  sweep(
    [
      [6.94, 34.5, 4.75],
      [7.15, 33.35, 5.33],
      [6.6, 32.83, 5.43],
    ],
    [0.36, 0.33, 0.06],
    MARBLE,
    { radial: 10, samples: 18 },
  );
  // 手背细腱从腕背进入指根，强调手与前臂的连续关系。
  for (let i = 0; i < 3; i++)
    sweep(
