    oval([s * 0.53, 58.09, 3.78], [0.2, 0.09, 0.1], "#8d9486");
    oval([s * 3.12, 58.7, 0.05], [0.51, 1.05, 0.66]);
    sweep(
      [
        [s * 3.25, 59.49, 0.47],
        [s * 3.49, 59.16, 0.53],
        [s * 3.44, 58.3, 0.45],
        [s * 3.2, 57.98, 0.4],
      ],
      [0.1, 0.16, 0.15, 0.06],
      MARBLE,
      { radial: 8, samples: 22 },
    );
    // 眼睑包住石雕眼球，眼睛不发光；眉压与暗缝负责庄严神情。
    oval([s * 1.42, 59.72, 2.88], [0.57, 0.235, 0.16], "#adaf9f");
    sweep(
      [
        [s * 0.72, 59.67, 3.01],
        [s * 1.34, 59.95, 3.18],
        [s * 2.08, 59.76, 2.7],
      ],
      [0.08, 0.17, 0.065],
      MARBLE,
      { radial: 10, samples: 22 },
    );
    sweep(
      [
        [s * 0.72, 59.63, 3.02],
        [s * 1.4, 59.48, 3.08],
        [s * 2.08, 59.75, 2.7],
      ],
      [0.065, 0.11, 0.04],
      MARBLE,
      { radial: 9, samples: 22 },
    );
    oval([s * 1.4, 59.72, 3.07], [0.11, 0.13, 0.036], "#768679");
    sweep(
      [
        [s * 0.46, 60.3, 3.29],
        [s * 1.34, 60.5, 3.33],
        [s * 2.35, 60.24, 2.64],
      ],
      [0.07, 0.19, 0.025],
      HAIR,
      { radial: 10, samples: 24, groove: 0.07 },
    );
    // 胡须前的口唇仍可辨认，鼻唇沟沉入须根。
    sweep(
      [
        [s * 0.59, 58.02, 3.66],
        [s * 1.02, 57.59, 3.61],
        [s * 1.19, 57.06, 3.51],
      ],
      [0.07, 0.1, 0.04],
      MARBLE,
      { samples: 20, radial: 8 },
    );
  }
  sweep(
    [
      [-0.99, 57.23, 3.54],
      [-0.38, 57.28, 3.78],
      [0, 57.2, 3.82],
      [0.38, 57.28, 3.78],
      [0.99, 57.23, 3.54],
    ],
    [0.05, 0.13, 0.11, 0.13, 0.05],
    "#b5b39f",
    { samples: 32, radial: 10 },
  );
  sweep(
    [
      [-0.91, 56.98, 3.6],
      [0, 56.9, 3.86],
      [0.91, 56.98, 3.6],
    ],
    [0.04, 0.21, 0.04],
    MARBLE,
    { samples: 24, radial: 10 },
  );

  // 卷须主面整体雕刻连续起伏，凹槽随波浪弯曲，避免管状须束之间的穿插。
  add(
    carvedLoft(
      [
        { y: 51.65, rx: 0.12, rz: 0.13, z: 3.03 },
