import * as THREE from "three";
import {
  MergeBucket,
  atlantisMaterials,
  cachedGeometry,
  paintStone,
  seededRandom,
} from "./atlantis_art_geometry.js";
import { buildPoseidon } from "./atlantis_art_poseidon.js";
import {
  createAtlantisUnderways,
  isAtlantisUnderwayReserved,
} from "./atlantis_underways.js";
import { createAtlantisTerrainMesh } from "./atlantis_terrain_mesh.js";
import { createAtlantisHarborRuins } from "./atlantis_exploration_harbor.js";
import { createAtlantisAgoraRuins } from "./atlantis_exploration_agora.js";
import { createAtlantisCityMarine } from "./atlantis_city_marine.js";
import { createAtlantisExplorationFurniture } from "./atlantis_exploration_furniture.js";
import { createAtlantisResidentialInteriors } from "./atlantis_residential_interiors.js";
import { createAtlantisPoseidonTemple } from "./atlantis_poseidon_temple.js";
import {
  POSEIDON_TEMPLE_SITE,
  isPoseidonTempleReserved,
} from "./atlantis_poseidon_site.js";
import { selectMarineFacades } from "./atlantis_marine_anchors.js";
import { ATLANTIS_EXCAVATION_SITES } from "./atlantis_terrain.js";
import { cityArchitecture } from "./atlantis_architecture.js";
import {
  ATLANTIS_CITY_BOUNDS,
  ATLANTIS_DISTRICTS,
  cityCoverage,
  cityLots,
} from "./atlantis_city_plan.js";

/**
 * 创建覆盖海域约70%的亚特兰蒂斯城邦，按真实海床逐街坊建造。
 * @param {THREE.Object3D} parent 场景父节点。
 * @param {{heightAt:function}} options 共享海床高度，不改动生存规则。
 * @returns {object} 场景、静态碰撞、地标、城区统计和生命周期接口。
 */
export function createAtlantisCity(parent, { heightAt } = {}) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error("Atlantis requires a scene and seabed height function");
  const root = new THREE.Group();
  root.name = "atlantis_city";
  parent.add(root);
  const materials = atlantisMaterials();
  const owned = new Set(),
    colliders = [],
    obstacles = [],
    landmarks = [],
    chunks = new Map(),
    lights = [];
  const random = seededRandom(9517);
  const records = [];
  let disposed = false;
  // 特殊台基先保留空间，避免普通住宅在稍后放入的神殿、圆亭或塔楼中被掩埋。
  const residentialReservations = [
    ...[-187, 187].map((x) => ({
      kind: "temple",
      x,
      z: -774,
      scale: 0.96,
      rotation: Math.PI / 2,
    })),
    ...[-177, 177].map((x) => ({
      kind: "rotunda",
      x,
      z: -944,
      scale: 0.85,
      rotation: 0,
    })),
    ...[-253, 253].map((x) => ({
      kind: "tower",
      x,
      z: -645,
      scale: 1.1,
      rotation: 0,
    })),
  ].map((r) => {
    const kit = cityArchitecture(r.kind),
      c = Math.abs(Math.cos(r.rotation)),
      s = Math.abs(Math.sin(r.rotation));
    return {
      ...r,
      width: (kit.width * c + kit.depth * s) * r.scale,
      depth: (kit.width * s + kit.depth * c) * r.scale,
    };
  });

  function chunkFor(x, z) {
    const cx = Math.floor((x + 300) / 150),
      cz = Math.floor((z + 1100) / 140),
      key = `${cx}:${cz}`;
    if (!chunks.has(key)) {
      const group = new THREE.Group();
      group.name = `city_district_${key}`;
      root.add(group);
      chunks.set(key, {
        group,
        batches: new Map(),
        center: new THREE.Vector3(cx * 150 - 225, 0, cz * 140 - 1030),
      });
    }
    return chunks.get(key);
  }
  function instance(
    geometry,
    material,
    x,
    y,
    z,
    { scale = [1, 1, 1], rotation = 0, color = null } = {},
  ) {
    const chunk = chunkFor(x, z),
      key = `${geometry.uuid}:${material.uuid}`;
    if (!chunk.batches.has(key))
      chunk.batches.set(key, { geometry, material, transforms: [] });
    chunk.batches.get(key).transforms.push({ x, y, z, scale, rotation, color });
  }
  function transformedCollider(c, x, y, z, scale, angle) {
    const sin = Math.sin(angle),
      cos = Math.cos(angle);
    const point = (p) => ({
      x: x + (p.x * cos + p.z * sin) * scale,
      y: y + p.y * scale,
      z: z + (-p.x * sin + p.z * cos) * scale,
    });
    if (c.type === "capsule")
      return { ...c, a: point(c.a), b: point(c.b), radius: c.radius * scale };
    const p = point(c),
      q = new THREE.Quaternion().setFromAxisAngle(
        new THREE.Vector3(0, 1, 0),
        angle,
      );
    if (c.rotation)
      q.multiply(
        new THREE.Quaternion(
          c.rotation.x,
          c.rotation.y,
          c.rotation.z,
          c.rotation.w,
        ),
      );
    const out = { ...c, ...p, rotation: { x: q.x, y: q.y, z: q.z, w: q.w } };
    if (c.halfSize)
      out.halfSize = {
        x: c.halfSize.x * scale,
        y: c.halfSize.y * scale,
        z: c.halfSize.z * scale,
      };
    if (c.axes)
      out.axes = {
        x: c.axes.x * scale,
        y: c.axes.y * scale,
        z: c.axes.z * scale,
      };
    return out;
  }
  const cube = cachedGeometry("city_foundation_cube_v2", () =>
    paintStone(new THREE.BoxGeometry(1, 1, 1), {
      base: "#a2b5b0",
      algaeAmount: 0.18,
    }),
  );
  function footprintHeights(x, z, w, d) {
    const heights = [];
    for (let ix = 0; ix <= 4; ix++)
      for (let iz = 0; iz <= 4; iz++)
        heights.push(heightAt(x + (ix / 4 - 0.5) * w, z + (iz / 4 - 0.5) * d));
    return { min: Math.min(...heights), max: Math.max(...heights) };
  }
  function foundation(x, z, w, d, top) {
    const low = footprintHeights(x, z, w, d).min - 1.8;
    const h = Math.max(1, top - low);
    instance(cube, materials.stone, x, (top + low) / 2, z, {
      scale: [w, h, d],
    });
    colliders.push({
      type: "box",
      kind: "city_foundation",
      x,
      y: (top + low) / 2,
      z,
      halfSize: { x: w / 2, y: h / 2, z: d / 2 },
    });
    // 连续基座用贴合的垂直扶壁与上缘压顶打破大片空白侧面。
    for (const sx of [-1, 1])
      for (let dz = -d / 2 + 3; dz < d / 2; dz += 9)
        instance(
          cube,
          materials.marble,
          x + sx * (w / 2 + 0.15),
          top - h * 0.46,
          z + dz,
          { scale: [0.7, h * 0.9, 1] },
        );
    instance(cube, materials.marble, x, top + 0.15, z, {
      scale: [w + 0.8, 0.35, d + 0.8],
    });
  }
  function place(
    kind,
    x,
    z,
    {
      scale = 1,
      rotation = 0,
      base = null,
      footing = true,
      allowReserved = false,
    } = {},
  ) {
    const kit = cityArchitecture(kind);
    const width =
      (Math.abs(Math.cos(rotation)) * kit.width +
        Math.abs(Math.sin(rotation)) * kit.depth) *
      scale;
    const depth =
      (Math.abs(Math.sin(rotation)) * kit.width +
        Math.abs(Math.cos(rotation)) * kit.depth) *
      scale;
    if (
      ["courtyard", "villa"].includes(kind) &&
      residentialReservations.some(
        (r) =>
          Math.abs(x - r.x) < (width + r.width) / 2 &&
          Math.abs(z - r.z) < (depth + r.depth) / 2,
      )
    )
      return null;
    if (
      isPoseidonTempleReserved(x, z, width, depth) ||
      (!allowReserved && isAtlantisUnderwayReserved(x, z, width, depth))
    )
      return null;
    const terrain = footprintHeights(x, z, width, depth);
    const y =
      kind === "pearl" ? terrain.max + 0.35 : (base ?? terrain.max + 0.8);
    if (kind === "pearl") {
      // 贝壳搁在自然礁石上，取整个壳体投影的最高海床，避免斜坡穿过下瓣。
      const rock = cachedGeometry("pearl_reef_base", () => {
        const g = new THREE.IcosahedronGeometry(1, 2);
        const p = g.attributes.position;
        for (let i = 0; i < p.count; i++) {
          const n = 1 + 0.055 * Math.sin(p.getX(i) * 19 + p.getZ(i) * 7);
          p.setXYZ(i, p.getX(i) * n, p.getY(i), p.getZ(i) * n);
        }
        g.computeVertexNormals();
        return paintStone(g, { base: "#647e77", algaeAmount: 0.45 });
      });
      const low = terrain.min - 1,
        top = y + 0.5;
      const axes = { x: width * 0.45, y: (top - low) / 2, z: depth * 0.45 };
      const centerY = (top + low) / 2;
      instance(rock, materials.pearlReef, x, centerY, z, {
        scale: [axes.x, axes.y, axes.z],
      });
      colliders.push({
        type: "ellipsoid",
        kind: "pearl_reef",
        x,
        y: centerY,
        z,
        axes,
      });
    }
    if (footing) foundation(x, z, width, depth, y);
    for (const part of kit.parts)
      instance(part.geometry, part.material, x, y, z, {
        scale: [scale, scale, scale],
        rotation,
      });
    for (const c of kit.colliders)
      colliders.push(transformedCollider(c, x, y, z, scale, rotation));
    obstacles.push({
      x,
      y: y + kit.height * scale * 0.4,
      z,
      radius: Math.max(width, depth) * 0.4,
    });
    records.push({
      kind,
      x,
      z,
      y,
      width,
      depth,
      height: kit.height * scale,
      scale,
      rotation,
    });
    return { x, y, z, kit };
  }
  function landmark(id, x, y, z) {
    landmarks.push({ id, position: new THREE.Vector3(x, y, z) });
  }
  function lamp(color, intensity, distance, x, y, z, fixed = false) {
    lights.push({
      position: new THREE.Vector3(x, y, z),
      color,
      intensity,
      distance,
      fixed,
    });
  }

  buildPavement(root, heightAt, owned, materials);
  // 中轴台阶顺海床逐级下降；横街和竞技广场仍开阔，不改变原有地形函数。
  for (const [from, to] of [
    [-124, -660],
    [-956, -1078],
  ]) {
    for (let z = from; z > to; z -= 2) {
      if (isPoseidonTempleReserved(0, z, 38, 2)) continue;
      if (Math.abs(((((z + 100) % 138) + 138) % 138) - 69) < 13) continue;
      const floor = footprintHeights(0, z, 38, 2);
      const top = floor.max + 0.28,
        bottom = floor.min - 0.5;
      instance(cube, materials.marble, 0, (top + bottom) / 2, z, {
        scale: [38, top - bottom, 2],
      });
      colliders.push({
        type: "box",
        kind: "city_avenue_step",
        x: 0,
        y: (top + bottom) / 2,
        z,
        halfSize: { x: 19, y: (top - bottom) / 2, z: 1 },
      });
    }
  }
  // 每个64×69m街坊都有两座不完全相同的建筑，留中央圣道与横向巷道。
  for (const lot of cityLots()) {
    if (isAtlantisUnderwayReserved(lot.x, lot.z)) continue;
    const outer = Math.abs(lot.x) > 215;
    const variants =
      lot.district === "harbor"
        ? ["courtyard", "villa"]
        : lot.district === "market"
          ? ["stoa", "courtyard"]
          : lot.district === "necropolis"
            ? ["courtyard", "villa"]
            : ["villa", "courtyard"];
    const a = place(variants[lot.row % 2], lot.x, lot.z + 15, {
      rotation: lot.x < 0 ? Math.PI / 2 : -Math.PI / 2,
      scale: outer ? 0.82 : 0.94,
    });
    place(
      (lot.row + Math.round(lot.x)) % 3 === 0
        ? "ruins"
        : variants[(lot.row + 1) % 2],
      lot.x + (lot.row % 2 ? 4 : -4),
      lot.z - 17,
      {
        rotation: lot.x < 0 ? Math.PI / 2 : -Math.PI / 2,
        scale: 0.7 + random() * 0.15,
      },
    );
    if ((lot.row + Math.round(lot.x)) % 3 === 0)
      place("amphora", lot.x + 18, lot.z, {
        footing: false,
        base: heightAt(lot.x + 18, lot.z) + 0.2,
        scale: 1.8,
      });
    if (a && !outer && lot.row % 3 === 0)
      lamp("#7eb8bd", 950, 80, a.x, a.y + 17, a.z);
  }
  // 外围城门与塔楼形成可辨认的轮廓线，城市向两侧伸展而非夹在内部岩脊之间。
  for (const z of [-175, -450, -645, -955])
    for (const x of [-253, 253])
      place("tower", x, z, { scale: z === -645 ? 1.1 : 0.85 });
  for (const [z, scale] of [
    [-190, 0.9],
    [-475, 1.12],
    [-630, 1.15],
    [-985, 0.8],
  ]) {
    const g = place("gateway", 0, z, { scale });
    landmark(z === -475 ? "grand_arch" : `gate_${-z}`, 0, g.y + 19 * scale, z);
    lamp("#d9bb89", 2100, 125, 0, g.y + 26 * scale, z);
  }
  for (const x of [-177, 177])
    for (const z of [-362, -575, -944])
      place("rotunda", x, z, { scale: z === -575 ? 1.1 : 0.85 });
  // 长途可见的方尖碑和成对柱列标出主轴，横街与街坊入口保持开放。
  for (let z = -125; z > -1080; z -= 35)
    for (const x of [-26, 26]) {
      if (z < -650 && z > -905) continue;
      place("column", x, z, {
        scale: z > -300 ? 0.65 : 0.95,
        footing: false,
        base: heightAt(x, z) + 0.35,
      });
    }
  for (const [x, z] of [
    [-78, -270],
    [78, -270],
    [-103, -555],
    [103, -555],
    [-109, -852],
    [109, -852],
  ])
    place("obelisk", x, z, { scale: z === -852 ? 1.35 : 1 });
  // 宏大王城由开阔竞技广场、两翼神殿及后方巨像构成，克拉肯原领地保持畅通。
  for (const x of [-187, 187]) {
    const t = place("temple", x, -774, {
      scale: 0.96,
      rotation: x < 0 ? Math.PI / 2 : -Math.PI / 2,
    });
    lamp("#edbf83", 4200, 165, t.x, t.y + 27, t.z);
  }
  const temple = createAtlantisPoseidonTemple(root, {
    heightAt,
    hostColliders: colliders,
    site: POSEIDON_TEMPLE_SITE,
  });
  colliders.push(...temple.colliders);
  landmarks.push(...temple.landmarks);
  records.push({
    kind: "poseidon_temple",
    x: 0,
    z: -911,
    y: POSEIDON_TEMPLE_SITE.templeFloorY,
    width: 130,
    depth: 100,
    height: 82,
    scale: 1,
    rotation: 0,
  });
  for (const source of temple.lightSources)
    lamp(
      source.color,
      source.intensity,
      source.distance,
      source.x,
      source.y,
      source.z,
    );
  buildArena(root, instance, colliders, heightAt, materials, cube);
  const arenaY = heightAt(0, -735) + 0.5;
  landmark("arena", 0, arenaY + 1, -735);
  landmark("entrance_district", 0, heightAt(0, -115) + 12, -115);
  landmark("colonnade", 0, heightAt(0, -550) + 16, -550);
  const statueScale = 1.55,
    origin = { x: 0, y: footprintHeights(0, -865, 42, 36).max + 1, z: -865 };
  foundation(0, -865, 42, 36, origin.y);
  const statueBucket = new MergeBucket();
  const statue = buildPoseidon(
    {
      add(geo, key, transform) {
        statueBucket.add(geo, key, {
          position: [
            origin.x + (transform?.position?.[0] || 0) * statueScale,
            origin.y + (transform?.position?.[1] || 0) * statueScale,
            origin.z + (transform?.position?.[2] || 0) * statueScale,
          ],
          scale: statueScale,
        });
      },
    },
    { x: 0, y: 0, z: 0 },
  );
  const statueGroup = new THREE.Group();
  statueGroup.name = "poseidon_monument";
  root.add(statueGroup);
  statueBucket.build(materials, statueGroup, owned);
  for (const c of statue.colliders)
    colliders.push(
      transformedCollider(c, origin.x, origin.y, origin.z, statueScale, 0),
    );
  const head = statue.headCenter
    .clone()
    .multiplyScalar(statueScale)
    .add(new THREE.Vector3(origin.x, origin.y, origin.z));
  const tip = statue.tridentTip
    .clone()
    .multiplyScalar(statueScale)
    .add(new THREE.Vector3(origin.x, origin.y, origin.z));
  landmark("poseidon_statue", head.x, head.y, head.z);
  landmark("poseidon_trident", tip.x, tip.y, tip.z);
  landmark("rear_shrine", 0, heightAt(0, -1025) + 18, -1025);
  lamp("#d8dec5", 9000, 210, -40, origin.y + 80, -825, true);
  lamp("#6fbbff", 3000, 170, tip.x, tip.y - 2, tip.z, true);
  place("rotunda", 0, -1032, { scale: 1.3 });

  const underways = createAtlantisUnderways(root, { heightAt });
  colliders.push(...underways.colliders);
  obstacles.push(...underways.obstacles);
  landmarks.push(...underways.landmarks);
  const exploration = createAtlantisHarborRuins(root, { heightAt });
  colliders.push(...exploration.colliders);
  landmarks.push(...exploration.landmarks);
  const agora = createAtlantisAgoraRuins(root, {
    heightAt,
    site: ATLANTIS_EXCAVATION_SITES.find(
      (site) => site.reservation === "agora_bridges",
    ),
    hostColliders: colliders,
  });
  colliders.push(...agora.colliders);
  landmarks.push(...agora.landmarks);
  for (const source of [...exploration.lightSources, ...agora.lightSources])
    lamp(
      source.color,
      source.intensity,
      source.distance,
      source.x,
      source.y,
      source.z,
    );

  // 贝珠柔光沿圣道和横街生长，避开建筑实体与中央战斗通道。
  const pearlSites = [];
  for (let z = -144; z > -1070; z -= 34) {
    if (z < -656 && z > -937) continue;
    for (const x of [-21, 21]) pearlSites.push([x, z]);
  }
  for (const z of [-290, -428, -566, -980])
    for (const x of [-215, -140, -95, 95, 140, 215]) pearlSites.push([x, z]);
  for (const z of [-684, -720, -756, -792, -827])
    for (const x of [-101, 101]) pearlSites.push([x, z]);
  for (const [x, z] of pearlSites) {
    if (
      records.some(
        (r) =>
          Math.abs(x - r.x) < r.width / 2 + 3 &&
          Math.abs(z - r.z) < r.depth / 2 + 3,
      )
    )
      continue;
    const t = place("pearl", x, z, {
      footing: false,
      base: heightAt(x, z) + 0.3,
      rotation: x < 0 ? -0.55 : 0.55,
    });
    if (t) lamp("#ffe3ab", 45, 58, t.x, t.y + 1.65, t.z);
  }

  for (const site of underways.records)
    for (const side of [-1, 1])
      for (const end of [-1, 1]) {
        const x = site.x + side * 26,
          z = site.z + end * 43;
        const t = place("pearl", x, z, {
          footing: false,
          base: heightAt(x, z) + 0.3,
          rotation: end > 0 ? 0 : Math.PI,
          allowReserved: true,
        });
        lamp("#ffe3ab", 45, 58, t.x, t.y + 1.65, t.z);
      }

  // 建造零散残件、柱鼓与陶罐，既有尺度参照，又不让大鱼卡在碎石碰撞中。
  const debris = cachedGeometry("city_rubble_v2", () => {
    const g = new THREE.IcosahedronGeometry(1, 0);
    return paintStone(g, { base: "#879c95", algaeAmount: 0.3 });
  });
  for (let i = 0; i < 700; i++) {
    const x = -266 + random() * 532,
      z = -110 - random() * 960;
    if (Math.abs(x) < 22 || isPoseidonTempleReserved(x, z, 6, 6)) continue;
    const s = 0.5 + random() * 1.8;
    instance(debris, materials.stone, x, heightAt(x, z) + s * 0.22, z, {
      scale: [s, s * 0.5, s * 1.35],
      rotation: random() * 6.28,
    });
  }
  const dummy = new THREE.Object3D();
  for (const chunk of chunks.values()) {
    for (const batch of chunk.batches.values()) {
      const mesh = new THREE.InstancedMesh(
        batch.geometry,
        batch.material,
        batch.transforms.length,
      );
      mesh.name = "atlantis_architecture_instances";
      batch.transforms.forEach((t, i) => {
        dummy.position.set(t.x, t.y, t.z);
        dummy.rotation.set(0, t.rotation, 0);
        dummy.scale.set(...t.scale);
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
      });
      mesh.computeBoundingBox();
      mesh.computeBoundingSphere();
      mesh.receiveShadow = true;
      mesh.castShadow = false;
      chunk.group.add(mesh);
      owned.add({ dispose: () => mesh.dispose() });
    }
    chunk.batches.clear();
  }
  // 陈设先占据实际空间，再让海洋生长避让家具；最终碰撞只在组装时合并。
  const harborSite = ATLANTIS_EXCAVATION_SITES[0];
  const facades = selectMarineFacades(colliders, {
    near: harborSite.entrance.top,
  });
  const furniture = createAtlantisExplorationFurniture(root, {
    heightAt,
    site: harborSite,
    hostColliders: colliders,
    facades,
  });
  colliders.push(...furniture.colliders);
  landmarks.push(...furniture.landmarks);
  const marine = createAtlantisCityMarine(root, {
    heightAt,
    site: harborSite,
    hostColliders: colliders,
    facades,
  });
  colliders.push(...marine.colliders);
  landmarks.push(...marine.landmarks);
  const agoraMarine = createAtlantisCityMarine(root, {
    heightAt,
    site: ATLANTIS_EXCAVATION_SITES.find(
      (site) => site.reservation === "agora_bridges",
    ),
    hostColliders: colliders,
    seed: 7129,
  });
  agoraMarine.root.name = "atlantis_agora_marine";
  colliders.push(...agoraMarine.colliders);
  landmarks.push(...agoraMarine.landmarks);
  const residential = createAtlantisResidentialInteriors(root, {
    records,
    heightAt,
    hostColliders: colliders,
  });
  colliders.push(...residential.colliders);
  landmarks.push(...residential.landmarks);
  // 固定数量动态点光复用，按玩家距离选最近灯位，避免全城数十盏灯进入每个着色器。
  const lightPool = Array.from({ length: 5 }, () => {
    const l = new THREE.PointLight(0xffffff, 0, 100, 2);
    root.add(l);
    return l;
  });
  const stats = {
    coverage: cityCoverage(),
    bounds: ATLANTIS_CITY_BOUNDS,
    districts: ATLANTIS_DISTRICTS.length,
    lots: cityLots().length,
    buildings: records.filter(
      (r) => !["column", "amphora", "obelisk", "pearl"].includes(r.kind),
    ).length,
    pearlHabitats: records.filter((r) => r.kind === "pearl").length,
    multilevelComplexes: underways.records.length,
    subterraneanSites: ATLANTIS_EXCAVATION_SITES.length,
    agora: agora.stats,
    marine: marine.stats,
    agoraMarine: agoraMarine.stats,
    furniture: furniture.stats,
    residential: residential.stats,
    temple: temple.stats,
    chunks: chunks.size,
    colliders: colliders.length,
  };
  root.userData.cityStats = stats;
  function update(time, dt, position, highQuality = true) {
    if (disposed) return;
    underways.update(time, dt, position, highQuality);
    exploration.update(time, dt, position, highQuality);
    agora.update(time, dt, position, highQuality);
    furniture.update(time, dt, position, highQuality);
    marine.update(time, dt, position, highQuality);
    agoraMarine.update(time, dt, position, highQuality);
    residential.update(time, dt, position, highQuality);
    temple.update(time, dt, position, highQuality);
    const reach = highQuality ? 350 : 275;
    for (const chunk of chunks.values())
      chunk.group.visible =
        !position ||
        Math.hypot(chunk.center.x - position.x, chunk.center.z - position.z) <
          reach;
    const fixed = lights.filter((l) => l.fixed);
    const nearby = position
      ? [...lights]
          .filter((l) => !fixed.includes(l))
          .sort(
            (a, b) =>
              a.position.distanceToSquared(position) -
              b.position.distanceToSquared(position),
          )
      : lights;
    const activeLights = [...fixed, ...nearby];
    lightPool.forEach((light, i) => {
      const source = activeLights[i];
      light.visible = !!source && (highQuality || i < 3);
      if (source) {
        light.position.copy(source.position);
        light.color.set(source.color);
        light.distance = source.distance;
        light.intensity =
          source.intensity * (0.96 + Math.sin(time * 0.8 + i) * 0.04);
      }
    });
    void dt;
  }
  update(0, 0, new THREE.Vector3(0, -18, 75));
  return {
    root,
    colliders,
    obstacles,
    landmarks,
    stats,
    buildings: records,
    underways,
    exploration,
    agora,
    furniture,
    marine,
    agoraMarine,
    residential,
    temple,
    update,
    dispose() {
      if (disposed) return;
      disposed = true;
      residential.dispose();
      temple.dispose();
      marine.dispose();
      agoraMarine.dispose();
      furniture.dispose();
      exploration.dispose();
      agora.dispose();
      underways.dispose();
      parent.remove(root);
      for (const resource of owned) resource.dispose();
      owned.clear();
      root.clear();
    },
  };
}

/** 铺装跟随共享斜坡；每街区单独网格，路幅、广场与房基共同组成连续城市。 */
function buildPavement(root, heightAt, owned, materials) {
  const bounds = ATLANTIS_CITY_BOUNDS;
  for (let z = bounds.minZ; z < bounds.maxZ; z += 140)
    for (let x = bounds.minX; x < bounds.maxX; x += 137.5) {
      const w = Math.min(137.5, bounds.maxX - x),
        d = Math.min(140, bounds.maxZ - z);
      const geo = createAtlantisTerrainMesh({
        minX: x,
        maxX: x + w,
        minZ: z,
        maxZ: z + d,
        segmentsX: 16,
        segmentsZ: 20,
        heightAt,
        offset: 0.22,
      });
      const p = geo.attributes.position,
        colors = new Float32Array(p.count * 3),
        uv = geo.attributes.uv;
      for (let i = 0; i < p.count; i++) {
        const px = p.getX(i),
          pz = p.getZ(i);
        p.setY(i, heightAt(px, pz) + 0.22);
        const avenue = Math.abs(px) < 20;
        const cross = Math.abs(((((pz + 100) % 138) + 138) % 138) - 69) < 13;
        const c = new THREE.Color(avenue || cross ? "#afc2bc" : "#758e8d");
        c.multiplyScalar(
          0.94 + 0.035 * Math.cos(px * 0.4) * Math.sin(pz * 0.35),
        );
        c.toArray(colors, i * 3);
        uv.setXY(i, px / 16, pz / 16);
      }
      geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
      geo.computeBoundingSphere();
      owned.add(geo);
      const mesh = new THREE.Mesh(geo, materials.stone);
      mesh.name = "city_paved_district";
      mesh.receiveShadow = true;
      root.add(mesh);
    }
}

/** 竞技场沿真实坡面铺设，侧面层层看台，不用悬空整块方盒垫起整个王城。 */
function buildArena(root, instance, colliders, heightAt, materials, cube) {
  const ringParts = [];
  for (let i = 0; i < 80; i++) {
    const a = (i / 80) * Math.PI * 2,
      b = ((i + 1) / 80) * Math.PI * 2;
    for (const radius of [48, 71, 94]) {
      const r0 = radius - 0.23,
        r1 = radius + 0.23;
      const coords = [
        [Math.cos(a) * r0, Math.sin(a) * r0 - 735],
        [Math.cos(b) * r0, Math.sin(b) * r0 - 735],
        [Math.cos(a) * r1, Math.sin(a) * r1 - 735],
        [Math.cos(b) * r1, Math.sin(b) * r1 - 735],
      ];
      const geo = new THREE.BufferGeometry();
      const vertices = [];
      for (const j of [0, 1, 2, 1, 3, 2]) {
        const [x, z] = coords[j];
        vertices.push(x, heightAt(x, z) + 0.46, z);
      }
      geo.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(vertices, 3),
      );
      geo.computeVertexNormals();
      ringParts.push(geo);
    }
  }
  // 环形浅浮雕使用独立一次性几何，生命周期交给其父节点清理。
  const bucket = new MergeBucket();
  for (const g of ringParts) {
    bucket.add(g, "guideTeal");
    g.dispose();
  }
  const owned = new Set();
  bucket.build(materials, root, owned);
  root.userData.arenaResources = owned;
  // 并入父场景的释放事件，保持所有实例重开后无遗留。
  root.addEventListener("removed", () => {
    for (const r of owned) r.dispose();
    owned.clear();
  });
  for (const side of [-1, 1])
    for (let row = 0; row < 4; row++)
      for (let i = 0; i < 8; i++) {
        const z = -684 - i * 14,
          x = side * (111 + row * 6.3),
          top = heightAt(x, z) + 2 + row * 2.3,
          h = 3 + row * 2.3;
        instance(cube, materials.marble, x, top - h / 2, z, {
          scale: [5.8, h, 13],
        });
        colliders.push({
          type: "box",
          kind: "arena_seat",
          x,
          y: top - h / 2,
          z,
          halfSize: { x: 2.9, y: h / 2, z: 6.5 },
        });
      }
}

atlantis_city_marine.js.source:
import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import {
  cachedGeometry,
  loftGeometry,
  seededRandom,
  tubeGeometry,
} from "./atlantis_art_geometry.js";
import {
  addLeafDetail,
  addSurfaceDetail,
  clusterInstances,
  ribbonGeometry,
  seaFanGeometry,
} from "./ocean_visuals.js";
import { ATLANTIS_EXCAVATION_SITES } from "./atlantis_terrain.js";

/**
 * 亚特兰蒂斯城市海洋殖民切片:冷水分枝珊瑚、层叠板状海绵、海扇、海葵与
 * 克制的漂浮植被,有根附着于砌缝、断檐、台面与厅室地面。
 * 当前切片覆盖:港口下厅内部(含竖井缘与柱列)、入口坡道/台阶两侧、
 * 港区一段街区立面。所有布置由 ATLANTIS_EXCAVATION_SITES 元数据、
 * 宿主碰撞(扫墙)与立面锚点驱动,不改动任何既有模块。
 * 风格化的海洋景观,不作生物复原宣称;不新增猎物物种,不影响战斗。
 */

// 原型几何跨场景缓存；材质与动画时钟归每次 create 所有，暂停或销毁一个
// 切片不会改变其他切片。相同着色器仍通过程序缓存复用 GPU 程序。

/** 与 atlantis_art_geometry 内部相同的雾减免注入,深海雾中剪影与城市一致。 */
function applyFogRelief(material, relief) {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous?.call(material, shader, renderer);
    shader.uniforms.atlFogRelief = { value: relief };
    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <fog_pars_fragment>",
        "#include <fog_pars_fragment>\nuniform float atlFogRelief;",
      )
      .replace(
        "#include <fog_fragment>",
        `#ifdef USE_FOG
        #ifdef FOG_EXP2
          float atlFogFactor = 1.0 - exp( - fogDensity * fogDensity * vFogDepth * vFogDepth );
        #else
          float atlFogFactor = smoothstep( fogNear, fogFar, vFogDepth );
        #endif
        gl_FragColor.rgb = mix( gl_FragColor.rgb, fogColor, atlFogFactor * atlFogRelief );
        #endif`,
      );
  };
}

/** 只摆动植被上端,根部保持锚固;相位来自实例平移,避免整片同相摇摆。 */
function addSway(material, strength, time) {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous?.call(material, shader, renderer);
    shader.uniforms.marineTime = time;
    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        "#include <common>\nuniform float marineTime;",
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
        float marinePhase = 0.0;
        #ifdef USE_INSTANCING
          marinePhase = instanceMatrix[3].x*0.21+instanceMatrix[3].z*0.13;
        #endif
        transformed.x += sin(marineTime*0.6+marinePhase+position.y)*pow(max(0.0,position.y),2.0)*${strength.toFixed(3)};`,
      );
  };
}

/**
 * 当前切片拥有的材质集，切片内批次共享，dispose 时释放。
 * 颜色全部来自顶点色/实例色,材质本体保持浅灰白便于多物种复用;
 * 每个材质的着色器组合(表面细节/摇曳/叶面/雾减免)有独立缓存键。
 */
function marineMaterials(time) {
  const coral = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.82,
    metalness: 0.02,
  });
  addSurfaceDetail(coral, "coral", 1.35);
  applyFogRelief(coral, 0.9);
  coral.customProgramCacheKey = () => "marine_coral_v1";
  const sponge = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.88,
    metalness: 0.02,
  });
  addSurfaceDetail(sponge, "coral", 0.85);
  applyFogRelief(sponge, 0.9);
  sponge.customProgramCacheKey = () => "marine_sponge_v1";
  const fan = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.72,
    metalness: 0.03,
    side: THREE.DoubleSide,
  });
  addSway(fan, 0.017, time);
  applyFogRelief(fan, 0.86);
  fan.customProgramCacheKey = () => "marine_fan_v1";
  const anemone = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.66,
    metalness: 0.02,
  });
  addSurfaceDetail(anemone, "coral", 0.55);
  applyFogRelief(anemone, 0.9);
  anemone.customProgramCacheKey = () => "marine_anemone_v1";
  const kelp = new THREE.MeshStandardMaterial({
    color: "#dce8e2",
    vertexColors: true,
    roughness: 0.9,
    metalness: 0.02,
    side: THREE.DoubleSide,
  });
  addLeafDetail(kelp);
  addSway(kelp, 0.11, time);
  applyFogRelief(kelp, 0.9);
  kelp.customProgramCacheKey = () => "marine_kelp_v1";
  return { coral, sponge, fan, anemone, kelp };
}

/*********************************************
 * 顶点着色工具:有机体的基色、尖端渐色、根部附着垫
 *********************************************/

/** 按高度比例在两种颜色间渐变,并做低频深浅起伏;写入 color 属性。 */
function paintGradient(geometry, { bottom, top, seed = 1, darkenDown = 0.72 }) {
  const position = geometry.attributes.position;
  geometry.computeBoundingBox();
  const min = geometry.boundingBox.min.y,
    span = Math.max(1e-5, geometry.boundingBox.max.y - min);
  const low = new THREE.Color(bottom),
    high = new THREE.Color(top),
    color = new THREE.Color();
  const colors = new Float32Array(position.count * 3);
  const normal = geometry.attributes.normal;
  for (let i = 0; i < position.count; i += 1) {
    const t = (position.getY(i) - min) / span;
    color.copy(low).lerp(high, t * t * (3 - 2 * t));
    const grain =
      0.86 +
      0.14 *
        Math.sin(
          position.getX(i) * 6.1 +
            position.getZ(i) * 5.3 +
            seed * 3.7 +
            t * 9.4,
        );
    color.multiplyScalar(grain);
    if (normal && normal.getY(i) < -0.3) color.multiplyScalar(darkenDown);
    colors[i * 3] = color.r;
    colors[i * 3 + 1] = color.g;
    colors[i * 3 + 2] = color.b;
  }
  geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  return geometry;
}

/** 附着根垫:压扁的侵蚀丘,把殖民体视觉锚进砌缝/台面,颜色贴近宿主石材。 */
function rootPad(radius, seed) {
  const g = new THREE.IcosahedronGeometry(1, 1);
  const p = g.attributes.position;
  for (let i = 0; i < p.count; i += 1) {
    const n =
      1 +
      0.16 * Math.sin(p.getX(i) * 9 + seed) * Math.cos(p.getZ(i) * 7 - seed);
    p.setXYZ(
      i,
      p.getX(i) * n * radius,
      p.getY(i) * 0.14 * radius,
      p.getZ(i) * n * radius,
    );
  }
  g.computeVertexNormals();
  const colors = new Float32Array(p.count * 3);
  const base = new THREE.Color("#6d7f78"),
    algae = new THREE.Color("#486a55"),
    color = new THREE.Color();
  for (let i = 0; i < p.count; i += 1) {
    color
      .copy(base)
      .lerp(algae, 0.3 + 0.3 * Math.sin(i * 1.7 + seed))
      .multiplyScalar(0.8 + 0.2 * Math.sin(i * 2.3 + seed * 2));
    colors[i * 3] = color.r;
    colors[i * 3 + 1] = color.g;
    colors[i * 3 + 2] = color.b;
  }
  g.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  return g;
}

/** 合并带 position/normal/uv/color 的部件为单几何(全部转非索引)。 */
function mergeParts(parts) {
  const ready = parts.map((g) => {
    const geometry = g.index ? g.toNonIndexed() : g;
    if (!geometry.attributes.uv) {
      const count = geometry.attributes.position.count;
      geometry.setAttribute(
        "uv",
        new THREE.BufferAttribute(new Float32Array(count * 2), 2),
      );
    }
    if (!geometry.attributes.color) {
      const count = geometry.attributes.position.count;
      const white = new Float32Array(count * 3).fill(1);
      geometry.setAttribute("color", new THREE.BufferAttribute(white, 3));
    }
    for (const name of Object.keys(geometry.attributes))
      if (!["position", "normal", "uv", "color"].includes(name))
        geometry.deleteAttribute(name);
    return geometry;
  });
  const merged = mergeGeometries(ready, false);
  for (const geometry of ready) geometry.dispose();
  for (const g of parts) if (!ready.includes(g)) g.dispose();
  merged.computeBoundingSphere();
  return merged;
}

/*********************************************
 * 物种原型几何(模块级缓存;每个原型含根垫)
 *********************************************/

/**
 * 冷水分枝珊瑚群落:主干分叉两代,末端带膨大的珊瑚虫球;
 * 沿骨架由象牙白过渡到玫瑰尖,根部压在石色附着垫上。
 */
function branchingCoralGeometry(variant) {
  return cachedGeometry(`marine_branching_coral_v${variant}`, () => {
    const random = seededRandom(5300 + variant * 17);
    const parts = [];
    const tips = [];
    const grow = (from, yaw, tilt, length, radius, depth) => {
      const mid = from
        .clone()
        .addScaledVector(
          new THREE.Vector3(
            Math.sin(yaw) * Math.sin(tilt),
            Math.cos(tilt),
            Math.cos(yaw) * Math.sin(tilt),
          ),
          length * 0.5,
        );
      mid.x += (random() - 0.5) * length * 0.16;
      mid.z += (random() - 0.5) * length * 0.16;
      const end = from
        .clone()
        .addScaledVector(
          new THREE.Vector3(
            Math.sin(yaw) * Math.sin(tilt),
            Math.cos(tilt),
            Math.cos(yaw) * Math.sin(tilt),
          ),
          length,
        );
      parts.push(
        tubeGeometry(
          null,
          [from, mid, end],
          [radius, radius * 0.78, radius * 0.5],
          { radial: 6, samples: 5 },
        ),
      );
      if (depth <= 0) {
        tips.push(end);
        return;
      }
      for (let c = 0; c < 2; c += 1) {
        const branchYaw = yaw + (c ? 1 : -1) * (0.5 + random() * 0.45);
        const branchTilt = Math.min(1.25, tilt + 0.35 + random() * 0.4);
        grow(
          end,
          branchYaw + (random() - 0.5) * 0.5,
          branchTilt,
          length * (0.62 + random() * 0.14),
          radius * 0.58,
          depth - 1,
        );
      }
    };
    // 两到三股骨架,剪影互不相同。
    const trunks = variant % 2 === 0 ? 2 : 3;
    for (let t = 0; t < trunks; t += 1) {
      const yaw = (t / trunks) * Math.PI * 2 + random() * 0.8;
      grow(
        new THREE.Vector3(Math.cos(yaw) * 0.1, 0.12, Math.sin(yaw) * 0.1),
        yaw,
        0.12 + random() * 0.3,
        0.85 + random() * 0.3,
        0.16 - t * 0.02,
        2,
      );
    }
    for (const tip of tips) {
      const polyp = new THREE.IcosahedronGeometry(0.055, 0);
      polyp.translate(tip.x, tip.y, tip.z);
      parts.push(polyp);
    }
    parts.push(rootPad(0.34, variant * 3 + 1));
    const geometry = mergeParts(parts);
    return paintGradient(geometry, {
      bottom: "#ce6958",
      top: "#ffba8e",
      seed: variant * 11 + 3,
      darkenDown: 0.75,
    });
  });
}

/** 层叠板状海绵:波浪边圆盘层叠错落,顶部点缀两支带唇口的管状海绵。 */
