/*********************************************
 * 布置引擎:避让体、宿主墙面扫描、宿主重叠剔除
 *********************************************/

// 避让体:竖井、回转区、两条路线走廊、台阶通道、南门走廊一律不放置。
function keepOuts(site) {
  const zones = [];
  const shaft = site.shaft;
  zones.push({
    minX: shaft.minX - 2,
    maxX: shaft.maxX + 2,
    minZ: shaft.minZ - 2,
    maxZ: shaft.maxZ + 2,
    minY: site.levels[1].floorY - 1,
    maxY: shaft.topY + 8,
  });
  const turn = site.turningCircle;
  // 回转净区只约束游泳平面(turn.y)上下各 8m;厅底植被在其下方十余米。
  zones.push({
    circle: { x: turn.x, z: turn.z, radius: turn.clearRadius + 1 },
    minY: turn.y - 8,
    maxY: turn.y + 8,
  });
  for (const route of site.routes ?? [])
    for (let i = 0; i < route.waypoints.length - 1; i += 1)
      zones.push({
        segment: [route.waypoints[i], route.waypoints[i + 1]],
        radius: 8.5,
      });
  const stair = site.entrance;
  zones.push({
    tag: "stair",
    segment: [
      { x: stair.top.x, y: stair.top.y + 2, z: stair.top.z - 4 },
      { x: stair.bottom.x, y: stair.bottom.y + 2, z: stair.bottom.z + 4 },
    ],
    radius: stair.clearWidth / 2 + 0.6,
  });
  const portal = site.secondExit;
  zones.push({
    minX: portal.minX - 2.5,
    maxX: portal.maxX + 2.5,
    minY: portal.sillY - 3,
    maxY: portal.topY + 3,
    minZ: portal.z - 7,
    maxZ: portal.z + 7,
  });
  return zones;
}

function blockedByKeepOut(zones, x, y, z, margin = 0, skipTag = null) {
  for (const zone of zones) {
    if (zone.tag && zone.tag === skipTag) continue;
    if (zone.circle) {
      if (y < zone.minY || y > zone.maxY) continue;
      if (
        Math.hypot(x - zone.circle.x, z - zone.circle.z) <
        zone.circle.radius + margin
      )
        return true;
      continue;
    }
    if (zone.segment) {
      const [a, b] = zone.segment;
      const abx = b.x - a.x,
        aby = b.y - a.y,
        abz = b.z - a.z;
      const length2 = abx * abx + aby * aby + abz * abz;
      const t = Math.max(
        0,
        Math.min(
          1,
          ((x - a.x) * abx + (y - a.y) * aby + (z - a.z) * abz) / length2,
        ),
      );
      const dx = x - (a.x + abx * t),
        dy = y - (a.y + aby * t),
        dz = z - (a.z + abz * t);
      if (Math.hypot(dx, dy, dz) < zone.radius + margin) return true;
      continue;
    }
    if (
      x > zone.minX - margin &&
      x < zone.maxX + margin &&
      z > zone.minZ - margin &&
      z < zone.maxZ + margin &&
      y > zone.minY - margin &&
      y < zone.maxY + margin
    )
      return true;
  }
  return false;
}

/**
 * 放置点是否撞进宿主实体(既有家具、贝珠壁龛、倒柱、墙体):
 * 轴对齐 Minkowski 测试;站在盒顶面(baseY 不低于盒顶 0.3m)不算相交。
 */
function overlapsHost(hostColliders, x, baseY, topY, z, halfX, halfZ) {
  for (const c of hostColliders ?? []) {
    if (c.type === "box") {
      if (c.rotation) continue;
      const cMinY = c.y - c.halfSize.y,
        cMaxY = c.y + c.halfSize.y;
      if (baseY >= cMaxY - 0.3) continue; // 立于其顶面
      if (
        Math.abs(x - c.x) < c.halfSize.x + halfX &&
        Math.abs(z - c.z) < c.halfSize.z + halfZ &&
        baseY < cMaxY - 0.05 &&
        topY > cMinY + 0.05
      )
        return true;
    } else if (c.type === "capsule") {
      const capMinY = Math.min(c.a.y, c.b.y),
        capMaxY = Math.max(c.a.y, c.b.y);
      if (baseY >= capMaxY - 0.3) continue;
      if (topY < capMinY + 0.05) continue;
      const reach = c.radius + Math.max(halfX, halfZ);
      const abx = c.b.x - c.a.x,
        aby = c.b.y - c.a.y,
        abz = c.b.z - c.a.z;
      const length2 = abx * abx + aby * aby + abz * abz || 1e-6;
      const midY = (baseY + topY) / 2;
      const t = Math.max(
        0,
        Math.min(
          1,
          ((x - c.a.x) * abx + (midY - c.a.y) * aby + (z - c.a.z) * abz) /
            length2,
        ),
      );
      if (
        Math.hypot(
          x - (c.a.x + abx * t),
          midY - (c.a.y + aby * t),
          z - (c.a.z + abz * t),
        ) < reach
      )
        return true;
    }
  }
  return false;
}

/**
 * 从宿主碰撞扫描厅室内墙面:取与基坑相交的无旋转盒,找出朝向坑内的
 * 竖直面,返回可附着的墙带(法线、所在平面、沿墙区间、高度区间)。
 * 扫描失败时回退到由 site.bounds 与墙体常规厚度推导的四面内墙。
 */
function scanWallBands(hostColliders, site) {
  const pit = site.bounds;
  const cx = (pit.minX + pit.maxX) / 2,
    cz = (pit.minZ + pit.maxZ) / 2;
  const y0 = site.levels[1].floorY,
    y1 = site.levels[0].ceilingY;
  const minY = (c) => c.y - c.halfSize.y;
  const maxY = (c) => c.y + c.halfSize.y;
  const bands = [];
  for (const c of hostColliders ?? []) {
    if (c.type !== "box" || c.rotation) continue;
    if (typeof c.kind !== "string" || !c.kind.endsWith("_ruin_masonry"))
      continue;
    const minX = c.x - c.halfSize.x,
      maxX = c.x + c.halfSize.x,
      minZ = c.z - c.halfSize.z,
      maxZ = c.z + c.halfSize.z;
    if (
      maxX < pit.minX ||
      minX > pit.maxX ||
      maxZ < pit.minZ ||
      minZ > pit.maxZ
    )
      continue;
    const faces = [
      {
        axis: "x",
        plane: maxX,
        normal: [1, 0],
        toward: maxX <= cx,
        span: [minZ, maxZ],
      },
      {
        axis: "x",
        plane: minX,
        normal: [-1, 0],
        toward: minX >= cx,
        span: [minZ, maxZ],
      },
      {
        axis: "z",
        plane: maxZ,
        normal: [0, 1],
        toward: maxZ <= cz,
        span: [minX, maxX],
      },
      {
        axis: "z",
        plane: minZ,
        normal: [0, -1],
        toward: minZ >= cz,
        span: [minX, maxX],
      },
    ];
    for (const face of faces) {
      if (!face.toward) continue;
      // 墙面必须落在基坑内缘附近,且盒子高度跨越大半个厅高。
      if (
        face.axis === "x" &&
        (face.plane < pit.minX - 0.5 || face.plane > pit.maxX + 0.5)
      )
        continue;
      if (
        face.axis === "z" &&
        (face.plane < pit.minZ - 0.5 || face.plane > pit.maxZ + 0.5)
      )
        continue;
      const height = Math.min(maxY(c), y1) - Math.max(minY(c), y0);
      if (height < 8) continue;
      bands.push({
        axis: face.axis,
        plane: face.plane,
        normal: face.normal,
        span: face.span,
        y0: Math.max(minY(c), y0),
        y1: Math.min(maxY(c), y1),
      });
    }
  }
  if (bands.length >= 3) return bands;
  // 回退:按港湾厅堂墙体合同(北/西墙 4.5m,南/东墙 2.5m)推内面。
  return [
    {
      axis: "z",
      plane: pit.maxZ - 4.5,
      normal: [0, -1],
      span: [pit.minX + 4.5, pit.maxX - 2.5],
      y0,
      y1,
    },
    {
      axis: "z",
      plane: pit.minZ + 2.5,
      normal: [0, 1],
      span: [pit.minX + 4.5, pit.maxX - 2.5],
      y0,
      y1,
    },
    {
      axis: "x",
      plane: pit.minX + 4.5,
      normal: [1, 0],
      span: [pit.minZ + 2.5, pit.maxZ - 4.5],
      y0,
      y1,
    },
    {
      axis: "x",
      plane: pit.maxX - 2.5,
      normal: [-1, 0],
      span: [pit.minZ + 2.5, pit.maxZ - 4.5],
      y0,
      y1,
    },
  ];
}

/** 放置记录:每物种一组 {position, quaternion, scale, tint}。 */
class PlacementSet {
  constructor() {
    this.byKind = new Map();
  }
  add(kind, position, quaternion, scale, tint) {
    if (!this.byKind.has(kind)) this.byKind.set(kind, []);
    const placement = { position, quaternion, scale, tint };
    this.byKind.get(kind).push(placement);
    return placement;
  }
  count() {
    let total = 0;
    for (const list of this.byKind.values()) total += list.length;
    return total;
  }
}

const UP = new THREE.Vector3(0, 1, 0);
/** 让 +Y 贴合法线方向的姿态(墙面附着时根系朝墙、冠部朝外),roll 绕自身轴。 */
function orientationFromNormal(nx, ny, nz, roll = 0) {
  const normal = new THREE.Vector3(nx, ny, nz).normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(UP, normal);
  if (roll) q.multiply(new THREE.Quaternion().setFromAxisAngle(UP, roll));
  return q;
}

/*********************************************
 * 分区布置:下厅、柱列、竖井缘与屋面、入口台阶、街区立面
 *********************************************/

function planLowerHall(
  set,
  site,
  wallBands,
  zones,
  hostColliders,
  heightAt,
  random,
) {
  const lower = site.levels[1],
    upper = site.levels[0];
  const pit = site.bounds;
  const inset = {
    minX: pit.minX + 5.2,
    maxX: pit.maxX - 3.4,
    minZ: pit.minZ + 3.4,
    maxZ: pit.maxZ - 5.4,
  };
  // 地面周缘带:珊瑚与海绵贴墙脚散布,回转区、路线与既有家具由避让兜底。
  const floorSpots = 26;
  for (let i = 0; i < floorSpots; i += 1) {
    const side = i % 4;
    const t = random();
    let x, z;
    if (side === 0) {
      x = inset.minX + 0.6 + random() * 1.6;
      z = inset.minZ + t * (inset.maxZ - inset.minZ);
    } else if (side === 1) {
      x = inset.maxX - 0.6 - random() * 1.6;
      z = inset.minZ + t * (inset.maxZ - inset.minZ);
    } else if (side === 2) {
      z = inset.minZ + 0.6 + random() * 1.6;
      x = inset.minX + t * (inset.maxX - inset.minX);
    } else {
      z = inset.maxZ - 0.6 - random() * 1.6;
      x = inset.minX + t * (inset.maxX - inset.minX);
    }
    if (blockedByKeepOut(zones, x, lower.floorY + 1, z, 0.5)) continue;
    if (
      overlapsHost(
        hostColliders,
        x,
        lower.floorY,
        lower.floorY + 2.6,
        z,
        1.0,
        1.0,
      )
    )
      continue;
    const pick = random();
    const kind =
      pick < 0.34
        ? "coral"
        : pick < 0.62
          ? "sponge"
          : pick < 0.85
            ? "anemone"
            : "kelp";
    const scale =
      kind === "coral" ? 0.9 + random() * 0.9 : 0.7 + random() * 0.8;
    const placement = set.add(
      kind,
      new THREE.Vector3(x, lower.floorY - 0.04, z),
      orientationFromNormal(0, 1, 0, random() * Math.PI * 2),
      scale,
      null,
    );
    // 保留实际实例记录，装配原型变体后按真实几何范围生成碰撞。
    placement.solid = (kind === "coral" || kind === "sponge") && scale > 1.15;
  }
  // 墙面砌缝带:海扇垂直墙面向厅内展开,海绵与小型海葵咬合同一灰缝。
  for (const band of wallBands) {
    const length = band.span[1] - band.span[0];
    const fans = Math.max(2, Math.round(length / 9));
    for (let i = 0; i < fans; i += 1) {
      const along = THREE.MathUtils.clamp(
        band.span[0] + ((i + 0.5) / fans) * length + (random() - 0.5) * 2.4,
        band.span[0] + Math.min(0.35, length / 4),
        band.span[1] - Math.min(0.35, length / 4),
      );
      const levelPick = random();
      const desiredY =
        levelPick < 0.55
          ? lower.floorY + 1.2 + random() * 6
          : levelPick < 0.8
            ? lower.floorY + 10.5 + random() * 3.5 // 盲拱线脚上下一带
            : upper.floorY + 1 + random() * 4;
      const x = band.axis === "x" ? band.plane + band.normal[0] * 0.12 : along;
      const z = band.axis === "z" ? band.plane + band.normal[1] * 0.12 : along;
      // 实墙下沿与坑缘过渡地形共同限定附着高度，不能把整座厅堂的地板
      // 标高套在门洞侧墙或坡缘上。抖动也不能越过实际墙面端点。
      const y = Math.max(desiredY, band.y0 + 0.3, heightAt(x, z) + 0.3);
      if (y > band.y1 - 1) continue;
      if (blockedByKeepOut(zones, x, y, z, 1.2)) continue;
      set.add(
        "fan",
        new THREE.Vector3(x, y, z),
        orientationFromNormal(
          band.normal[0],
          0.25,
          band.normal[1],
          (random() - 0.5) * 0.5,
        ),
        1.5 + random() * 1.3,
        null,
      );
      if (random() < 0.55) {
        const desiredSY = y - 0.9 - random() * 1.2;
        const smallAlong = THREE.MathUtils.clamp(
          along + (random() - 0.5) * 2,
          band.span[0] + Math.min(0.25, length / 4),
          band.span[1] - Math.min(0.25, length / 4),
        );
        const sx =
          band.axis === "x" ? band.plane + band.normal[0] * 0.1 : smallAlong;
        const sz =
          band.axis === "z" ? band.plane + band.normal[1] * 0.1 : smallAlong;
        const sy = Math.max(desiredSY, band.y0 + 0.2, heightAt(sx, sz) + 0.2);
        if (sy < band.y1 - 0.5 && !blockedByKeepOut(zones, sx, sy, sz, 1.0))
          set.add(
            random() < 0.6 ? "wallSponge" : "wallAnemone",
            new THREE.Vector3(sx, sy, sz),
            orientationFromNormal(
              band.normal[0],
              0.1,
              band.normal[1],
              random() * Math.PI * 2,
            ),
            0.45 + random() * 0.4,
            null,
          );
      }
    }
  }
}

function planColumns(set, site, hostColliders, zones, random) {
  const lower = site.levels[1];
  const columns = (hostColliders ?? []).filter(
    (c) =>
      c.type === "capsule" &&
      c.kind === "harbor_ruin_column" &&
      c.a.y < c.b.y &&
      c.a.x >= site.bounds.minX &&
      c.a.x <= site.bounds.maxX &&
      c.a.z >= site.bounds.minZ &&
      c.a.z <= site.bounds.maxZ,
  );
  for (const column of columns) {
    const x = column.a.x,
      z = column.a.z,
      radius = column.radius;
    const floorY = column.a.y - radius;
    const onLower = Math.abs(floorY - lower.floorY) < 1;
    // 柱脚一圈海葵与小型海绵,不占柱间水道。
    const ring = 3 + Math.floor(random() * 2);
    for (let i = 0; i < ring; i += 1) {
      const a = random() * Math.PI * 2;
      const px = x + Math.cos(a) * (radius + 0.5),
        pz = z + Math.sin(a) * (radius + 0.5);
      if (blockedByKeepOut(zones, px, floorY + 1, pz, 0.4)) continue;
      set.add(
        random() < 0.6 ? "anemone" : "sponge",
        new THREE.Vector3(px, floorY - 0.03, pz),
        orientationFromNormal(0, 1, 0, random() * Math.PI * 2),
        0.55 + random() * 0.35,
        null,
      );
    }
    // 柱身 40%~65% 高度一张海扇,像从凹槽里长出。
    if (random() < (onLower ? 0.85 : 0.55)) {
      const y = floorY + (column.b.y - column.a.y) * (0.45 + random() * 0.2);
      const a = random() * Math.PI * 2;
      const nx = Math.cos(a),
        nz = Math.sin(a);
      const px = x + nx * (radius + 0.1),
        pz = z + nz * (radius + 0.1);
      if (!blockedByKeepOut(zones, px, y, pz, 1.2))
        set.add(
          "fan",
          new THREE.Vector3(px, y, pz),
          orientationFromNormal(nx, 0.3, nz, (random() - 0.5) * 0.4),
          1.2 + random() * 0.9,
          null,
        );
    }
  }
}

function planShaftRim(set, site, zones, random, hostColliders) {
  const shaft = site.shaft;
  const upper = site.levels[0];
  // 在实际楼板顶面种植，不能把另一种遗迹的井缘尺寸当作实心屋面。
  const supported = (x, y, z) =>
    hostColliders.some(
      (c) =>
        c.type === "box" &&
        !c.rotation &&
        Math.abs(c.y + c.halfSize.y - y) < 0.15 &&
        Math.abs(c.x - x) <= c.halfSize.x &&
        Math.abs(c.z - z) <= c.halfSize.z,
    );
  // 楼板断檐:沿竖井缘外侧布置叶丛与海扇,井内保持完全通畅。
  const edges = [
    {
      from: [shaft.minX, shaft.minZ],
      to: [shaft.maxX, shaft.minZ],
      normal: [0, -1],
    },
    {
      from: [shaft.minX, shaft.maxZ],
      to: [shaft.maxX, shaft.maxZ],
      normal: [0, 1],
    },
    {
      from: [shaft.minX, shaft.minZ],
      to: [shaft.minX, shaft.maxZ],
      normal: [-1, 0],
    },
    {
      from: [shaft.maxX, shaft.minZ],
      to: [shaft.maxX, shaft.maxZ],
      normal: [1, 0],
    },
  ];
  for (const edge of edges) {
    const length = Math.hypot(
      edge.to[0] - edge.from[0],
      edge.to[1] - edge.from[1],
    );
    const count = Math.max(1, Math.round(length / 9));
    for (let i = 0; i < count; i += 1) {
      if (random() < 0.35) continue;
      const t = (i + 0.5) / count + (random() - 0.5) * 0.1;
      const bx = edge.from[0] + (edge.to[0] - edge.from[0]) * t,
        bz = edge.from[1] + (edge.to[1] - edge.from[1]) * t;
      // 附着点退到檐口外缘 1.1m,冠部随姿态外倾;只挡真正探入井口的个体,
      // 不使用竖井护圈(护圈是为 30m 游体预留的,会误伤檐口附着)。
      const x = bx + edge.normal[0] * 1.1,
        z = bz + edge.normal[1] * 1.1;
      const overOpening =
        x > shaft.minX - 0.4 &&
        x < shaft.maxX + 0.4 &&
        z > shaft.minZ - 0.4 &&
        z < shaft.maxZ + 0.4;
      if (overOpening) continue;
      if (!supported(x, upper.floorY, z)) continue;
      const kind = random() < 0.55 ? "kelp" : "fan";
      set.add(
        kind,
        new THREE.Vector3(x, upper.floorY + 0.02, z),
        orientationFromNormal(
          edge.normal[0] * 0.4,
          1,
          edge.normal[1] * 0.4,
          random() * Math.PI * 2,
        ),
        kind === "kelp" ? 0.9 + random() * 0.5 : 1.1 + random() * 0.7,
        null,
      );
    }
  }
  // 屋面井口与南缘塌口外侧的屋面殖民:从街面俯冲下来时第一眼看到。
  const roofY = site.shaft.topY;
  const roofSpots = [
    [shaft.minX - 2.6, shaft.minZ - 2.2, "coral"],
    [shaft.maxX + 2.4, shaft.maxZ + 2.6, "coral"],
    [shaft.minX - 3.1, shaft.maxZ + 3.4, "fan"],
    [shaft.maxX + 3.2, shaft.minZ - 3.0, "sponge"],
    [site.secondExit.minX - 3.4, site.secondExit.z - 2.6, "coral"],
    [site.secondExit.maxX + 3.8, site.secondExit.z - 2.2, "fan"],
  ];
  for (const [x, z, kind] of roofSpots) {
    if (!supported(x, roofY, z)) continue;
    if (blockedByKeepOut(zones, x, roofY + 1, z, 0.6)) continue;
    set.add(
      kind,
      new THREE.Vector3(x, roofY - 0.05, z),
      orientationFromNormal(0, 1, 0, random() * Math.PI * 2),
      kind === "coral" ? 1.0 + random() * 0.5 : 0.8 + random() * 0.5,
      null,
    );
  }
}

function planEntranceStair(set, site, heightAt, zones, random) {
  const stair = site.entrance;
  const steps = 9;
  // 台阶通道中心线:护墙附着件只需避让净宽本身,护圈留给通道级复核。
  const axis = [
    { x: stair.top.x, y: stair.top.y, z: stair.top.z },
    { x: stair.bottom.x, y: stair.bottom.y, z: stair.bottom.z },
  ];
  const channelDistance = (x, y, z) => {
    const [a, b] = axis;
    const abx = b.x - a.x,
      aby = b.y - a.y,
      abz = b.z - a.z;
    const length2 = abx * abx + aby * aby + abz * abz;
    const t = Math.max(
      0,
      Math.min(
        1,
        ((x - a.x) * abx + (y - a.y) * aby + (z - a.z) * abz) / length2,
      ),
    );
    return Math.hypot(
      x - (a.x + abx * t),
      y - (a.y + aby * t),
      z - (a.z + abz * t),
    );
  };
  // 台阶两侧护墙内面:海扇与海绵顺坡而下,中央通道按 clearWidth 留空。
  for (const sideSign of [-1, 1]) {
    for (let i = 0; i < steps; i += 1) {
      if (random() < 0.3) continue;
      const t = (i + 0.5) / steps;
      const z = stair.top.z + (stair.bottom.z - stair.top.z) * t;
      const y = stair.top.y + (stair.bottom.y - stair.top.y) * t;
      const x = stair.top.x + sideSign * (stair.clearWidth / 2 - 0.12);
      if (channelDistance(x, y + 0.9, z) < stair.clearWidth / 2 - 0.3) continue;
      // 护墙附着件豁免台阶护圈(护圈为通道净宽而设),其余避让体仍然生效。
      if (blockedByKeepOut(zones, x, y + 1, z, 0, "stair")) continue;
      const pick = random();
      const kind =
        pick < 0.5 ? "fan" : pick < 0.78 ? "wallSponge" : "wallAnemone";
      set.add(
        kind,
        new THREE.Vector3(x, y + 0.7 + random() * 0.8, z),
        orientationFromNormal(-sideSign, 0.35, 0, (random() - 0.5) * 0.6),
        kind === "fan" ? 1.1 + random() * 0.8 : 0.5 + random() * 0.4,
        null,
      );
    }
  }
  // 塌口唇口的门柱外侧海扇,沟槽唇口一丛水叶,共同标记入口。
  const gateY = stair.top.y;
  for (const sideSign of [-1, 1]) {
    const x = stair.top.x + sideSign * 10.15;
    for (let i = 0; i < 2; i += 1) {
      const y = gateY + 4 + i * 7 + random() * 2;
      set.add(
        "fan",
        new THREE.Vector3(x, y, stair.top.z + (random() - 0.5)),
        orientationFromNormal(sideSign, 0.3, 0, (random() - 0.5) * 0.5),
        1.4 + random() * 0.8,
        null,
      );
    }
  }
  const lipX = stair.top.x - 7.4,
    lipZ = stair.top.z + 2.2;
  set.add(
    "kelp",
    new THREE.Vector3(lipX, heightAt(lipX, lipZ) + 0.02, lipZ),
    orientationFromNormal(0, 1, 0, random() * Math.PI * 2),
    1.2,
    null,
  );
  // 沟槽两侧原地面落石间的零星珊瑚,把入口编进海床生态。
  for (const sideSign of [-1, 1]) {
    for (let i = 0; i < 3; i += 1) {
      const x = stair.top.x + sideSign * (11.5 + random() * 4);
      const z = stair.top.z + 2 + random() * 8 * (i % 2 ? 1 : -0.4);
      if (blockedByKeepOut(zones, x, heightAt(x, z) + 1, z, 0.4)) continue;
      set.add(
        random() < 0.6 ? "coral" : "sponge",
        new THREE.Vector3(x, heightAt(x, z) - 0.05, z),
        orientationFromNormal(0, 1, 0, random() * Math.PI * 2),
        0.7 + random() * 0.6,
        null,
      );
    }
  }
}

/** 街区立面:锚点由集成方按城市建筑记录给出(中心、外法线、面宽、基顶标高)。 */
function planStreetFacades(set, facades, heightAt, random) {
  for (const facade of facades ?? []) {
    const normal = new THREE.Vector2(
      facade.normal.x,
      facade.normal.z,
    ).normalize();
    const tangent = new THREE.Vector2(-normal.y, normal.x);
    const width = facade.width,
      baseY = facade.baseY,
      topY = facade.topY;
    const at = (along, y, proud = 0) =>
      new THREE.Vector3(
        facade.center.x + tangent.x * along + normal.x * proud,
        y,
        facade.center.z + tangent.y * along + normal.y * proud,
      );
    // 立面灰缝上的海扇与板状海绵,按开间节奏分布,不盖满整面墙。
    const bays = Math.max(2, Math.round(width / 7.5));
    for (let i = 0; i < bays; i += 1) {
      const along =
        -width / 2 + ((i + 0.5) / bays) * width + (random() - 0.5) * 1.6;
      const y = baseY + 1.6 + random() * Math.max(2, (topY - baseY) * 0.55);
      set.add(
        "fan",
        at(along, y, 0.14),
        orientationFromNormal(normal.x, 0.22, normal.y, (random() - 0.5) * 0.5),
        1.6 + random() * 1.2,
        null,
      );
      if (random() < 0.7)
        set.add(
          random() < 0.55 ? "wallSponge" : "wallAnemone",
          at(along + (random() - 0.5) * 2.4, baseY + 1 + random() * 2.6, 0.12),
          orientationFromNormal(
            normal.x,
            0.08,
            normal.y,
            random() * Math.PI * 2,
          ),
          0.5 + random() * 0.45,
          null,
        );
    }
    // 檐口线下一排水叶,立面顶部读得出殖民轮廓。
    const kelps = Math.max(2, Math.round(width / 9));
    for (let i = 0; i < kelps; i += 1) {
      const along =
        -width / 2 + ((i + 0.5) / kelps) * width + (random() - 0.5) * 2;
      set.add(
        "kelp",
        at(along, topY - 0.4, 0.05),
        orientationFromNormal(normal.x, 0, normal.y, random() * Math.PI * 2),
        1.0 + random() * 0.6,
        null,
      );
    }
    // 墙脚街沿的珊瑚与海绵簇,衔接街面铺装。
    const feet = Math.max(2, Math.round(width / 8));
    for (let i = 0; i < feet; i += 1) {
      const along =
        -width / 2 + ((i + 0.5) / feet) * width + (random() - 0.5) * 2.2;
      const foot = at(along, 0, 1.2 + random() * 1.2);
      foot.y = heightAt(foot.x, foot.z) - 0.05;
      set.add(
        random() < 0.5 ? "coral" : "sponge",
        foot,
        orientationFromNormal(0, 1, 0, random() * Math.PI * 2),
        0.8 + random() * 0.7,
        null,
      );
    }
  }
}

/*********************************************
 * 装配:物种原型 → 实例化 → 空间分块
 *********************************************/

const KIND_BUILDERS = {
  coral: () => [
    branchingCoralGeometry(0),
    branchingCoralGeometry(1),
    branchingCoralGeometry(2),
  ],
  sponge: () => [plateSpongeGeometry(0), plateSpongeGeometry(1)],
  wallSponge: () => [plateSpongeGeometry(2), plateSpongeGeometry(3)],
  fan: () => [marineSeaFanGeometry()],
  anemone: () => [anemoneGeometry(0), anemoneGeometry(1)],
  wallAnemone: () => [anemoneGeometry(2)],
  kelp: () => [kelpTuftGeometry()],
};
const KIND_MATERIAL = {
  coral: "coral",
  sponge: "sponge",
  wallSponge: "sponge",
  fan: "fan",
  anemone: "anemone",
  wallAnemone: "anemone",
  kelp: "kelp",
};
// 每物种实例的色相抖动,避免整片同色塑料感。
const KIND_TINTS = {
  coral: ["#ffad90", "#ffceaa", "#f58379", "#ffd3bc"],
  sponge: ["#d8b96e", "#c9a558", "#bfa06a", "#d2b06a"],
  wallSponge: ["#c7ad6a", "#b89a58"],
  fan: ["#ff9b83", "#e98679", "#dbb4d8", "#f7baa0"],
  anemone: ["#d8a3b4", "#c48ba0", "#b49ac4", "#e0b4a8"],
  wallAnemone: ["#c99aae", "#b48ba4"],
  kelp: ["#5d8a7a", "#4f7a6b", "#6a9484"],
};

/**
 * 按最终原型及完整实例变换拟合实体核心。稀疏枝尖保留视觉细节；胶囊的
 * 上下端（包含端帽半径）与真实顶点范围一致，不能伸出模型形成隐形障碍。
 */
function growthCollider(geometry, matrix, kind) {
  const bounds = new THREE.Box3();
  const point = new THREE.Vector3();
  const position = geometry.attributes.position;
  for (let i = 0; i < position.count; i += 1)
    bounds.expandByPoint(
      point.fromBufferAttribute(position, i).applyMatrix4(matrix),
    );
  const size = bounds.getSize(new THREE.Vector3());
  const center = bounds.getCenter(new THREE.Vector3());
  const radius = Math.min(size.x, size.y, size.z) / 2;
  return {
    type: "capsule",
    kind: "marine_growth",
    a: { x: center.x, y: bounds.min.y + radius, z: center.z },
    b: { x: center.x, y: bounds.max.y - radius, z: center.z },
    radius,
    species: kind,
  };
}

/**
 * 创建城市海洋殖民切片。
 * @param {THREE.Object3D} parent 场景父节点(城市根节点)。
 * @param {object} options
 * @param {function} options.heightAt 共享海床高度(参考包 atlantisSeabedHeight)。
 * @param {object} [options.site] 挖掘场地元数据,默认 ATLANTIS_EXCAVATION_SITES[0]。
 * @param {object[]} [options.hostColliders] 厅堂既有碰撞,用于扫墙与避让。
 * @param {object[]} [options.facades] 街区立面锚点(中心/法线/面宽/基顶标高)。
 * @param {number} [options.seed] 布置随机种子,多次构建结果一致。
 * @returns {object} root、colliders、lightSources、landmarks、update、dispose、stats。
 */
export function createAtlantisCityMarine(
  parent,
  { heightAt, site, hostColliders = [], facades = [], seed = 4171 } = {},
) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error(
      "Marine colonization requires a parent and height function",
    );
  const SITE = site ?? ATLANTIS_EXCAVATION_SITES[0];
  const root = new THREE.Group();
  root.name = "atlantis_city_marine";
  parent.add(root);
  const owned = new Set(),
    colliders = [],
    landmarks = [],
    lightSources = [];
  const random = seededRandom(seed);
  const zones = keepOuts(SITE);
  const wallBands = scanWallBands(hostColliders, SITE);
  const set = new PlacementSet();

  planLowerHall(set, SITE, wallBands, zones, hostColliders, heightAt, random);
  planColumns(set, SITE, hostColliders, zones, random);
  planShaftRim(set, SITE, zones, random, hostColliders);
  if (SITE.entrance.kind === "collapsed_grand_stair")
    planEntranceStair(set, SITE, heightAt, zones, random);
  planStreetFacades(set, facades, heightAt, random);

  const marineTime = { value: 0 };
  const materials = marineMaterials(marineTime);
  for (const material of Object.values(materials)) owned.add(material);
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  const perKind = {};
  for (const [kind, list] of set.byKind) {
    const geometries = KIND_BUILDERS[kind]();
    const material = materials[KIND_MATERIAL[kind]];
    // 按原型变体拆分 InstancedMesh,再按空间块拆分供视锥剔除。
    const buckets = geometries.map(() => []);
    list.forEach((item, index) =>
      buckets[index % geometries.length].push(item),
    );
    const sources = [];
    buckets.forEach((bucket, variantIndex) => {
      if (!bucket.length) return;
      const mesh = new THREE.InstancedMesh(
        geometries[variantIndex],
        material,
        bucket.length,
      );
      mesh.name = `marine_${kind}_v${variantIndex}`;
      bucket.forEach((item, i) => {
        dummy.position.copy(item.position);
        dummy.quaternion.copy(item.quaternion);
        dummy.scale.setScalar(item.scale);
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
        if (item.solid)
          colliders.push(
            growthCollider(geometries[variantIndex], dummy.matrix, kind),
          );
        const tints = KIND_TINTS[kind];
        color
          .set(item.tint ?? tints[(i + variantIndex) % tints.length])
          .multiplyScalar(0.9 + ((i * 37 + variantIndex * 11) % 10) * 0.02);
        mesh.setColorAt(i, color);
      });
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
      sources.push(mesh);
    });
    let clusters = 0;
    for (const source of sources) {
      const group = clusterInstances(source, 34);
      // 分批不继承源名,补回物种名便于调试与取样。
      for (const batch of group.children) batch.name = source.name;
      root.add(group);
      clusters += group.children.length;
      group.traverse((node) => {
        if (node.isInstancedMesh) {
          node.receiveShadow = true;
          owned.add({ dispose: () => node.dispose() });
        }
      });
    }
    perKind[kind] = { instances: list.length, clusters };
  }

  const centerX = (SITE.bounds.minX + SITE.bounds.maxX) / 2,
    centerZ = (SITE.bounds.minZ + SITE.bounds.maxZ) / 2;
  landmarks.push(
    {
      id: "marine_lower_hall_garden",
      position: new THREE.Vector3(
        SITE.turningCircle.x,
        SITE.levels[1].floorY + 3,
        SITE.turningCircle.z,
      ),
    },
    {
      id: "marine_entrance_stair",
      position: new THREE.Vector3(
        SITE.entrance.top.x,
        SITE.entrance.top.y + 4,
        SITE.entrance.top.z,
      ),
    },
  );
  if (facades.length)
    landmarks.push({
      id: "marine_street_facade",
      position: new THREE.Vector3(
        facades[0].center.x,
        facades[0].baseY + 4,
        facades[0].center.z,
      ),
    });

  const triangles = [...set.byKind].reduce((sum, [kind, list]) => {
    const geometries = KIND_BUILDERS[kind]();
    return (
      sum +
      list.reduce(
        (s, _item, index) =>
          s +
          geometries[index % geometries.length].attributes.position.count / 3,
        0,
      )
    );
  }, 0);
  const stats = {
    site: SITE.id,
    instances: set.count(),
    colliders: colliders.length,
    triangles: Math.round(triangles),
    perKind,
    wallBands: wallBands.length,
    facades: facades.length,
  };
  root.userData.marineStats = stats;
  let disposed = false;
  return {
    root,
    colliders,
    lightSources,
    landmarks,
    stats,
    update(time, dt, position, highQuality = true) {
      if (disposed) return;
      marineTime.value = time;
      root.visible =
        !position ||
        Math.hypot(centerX - position.x, centerZ - position.z) <
          (highQuality ? 400 : 330);
      void dt;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      parent.remove(root);
      for (const resource of owned) resource.dispose();
      owned.clear();
      root.clear();
      colliders.length = lightSources.length = landmarks.length = 0;
    },
  };
}

atlantis_city_plan.js.source:
import { WORLD } from "./world_config.js";

// 城区占真实水平海域约69.64%；统计的是有道路、街坊和广场的城区，而非建筑投影面积。
export const ATLANTIS_CITY_BOUNDS = Object.freeze({
  minX: -275,
  maxX: 275,
  minZ: -1080,
  maxZ: -100,
});
export const ATLANTIS_DISTRICTS = Object.freeze([
  {
    id: "harbor",
    name: "月湾古港",
    en: "MOON HARBOR",
    z0: -100,
    z1: -300,
    tone: "#b0b8ad",
  },
  {
    id: "market",
    name: "沉没市集",
    en: "DROWNED AGORA",
    z0: -300,
    z1: -500,
    tone: "#94aaaa",
  },
  {
    id: "civic",
    name: "列柱圣道",
    en: "SACRED AVENUE",
    z0: -500,
    z1: -680,
    tone: "#b7bcb2",
  },
  {
    id: "royal",
    name: "波塞冬王城",
    en: "POSEIDON ACROPOLIS",
    z0: -680,
    z1: -900,
    tone: "#bac3bf",
  },
  {
    id: "necropolis",
    name: "星渊陵园",
    en: "STARLESS NECROPOLIS",
    z0: -900,
    z1: -1080,
    tone: "#71878e",
  },
]);

/** 返回城区范围比例，用于地图尺度验收；水面/立体楼层不重复计数。 */
export function cityCoverage() {
  const b = ATLANTIS_CITY_BOUNDS;
  return (
    ((b.maxX - b.minX) * (b.maxZ - b.minZ)) /
    ((WORLD.maxX - WORLD.minX) * (WORLD.maxZ - WORLD.minZ))
  );
}

/** 按世界位置查询真实街区；浅滩仍在城区之外。 */
export function atlantisDistrict(x, z) {
  const b = ATLANTIS_CITY_BOUNDS;
  if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) return null;
  return ATLANTIS_DISTRICTS.find((d) => z <= d.z0 && z >= d.z1) || null;
}

/** 统一街区用地：中央60米圣道、横向通道与竞技场不被随机建筑占用。 */
export function cityLots() {
  const lots = [];
  for (let row = 0; row < 14; row++) {
    const z = -137 - row * 69;
    for (const x of [-247, -183, -119, -55, 55, 119, 183, 247]) {
      // 王城中央保留一个真正开放的大广场，外围街区连续延伸。
      if (Math.abs(x) < 140 && z < -675 && z > -895) continue;
      lots.push({ x, z, row, district: atlantisDistrict(x, z).id });
    }
  }
  return lots;
}

atlantis_exploration_agora.js.source:
import * as THREE from "three";
import {
  MergeBucket,
  atlantisMaterials,
  cachedGeometry,
  paintStone,
  seededRandom,
} from "./atlantis_art_geometry.js";
import { pearlHabitat } from "./atlantis_pearl.js";
import { createAtlantisExplorationFurniture } from "./atlantis_exploration_furniture.js";
import { AGORA_EXCAVATION_SITE } from "./atlantis_exploration_agora_site.js";

// 本模块由 AGORA_EXCAVATION_SITE 不可变元数据驱动装配:开阔下行井直入
// 下沉内庭,周边回廊(上层)带拱顶残跨,北墙为档案龛墙,南墙拱门接水道
// 沟槽出水面。可见体与碰撞体同尺寸同变换,colliders 装配完成后不再改动。
// 与港湾方盒厅堂刻意区分:无整屋面、无整层平板,结构读作"坍塌的环廊蓄池"。

const WALL_BOTTOM = AGORA_EXCAVATION_SITE.floorY - 4; // 墙脚埋入坑底以下
const WALL_W = 189.5; // 西墙内面(墙厚 4.5m,压住坑缘土坡)
const WALL_E = 242.5; // 东墙内面(墙厚 2.5m)
const WALL_S = -483.5; // 南墙内面(墙厚 2.5m)
const WALL_N = -412.5; // 北墙内面(墙厚 4.5m,档案墙)
const DECK = AGORA_EXCAVATION_SITE.levels[0]; // 上层回廊:楼板顶 -334
const CISTERN = AGORA_EXCAVATION_SITE.levels[1]; // 下层内庭:坑底 -362
const SHAFT = AGORA_EXCAVATION_SITE.shaft; // 中央庭院开口(下行井)
const GATE = AGORA_EXCAVATION_SITE.secondExit; // 南墙拱门
const TRENCH = AGORA_EXCAVATION_SITE.trench; // 南门水道沟槽
const TURN = AGORA_EXCAVATION_SITE.turningCircle;
const RIM_PARAPET_MIN = -316; // 墙顶至少到此,盖住海洋殖民的墙带上沿

/**
 * 在 Agora 桥廊预留区装配双层下沉档案库遗迹。
 * @param {THREE.Object3D} parent 场景父节点(城市根节点)。
 * @param {object} options
 * @param {function} options.heightAt 共享海床高度(预览含本场地挖掘剖面)。
 * @param {object} [options.site] 挖掘场地元数据,默认 AGORA_EXCAVATION_SITE。
 * @param {object[]} [options.hostColliders] 既有碰撞(陈设放置避让复核用)。
 * @returns {object} root、colliders、obstacles、landmarks、lightSources、records、stats、update、dispose。
 */
export function createAtlantisAgoraRuins(
  parent,
  { heightAt, site = AGORA_EXCAVATION_SITE, hostColliders = [] } = {},
) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error(
      "Agora sunken archive requires a parent and height function",
    );
  // 此区域专属构图只能配套已注册的场地；拒绝忽略自定义元数据的假接口。
  if (site !== AGORA_EXCAVATION_SITE)
    throw new Error("Agora geometry requires the registered excavation site");
  const SITE = site;
  const root = new THREE.Group();
  root.name = "atlantis_agora_sunken_archive";
  parent.add(root);
  const owned = new Set(),
    colliders = [],
    obstacles = [],
    landmarks = [],
    lightSources = [];
  const b = new ArchiveBuilder(colliders);

  buildPitWalls(b, heightAt);
  buildWalkways(b);
  buildVaults(b);
  buildArchiveWall(b);
  buildSouthGate(b, heightAt);
  buildRimMarkers(b, heightAt);
  buildPodiums(b);
  buildInteriorDressing(b);
  buildPearlNiches(b, lightSources);

  b.bucket.build(atlantisMaterials(), root, owned);
  for (const mesh of root.children) {
    mesh.receiveShadow = true;
    mesh.geometry.computeBoundingSphere();
  }

  // 重用已验收的雕纹家具及接触几何，避免在新遗迹复制低精度的整块包围盒。
  const furniture = createAtlantisExplorationFurniture(root, {
    heightAt,
    site: SITE,
    hostColliders: [...hostColliders, ...colliders],
    groups: agoraFurniturePlan(SITE),
    scatter: [],
    seed: 9377,
  });
  furniture.root.name = "atlantis_agora_furniture";
  colliders.push(...furniture.colliders);

  landmarks.push(
    {
      id: "agora_ruins_well",
      position: new THREE.Vector3(
        (SHAFT.minX + SHAFT.maxX) / 2,
        DECK.floorY + 2,
        (SHAFT.minZ + SHAFT.maxZ) / 2,
      ),
    },
    {
      id: "agora_ruins_cistern",
      position: new THREE.Vector3(TURN.x, TURN.y, TURN.z),
    },
    {
      id: "agora_ruins_gate",
      position: new THREE.Vector3(
        (GATE.minX + GATE.maxX) / 2,
        GATE.sillY + 4,
        GATE.z,
      ),
    },
    {
      id: "agora_ruins_archive_wall",
      position: new THREE.Vector3(216, -322, WALL_N),
    },
  );
  // 室内鱼群沿真实墙体避障，不能用整栋包围球把两层水域都排除掉。

  const stats = {
    site: SITE.id,
    meshes: root.getObjectsByProperty("isMesh", true).length,
    colliders: colliders.length,
    triangles: Math.round(
      [...owned].reduce(
        (sum, geometry) => sum + geometry.attributes.position.count / 3,
        0,
      ) + furniture.stats.triangles,
    ),
    levels: SITE.levels.length,
    pearls: 2,
    furniture: furniture.stats,
  };
  root.userData.agoraRuinsStats = stats;
  let disposed = false;
  return {
    root,
    colliders,
    obstacles,
    landmarks,
    lightSources,
    records: SITE.routes,
    stats,
    furniture,
    update(time, dt, position, highQuality = true) {
      if (disposed) return;
      root.visible =
        !position ||
        Math.hypot(215 - position.x, -447.5 - position.z) <
          (highQuality ? 400 : 330);
      furniture.update(time, dt, position, highQuality);
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      furniture.dispose();
      parent.remove(root);
      for (const geometry of owned) geometry.dispose();
      owned.clear();
      root.clear();
      colliders.length =
        obstacles.length =
        landmarks.length =
        lightSources.length =
          0;
    },
  };
}

/*********************************************
 * 装配工具:可见体与碰撞共用尺寸与变换(沿用港湾厅堂模式)
 *********************************************/

class ArchiveBuilder {
  constructor(colliders) {
    this.bucket = new MergeBucket();
    this.colliders = colliders;
    this.ordinal = 0;
  }
  add(geometry, material, x, y, z, options = {}) {
    const { quaternion = null, tint = null, tile = null } = options;
    paintStone(geometry, {
      base:
        tint ??
        (material === "bronze"
          ? "#668b84"
          : material === "marble"
            ? "#d3d2bc"
            : "#a6b7ae"),
      algaeAmount: material === "stone" ? 0.26 : 0.14,
      seed: 937 + this.ordinal++,
    });
    this.bucket.add(geometry, material, {
      position: [x, y, z],
      quaternion,
      tile: tile ?? (material === "stone" ? 11 : 18),
    });
    geometry.dispose();
  }
  /** 直接并入已带顶点色的构件(贝珠壳体、缓存器物等),不再做石材着色。 */
  addRaw(geometry, materialKey, x, y, z, euler = null) {
    this.bucket.add(geometry, materialKey, { position: [x, y, z], euler });
  }
  box(material, w, h, d, x, y, z, options = {}) {
    const {
      solid = true,
      quaternion = null,
      kind = "agora_ruin_masonry",
      tint = null,
    } = options;
    this.add(new THREE.BoxGeometry(w, h, d), material, x, y, z, {
      quaternion,
      tint,
    });
    if (solid) {
      const collider = {
        type: "box",
        kind,
        x,
        y,
        z,
        halfSize: { x: w / 2, y: h / 2, z: d / 2 },
      };
      if (quaternion)
        collider.rotation = {
          x: quaternion[0],
          y: quaternion[1],
          z: quaternion[2],
          w: quaternion[3],
        };
      this.colliders.push(collider);
    }
  }
}

/*********************************************
 * 四面衬墙:分段跟随坑缘地形,顶缘破碎;北墙见 buildArchiveWall
 *********************************************/

function buildPitWalls(b, heightAt) {
  const pit = AGORA_EXCAVATION_SITE.bounds;
  const WALL_LENGTH = WALL_N - WALL_S; // 71m(z 从南墙内面到北墙内面)
  // 西墙(4.5m 厚)分八段,段顶 = max(坑缘地形 + 1.0, -316) 加破碎抖动。
  for (let i = 0; i < 8; i += 1) {
    const z0 = WALL_S + (WALL_LENGTH / 8) * i,
      z1 = WALL_S + (WALL_LENGTH / 8) * (i + 1);
    const rim = Math.max(
      heightAt(pit.minX - 0.5, (z0 + z1) / 2) + 1.0,
      RIM_PARAPET_MIN,
    );
    const top = rim - (i % 3) * 1.6;
    const h = top - WALL_BOTTOM;
    b.box(
      "stone",
      4.5,
      h,
      z1 - z0,
      pit.minX + 2.25,
      WALL_BOTTOM + h / 2,
      (z0 + z1) / 2,
    );
  }
  // 东墙(2.5m 厚)同样分段。
  for (let i = 0; i < 8; i += 1) {
    const z0 = WALL_S + (WALL_LENGTH / 8) * i,
      z1 = WALL_S + (WALL_LENGTH / 8) * (i + 1);
    const rim = Math.max(
      heightAt(pit.maxX + 0.5, (z0 + z1) / 2) + 1.0,
      RIM_PARAPET_MIN,
    );
    const top = rim - ((i + 1) % 3) * 1.4;
    const h = top - WALL_BOTTOM;
    b.box(
      "stone",
      2.5,
      h,
      z1 - z0,
      pit.maxX - 1.25,
      WALL_BOTTOM + h / 2,
      (z0 + z1) / 2,
    );
  }
  // 南墙(2.5m 厚):中央留拱门开口 x∈[GATE.minX, GATE.maxX]、y∈[-334,-318]。
  const gateTop = GATE.topY;
  for (const [x0, x1] of [
    [WALL_W, GATE.minX],
    [GATE.maxX, WALL_E],
  ]) {
    for (let i = 0; i < 3; i += 1) {
      const xa = x0 + ((x1 - x0) / 3) * i,
        xb = x0 + ((x1 - x0) / 3) * (i + 1);
      const rim = Math.max(
        heightAt((xa + xb) / 2, pit.minZ - 0.5) + 1.0,
        RIM_PARAPET_MIN + 2,
      );
      const top = rim - (i % 2) * 1.8;
      const h = top - WALL_BOTTOM;
      b.box(
        "stone",
        xb - xa,
        h,
        2.5,
        (xa + xb) / 2,
        WALL_BOTTOM + h / 2,
        pit.minZ + 1.25,
      );
    }
  }
  // 门洞下槛段(埋住坑缘残土)与门楣段(楣顶与两侧墙顶线相读)。
  b.box(
    "stone",
    GATE.maxX - GATE.minX,
    -334 - WALL_BOTTOM,
    2.5,
    216,
    (-334 + WALL_BOTTOM) / 2,
    pit.minZ + 1.25,
  );
  b.box(
    "stone",
    GATE.maxX - GATE.minX,
    -313.5 - gateTop,
    2.5,
    216,
    (-313.5 + gateTop) / 2,
    pit.minZ + 1.25,
  );
  // 墙顶内饰线脚(视觉,贴面不出碰撞):回廊楼板标高与拱顶起拱线各一道。
  for (const ledgeY of [DECK.floorY + 0.9, -329.4]) {
    // 墙面线脚在门洞两侧结束，不能把无碰撞的石条悬挂在水道中。
    for (const [x0, x1] of [
      [WALL_W, GATE.minX],
      [GATE.maxX, WALL_E],
    ])
      b.box("marble", x1 - x0, 1.4, 0.9, (x0 + x1) / 2, ledgeY, WALL_S + 0.45, {
        solid: false,
      });
    b.box("marble", 0.9, 1.4, 71, WALL_W + 0.45, ledgeY, -447.5, {
      solid: false,
    });
    b.box("marble", 0.9, 1.4, 71, WALL_E - 0.45, ledgeY, -447.5, {
      solid: false,
    });
  }
}

/*********************************************
 * 周边回廊(上层):环井楼板 + 牛腿 + 内缘断栏;南侧接水门道槛
 *********************************************/

function buildWalkways(b) {
  const deckBottom = DECK.floorY - 2.5; // 楼板厚 2.5m
  const deckY = (DECK.floorY + deckBottom) / 2;
  const runs = [
    // 南回廊(满宽,接南门道槛)
    { x0: WALL_W, x1: WALL_E, z0: -483.5, z1: SHAFT.minZ },
    // 西回廊
    { x0: WALL_W, x1: SHAFT.minX, z0: SHAFT.minZ, z1: SHAFT.maxZ },
    // 东回廊
    { x0: SHAFT.maxX, x1: WALL_E, z0: SHAFT.minZ, z1: SHAFT.maxZ },
    // 北回廊(档案墙脚)
    { x0: SHAFT.minX, x1: SHAFT.maxX, z0: SHAFT.maxZ, z1: WALL_N },
  ];
  for (const run of runs)
    b.box(
      "stone",
      run.x1 - run.x0,
      DECK.floorY - deckBottom,
      run.z1 - run.z0,
      (run.x0 + run.x1) / 2,
      deckY,
      (run.z0 + run.z1) / 2,
      { kind: "agora_ruin_deck" },
    );
  // 悬挑牛腿:沿内缘线每 6.8m 一只,从墙/楼板底托出,不参与回转净区。
  for (const side of ["west", "east"]) {
    const x = side === "west" ? SHAFT.minX - 0.8 : SHAFT.maxX + 0.8;
    for (let z = SHAFT.minZ + 4; z < SHAFT.maxZ - 2; z += 6.8)
      b.box("stone", 1.6, 1.5, 2.2, x, deckBottom - 0.75, z, {
        kind: "agora_ruin_corbel",
      });
  }
  for (let x = SHAFT.minX + 4; x < SHAFT.maxX - 2; x += 6.8) {
    b.box("stone", 2.2, 1.5, 1.6, x, deckBottom - 0.75, SHAFT.minZ - 0.8, {
      kind: "agora_ruin_corbel",
    });
    b.box("stone", 2.2, 1.5, 1.6, x, deckBottom - 0.75, SHAFT.maxZ + 0.8, {
      kind: "agora_ruin_corbel",
    });
  }
  // 内缘断栏:大理石栏段断续残留,约占六成,让井口读作有栏的回廊。
  const random = seededRandom(4409);
  const curb = (w, d, x, z) =>
    b.box("marble", w, 0.95, d, x, DECK.floorY + 0.48, z, {
      kind: "agora_ruin_curb",
    });
  for (let z = SHAFT.minZ + 1.6; z < SHAFT.maxZ - 1; z += 4.4) {
    if (random() < 0.62) curb(0.7, 3.4, SHAFT.minX - 0.35, z);
    if (random() < 0.62) curb(0.7, 3.4, SHAFT.maxX + 0.35, z);
  }
  for (let x = SHAFT.minX + 1.8; x < SHAFT.maxX - 1; x += 4.4) {
    // 南内缘在水道门口走廊(x∈[206,226])不留栏段,保持门进门的俯视净空。
    if (random() < 0.6 && (x < 206 || x > 226))
      curb(3.4, 0.7, x, SHAFT.minZ - 0.35);
    if (random() < 0.55) curb(3.4, 0.7, x, SHAFT.maxZ + 0.35);
  }
  // 楼板面拼花:青铜嵌线沿内缘,不挡游线(视觉)。
  for (const [x, z, w, d] of [
    [SHAFT.minX - 0.9, -448.25, 0.22, 55],
    [SHAFT.maxX + 0.9, -448.25, 0.22, 55],
    [216, SHAFT.minZ - 0.9, 39, 0.22],
    [216, SHAFT.maxZ + 0.9, 39, 0.22],
  ])
    b.box("bronze", w, 0.1, d, x, DECK.floorY + 0.05, z, { solid: false });
}

/*********************************************
 * 拱顶残跨:东西回廊各两跨马蹄拱,部分壳板坍塌
 *********************************************/

function buildVaults(b) {
  // 拱剖面:弦跨 6m(墙面→内缘),矢高 4.3m,半径 3.2m,圆心 (3, -329.1)。
  const R = 3.2,
    CY = DECK.ceilingY + 2,
    SPRING = DECK.ceilingY + 0.9;
  const bays = [
    { side: -1, z0: -462, z1: -450, broken: false },
    { side: -1, z0: -438, z1: -426, broken: true },
    { side: 1, z0: -468, z1: -456, broken: true },
    { side: 1, z0: -442, z1: -430, broken: false },
  ];
  const phiA = Math.PI + 0.3519, // 墙侧起拱角
    phiB = -0.3519; // 内缘起拱角
  for (const bay of bays) {
    const cx = bay.side === -1 ? WALL_W + 3 : WALL_E - 3;
    const ribs = bay.broken ? 2 : 3;
    for (let r = 0; r < ribs; r += 1) {
      const z =
        bay.z0 + 2 + (r * (bay.z1 - bay.z0 - 4)) / Math.max(1, ribs - 1);
      const segments = 11;
      for (let i = 0; i < segments; i += 1) {
        const phi = phiB + ((i + 0.5) / segments) * (phiA - phiB);
        // 残跨的肋在上半部断续缺块,让井口天光漏进廊道。
        if (bay.broken && i > 3 && i < 8 && (r + i) % 2 === 0) continue;
        const px = cx - bay.side * Math.cos(phi) * R;
        const py = CY + Math.sin(phi) * R;
        const rotation = bay.side === -1 ? phi : -phi;
        b.box(
          "stone",
          0.6,
          ((Math.abs(phiA - phiB) * R) / segments) * 1.06,
          1.15,
          px,
          py,
          z,
          {
            kind: "agora_ruin_vault",
            quaternion: new THREE.Quaternion()
              .setFromAxisAngle(new THREE.Vector3(0, 0, 1), rotation)
              .toArray(),
          },
        );
      }
    }
    // 完整跨以五块壳板覆冠(读作连续拱壳);残跨只在起拱线留板根。
    const plateAngles = bay.broken
      ? [phiA - 0.22, phiB + 0.22]
      : [phiA - 0.35, 2.2, Math.PI / 2, 1.05, phiB + 0.35];
    for (const phi of plateAngles) {
      const px = cx - bay.side * Math.cos(phi) * (R - 0.12);
      const py = CY + Math.sin(phi) * (R - 0.12);
      const rotation = bay.side === -1 ? phi + Math.PI / 2 : Math.PI / 2 - phi;
      b.box(
        "stone",
        2.1,
        0.34,
        bay.z1 - bay.z0 - 2.4,
        px,
        py,
        (bay.z0 + bay.z1) / 2,
        {
          kind: "agora_ruin_vault",
          quaternion: new THREE.Quaternion()
            .setFromAxisAngle(new THREE.Vector3(0, 0, 1), rotation)
            .toArray(),
        },
      );
    }
    // 起拱线枕梁(墙侧与内缘各一)。
    for (const u of [0.35, 5.65]) {
      const x = bay.side === -1 ? WALL_W + u : WALL_E - u;
      b.box(
        "marble",
        0.9,
        1.1,
        bay.z1 - bay.z0,
        x,
        SPRING - 0.35,
        (bay.z0 + bay.z1) / 2,
        {
          kind: "agora_ruin_vault",
        },
      );
    }
  }
}

/*********************************************
 * 北墙档案墙:高出的龛墙,壁柱分间,三层卷轴龛
