    edgeBlend: 2,
    startBlendMeters: 2, // 南端渐入沟槽，避免口门与原海床出现高度跳变。
  },
};

/**
 * 不可变挖掘场地元数据。所有 Y 均为世界坐标(水面为 4,向下为负)。
 * fishSanctuary 为扩展字段:既有 8 尾 agora_bridges 白鲳的下层游动空间,
 * 供集成方迁移锚点;不改变物种、数量、水层带宽或营养规则。
 */
