/** 双耳瓶群:瓶座石盘上一簇立瓶,末尾一只倾倒,旁边一块残片。 */
function amphoraCluster(b, x, floor, z, count, seed) {
  const random = seededRandom(seed);
  b.box("stone", 3.4, 0.32, 2.6, x, floor + 0.16, z, { tint: "#97a79e" });
  const jar = amphoraGeometry(),
    handle = amphoraHandle();
  for (let i = 0; i < count; i += 1) {
    const angle = i * 2.399 + random() * 0.4;
    const px = x + Math.cos(angle) * (0.35 + (i % 3) * 0.55);
    const pz = z + Math.sin(angle) * (0.35 + (i % 2) * 0.55);
    const tipped = i === count - 1 && count > 3;
    const yaw = random() * Math.PI * 2;
    b.addRaw(
      jar,
      // 复用无石砖纹理的高粗糙度、低金属度材质，使陶器与铜箍明确区分。
      "pearlReef",
      px,
      floor + 0.33 + (tipped ? 0.3 : 0),
      pz,
      tipped ? [0, yaw, 1.35] : [0, yaw, 0],
    );
    if (!tipped)
      for (const side of [-1, 1])
        b.addRaw(handle, "pearlReef", px, floor + 0.33, pz, [
          0,
          yaw + (side < 0 ? Math.PI : 0),
          0,
        ]);
  }
  // 残片:半只瓶壳侧卧在瓶座边。
  const shard = cachedGeometry("exploration_amphora_shard_v2", () => {
    const points = [
      [0.02, 0],
      [0.4, 0.2],
      [0.55, 0.6],
      [0.42, 1.0],
    ].map(([px, py]) => new THREE.Vector2(px, py));
    const g = new THREE.LatheGeometry(points, 12, 0, Math.PI * 0.9);
    paintStone(g, { base: "#a57e68", algaeAmount: 0.2, seed: 93 });
    return g;
  });
  b.addRaw(shard, "pearlReef", x + 1.9, floor + 0.54, z + 1.1, [
    1.45,
    random() * 2,
    0.4,
  ]);
  b.colliders.push({
    type: "box",
    kind: "exploration_furniture",
    x,
    y: floor + 1.1,
    z,
    halfSize: { x: 1.7, y: 1.1, z: 1.3 },
  });
}

/** 缓存不可变成品；住宅批次只烘焙世界变换，不为每幢房屋重雕同一单品。 */
function furniturePrototype(item) {
  const variant = (((item.seed ?? 9151) % 4) + 4) % 4;
  const count = item.kind === "amphora" ? (item.count ?? 3) : 0;
  const key = `${item.kind}:${count}:${variant}`;
  if (FURNITURE_PROTOTYPES.has(key)) return FURNITURE_PROTOTYPES.get(key);
  const colliders = [],
    builder = new FurnitureBuilder(colliders);
  if (item.kind === "bench") stoneBench(builder, 0, 0, 0);
  else if (item.kind === "table") stoneTable(builder, 0, 0, 0);
  else if (item.kind === "chest") storageChest(builder, 0, 0, 0);
  else if (item.kind === "amphora")
    amphoraCluster(builder, 0, 0, 0, count, 9151 + variant);
  else throw new Error(`Unsupported furniture kind: ${item.kind}`);
  const parent = new THREE.Group(),
    owned = new Set();
  const parts = builder.bucket
    .build(atlantisMaterials(), parent, owned)
    .map((mesh) => ({
      geometry: mesh.geometry,
      material: mesh.name.slice("atlantis_".length),
    }));
  const bounds = new THREE.Box3();
  for (const part of parts) {
    part.geometry.computeBoundingBox();
    bounds.union(part.geometry.boundingBox);
  }
  const prototype = { parts, colliders, bounds };
  FURNITURE_PROTOTYPES.set(key, prototype);
  return prototype;
}

/** 局部碰撞与可见网格使用相同的旋转、缩放和世界原点。 */
function placePrototype(builder, prototype, item) {
  const scale = item.scale ?? 1,
    yaw = item.yaw ?? 0;
  const quaternion = new THREE.Quaternion().setFromAxisAngle(
    new THREE.Vector3(0, 1, 0),
    yaw,
  );
  for (const part of prototype.parts)
    builder.bucket.add(part.geometry, part.material, {
      position: [item.x, item.floor, item.z],
      quaternion: quaternion.toArray(),
      scale,
    });
  for (const source of prototype.colliders) {
    const position = new THREE.Vector3(source.x, source.y, source.z)
      .multiplyScalar(scale)
      .applyQuaternion(quaternion)
      .add(new THREE.Vector3(item.x, item.floor, item.z));
    const rotation = quaternion.clone();
    if (source.rotation)
      rotation.multiply(
        new THREE.Quaternion(
          source.rotation.x,
          source.rotation.y,
          source.rotation.z,
          source.rotation.w,
        ),
      );
    builder.colliders.push({
      ...source,
      x: position.x,
      y: position.y,
      z: position.z,
      halfSize: {
        x: source.halfSize.x * scale,
        y: source.halfSize.y * scale,
        z: source.halfSize.z * scale,
      },
      rotation: { x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w },
    });
  }
}

/** 散落器物:碗、小罐、盘,实例化散布;小件不加碰撞。 */
function scatterPieces(transforms, seed) {
  const random = seededRandom(seed);
  const bowl = cachedGeometry("exploration_scatter_bowl", () => {
    const g = new THREE.LatheGeometry(
      [
        [0, 0],
        [0.32, 0.06],
        [0.46, 0.22],
        [0.4, 0.36],
      ].map(([px, py]) => new THREE.Vector2(px, py)),
      14,
    );
    paintStone(g, { base: "#9c816a", algaeAmount: 0.2, seed: 77 });
    return g;
  });
  const jug = cachedGeometry("exploration_scatter_jug", () => {
    const g = new THREE.LatheGeometry(
      [
        [0, 0],
        [0.26, 0.04],
        [0.38, 0.4],
        [0.3, 0.66],
        [0.16, 0.78],
        [0.2, 0.88],
      ].map(([px, py]) => new THREE.Vector2(px, py)),
      12,
    );
    paintStone(g, { base: "#a08b70", algaeAmount: 0.22, seed: 79 });
    return g;
  });
  const disc = cachedGeometry("exploration_scatter_disc", () => {
    const g = new THREE.CylinderGeometry(0.5, 0.58, 0.15, 14);
    paintStone(g, { base: "#b9b7a6", algaeAmount: 0.24, seed: 78 });
    return g;
  });
  const geometries = [bowl, jug, disc];
  const buckets = geometries.map(() => []);
  for (const t of transforms) buckets[Math.floor(random() * 3)].push(t);
  const meshes = [];
  buckets.forEach((bucket, i) => {
    if (!bucket.length) return;
    const mesh = new THREE.InstancedMesh(
      geometries[i],
      atlantisMaterials().bronze,
      bucket.length,
    );
    mesh.name = `exploration_scatter_${i}`;
    const dummy = new THREE.Object3D();
    bucket.forEach((t, index) => {
      // 倾倒件绕底缘翻转,重心下沉,避免悬浮。
      dummy.position.set(t.x, t.y - (t.tipped ? 0.14 : 0), t.z);
      dummy.rotation.set(t.tipped ? 1.45 : 0, t.yaw, 0);
      dummy.scale.setScalar(t.scale);
      dummy.updateMatrix();
      mesh.setMatrixAt(index, dummy.matrix);
    });
    mesh.instanceMatrix.needsUpdate = true;
    mesh.computeBoundingSphere();
    meshes.push(mesh);
  });
  return meshes;
}

/*********************************************
 * 布置表:港湾厅堂成组陈设(坐标避让既有家具,掉落记入 stats.dropped)
 *********************************************/

function planGroups(site) {
  const lower = site.levels[1].floorY,
    upper = site.levels[0].floorY;
  const origin = siteOrigin(site);
  return [
    // 下厅东北角:宴会角——圆桌、对凳、续排双箱(避开柱础与竖井护圈)。
    { kind: "table", x: 21.2, floor: lower, z: 19.6 },
    { kind: "bench", x: 24.8, floor: lower, z: 19, yaw: 0 },
    { kind: "bench", x: 17.8, floor: lower, z: 19, yaw: 0 },
    { kind: "chest", x: 8.8, floor: lower, z: 21.6, yaw: 0 },
    { kind: "chest", x: 25.5, floor: lower, z: 21.5, yaw: 0 },
    // 下厅西南角:贝珠壁龛旁的落货——瓶群、单箱。
    { kind: "amphora", x: -16, floor: lower, z: -22.2, count: 5, seed: 87 },
    { kind: "chest", x: -12, floor: lower, z: -20.2, yaw: 0 },
    // 上层展厅西北角:对弈角——圆桌、双凳与单箱。
    { kind: "table", x: -30, floor: upper, z: 15 },
    { kind: "bench", x: -30, floor: upper, z: 18.4, yaw: 0 },
    { kind: "bench", x: -28.5, floor: upper, z: 12.5, yaw: 0 },
    { kind: "chest", x: -31, floor: upper, z: 10.5, yaw: 0 },
  ].map((item) => ({ ...item, x: origin.x + item.x, z: origin.z + item.z }));
}

/** 散落器物点位:围绕陈设组与南墙根,全部贴地、避开通道。 */
function planScatter(site, random) {
  const lower = site.levels[1].floorY,
    upper = site.levels[0].floorY;
  const spots = [];
  const rings = [
    { x: 19, z: 18.6, floor: lower, r: 3.6, n: 6 },
    { x: -14, z: -21.4, floor: lower, r: 3.8, n: 7 },
    { x: -29.5, z: 14.5, floor: upper, r: 3.6, n: 5 },
  ];
  for (const ring of rings)
    for (let i = 0; i < ring.n; i += 1) {
      const a = random() * Math.PI * 2;
      const r = ring.r * (0.55 + random() * 0.6);
      spots.push({
        x: ring.x + Math.cos(a) * r,
        y: ring.floor + 0.04,
        z: ring.z + Math.sin(a) * r,
        yaw: random() * Math.PI * 2,
        tipped: random() > 0.72,
        scale: 0.8 + random() * 0.5,
      });
    }
  // 南墙根一线零星器物。
  for (let i = 0; i < 6; i += 1) {
    const x = -7 + random() * 22;
    spots.push({
      x,
      y: lower + 0.04,
      z: -23.5 + random() * 1.6,
      yaw: random() * Math.PI * 2,
      tipped: random() > 0.6,
      scale: 0.75 + random() * 0.5,
    });
  }
  const origin = siteOrigin(site);
  return spots.map((spot) => ({
    ...spot,
    x: origin.x + spot.x,
    z: origin.z + spot.z,
  }));
}

/** 托盘完整占地采样，石质基座从最低海床埋入并托至最高点。 */
function facadeFooting(heightAt, x, z) {
  let min = Infinity,
    max = -Infinity;
  for (let ix = 0; ix <= 12; ix += 1)
    for (let iz = 0; iz <= 10; iz += 1) {
      const y = heightAt(x + (ix / 12 - 0.5) * 3.4, z + (iz / 10 - 0.5) * 2.6);
      min = Math.min(min, y);
      max = Math.max(max, y);
    }
  return { bottom: min - 0.1, floor: max + 0.02 };
}

/**
 * 创建探索家具陈设切片。
 * @param {THREE.Object3D} parent 场景父节点(城市根节点)。
 * @param {object} options
 * @param {function} options.heightAt 共享海床高度(街区立面墙脚贴地用)。
 * @param {object} [options.site] 挖掘场地元数据,默认 ATLANTIS_EXCAVATION_SITES[0]。
 * @param {object[]} [options.hostColliders] 厅堂既有碰撞,用于避让既有陈设。
 * @param {object[]} [options.facades] 可选墙面锚点；center{x,z} 为真实墙面点，normal{x,z} 为朝街道法线。
 * @param {number} [options.seed] 布置随机种子。
 * @param {object[]} [options.groups] 可选世界坐标陈设表；省略时采用港湾布局。
 * @param {object[]} [options.scatter] 可选散落器物表；省略时采用港湾布局。
 * @returns {object} root、colliders、lightSources、landmarks、update、dispose、stats。
 */
export function createAtlantisExplorationFurniture(
  parent,
  {
    heightAt,
    site,
    hostColliders = [],
    facades = [],
    seed = 9151,
    groups,
    scatter,
    customLayout = false,
  } = {},
) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error(
      "Exploration furniture requires a parent and height function",
    );
  const SITE = customLayout ? null : (site ?? ATLANTIS_EXCAVATION_SITES[0]);
  const root = new THREE.Group();
  root.name = "atlantis_exploration_furniture";
  parent.add(root);
  const owned = new Set(),
    colliders = [],
    landmarks = [],
    lightSources = [];
  const random = seededRandom(seed);
  const zones = SITE ? keepOuts(SITE) : [];
  const b = new FurnitureBuilder(colliders);
  const dropped = [];
  const placedGroups = [];
  const placed = { bench: 0, table: 0, chest: 0, amphora: 0 };

  // 宿主快照索引不污染集成方稍后仍在追加的城市碰撞数组。
  const hostGrid = createStaticColliderGrid([...hostColliders]);
  const queryHosts = (min, max) => [...hostGrid.query(min, max), ...colliders];
  // 同步构造期间宿主形状不变；仅缓存宿主盒，原始/缩底候选仍独立计算。
  let hostEdges = new WeakMap();
  const EXTENTS = {
    bench: { halfX: 1.8, halfZ: 0.68, height: 1.5 },
    table: { halfX: 1.38, halfZ: 1.38, height: 1.7 },
    chest: { halfX: 1.36, halfZ: 0.94, height: 2.4 },
    amphora: { halfX: 1.7, halfZ: 1.5, height: 2.4 },
  };
  function canPlace(kind, x, floor, z, bottom = floor, yaw = 0, scale = 1) {
    const extent = EXTENTS[kind];
    const c = Math.abs(Math.cos(yaw)),
      s = Math.abs(Math.sin(yaw));
    const box = furnitureBox(
      (extent.halfX * c + extent.halfZ * s) * 2 * scale,
      floor + extent.height * scale - bottom,
      (extent.halfX * s + extent.halfZ * c) * 2 * scale,
      x,
      (bottom + floor + extent.height * scale) / 2,
      z,
    );
    return (
      !blockedByKeepOut(zones, box) && !overlapsHost(queryHosts, box, hostEdges)
    );
  }
  function canPlaceGroup(item) {
    if (!customLayout)
      return canPlace(
        item.kind,
        item.x,
        item.floor,
        item.z,
        item.floor,
        item.yaw ?? 0,
      );
    const { bounds } = furniturePrototype(item);
    const scale = item.scale ?? 1,
      yaw = item.yaw ?? 0;
    const q = new THREE.Quaternion().setFromAxisAngle(
      new THREE.Vector3(0, 1, 0),
      yaw,
    );
    const size = bounds.getSize(new THREE.Vector3()).multiplyScalar(scale);
    const center = bounds
      .getCenter(new THREE.Vector3())
      .multiplyScalar(scale)
      .applyQuaternion(q)
      .add(new THREE.Vector3(item.x, item.floor, item.z));
    const box = furnitureBox(
      size.x,
      size.y,
      size.z,
      center.x,
      center.y,
      center.z,
      yaw,
    );
    return !overlapsHost(queryHosts, box, hostEdges);
  }
  for (const item of groups ?? (SITE ? planGroups(SITE) : [])) {
    if (!canPlaceGroup(item)) {
      dropped.push({
        id: item.id,
        kind: item.kind,
        x: item.x,
        z: item.z,
        reason: "keepout_or_host",
      });
      continue;
    }
    if (customLayout) placePrototype(b, furniturePrototype(item), item);
    else if (item.kind === "bench")
      stoneBench(b, item.x, item.floor, item.z, item.yaw ?? 0);
    else if (item.kind === "table") stoneTable(b, item.x, item.floor, item.z);
    else if (item.kind === "chest")
      storageChest(b, item.x, item.floor, item.z, item.yaw ?? 0);
    else if (item.kind === "amphora")
      amphoraCluster(b, item.x, item.floor, item.z, item.count, item.seed);
    placed[item.kind] += 1;
    placedGroups.push({ ...item });
  }

  // facade.center 是真实墙面上的点；normal 为指向街道的世界 XZ 法线。
  // 按托盘投影留出墙面净距，无论朝向都不能让基座嵌入立面。
  for (const facade of facades ?? []) {
    const normal = new THREE.Vector2(facade.normal.x, facade.normal.z);
    if (!normal.lengthSq()) continue;
    normal.normalize();
    const offset = Math.abs(normal.x) * 1.7 + Math.abs(normal.y) * 1.5 + 0.6;
    let placement = null;
    // 柱脚和地基可以突出于墙面；有限向外退让后仍须通过同一实体/游线检测。
    for (let attempt = 0; attempt < 5; attempt += 1) {
      const distance = offset + attempt * 0.6;
      const x = facade.center.x + normal.x * distance;
      const z = facade.center.z + normal.y * distance;
      const footing = facadeFooting(heightAt, x, z);
      if (!canPlace("amphora", x, footing.floor, z, footing.bottom)) continue;
      placement = { x, z, ...footing };
      break;
    }
    if (!placement) {
      dropped.push({
        kind: "amphora",
        x: facade.center.x,
        z: facade.center.z,
        reason: "keepout_or_host",
      });
      continue;
    }
    const { x: fx, z: fz, ...footing } = placement;
    const height = footing.floor - footing.bottom;
    b.box("stone", 3.4, height, 2.6, fx, footing.bottom + height / 2, fz, {
      solid: true,
      tint: "#97a79e",
    });
    amphoraCluster(b, fx, footing.floor, fz, 3, seed + 17);
    placed.amphora += 1;
  }

  // 散落器物(视觉小件,实例化,无碰撞);连同本组新碰撞一起避让。
  const scatterTransforms = (
    scatter ?? (SITE ? planScatter(SITE, random) : [])
  ).filter((t) => {
    const box = furnitureBox(1, 0.5, 1, t.x, t.y + 0.25, t.z);
    return (
      !blockedByKeepOut(zones, box) && !overlapsHost(queryHosts, box, hostEdges)
    );
  });
  // 布置结束后主动解除临时缓存引用，不随 update/dispose 闭包保留。
  hostEdges = null;
  const scatterMeshes = scatterPieces(scatterTransforms, seed + 3);

  b.bucket.build(atlantisMaterials(), root, owned);
  for (const mesh of scatterMeshes) {
    root.add(mesh);
    owned.add({ dispose: () => mesh.dispose() });
  }
  for (const mesh of root.children) {
    if (!mesh.isMesh && !mesh.isInstancedMesh) continue;
    mesh.receiveShadow = true;
    mesh.geometry.computeBoundingSphere();
  }

  if (SITE) {
    const origin = siteOrigin(SITE);
    landmarks.push(
      {
        id: "furniture_lower_hall_banquet",
        position: new THREE.Vector3(
          origin.x + 21.2,
          SITE.levels[1].floorY + 2,
          origin.z + 19.6,
        ),
      },
      {
        id: "furniture_upper_gallery_corner",
        position: new THREE.Vector3(
          origin.x - 29,
          SITE.levels[0].floorY + 2,
          origin.z + 15,
        ),
      },
    );
  }

  const triangles =
    [...owned].reduce((sum, resource) => {
      if (resource.attributes?.position)
        return (
          sum +
          (resource.index?.count ?? resource.attributes.position.count) / 3
        );
      return sum;
    }, 0) +
    scatterMeshes.reduce(
      (sum, mesh) =>
        sum +
        ((mesh.geometry.index?.count ??
          mesh.geometry.attributes.position.count) *
          mesh.count) /
          3,
      0,
    );
  const stats = {
    site: SITE?.id ?? "custom_furnishing_batch",
    placed,
    dropped,
    placedGroups,
    scatter: scatterTransforms.length,
    colliders: colliders.length,
    triangles: Math.round(triangles),
  };
  root.userData.furnitureStats = stats;
  const centerX = SITE ? (SITE.bounds.minX + SITE.bounds.maxX) / 2 : 0,
    centerZ = SITE ? (SITE.bounds.minZ + SITE.bounds.maxZ) / 2 : 0;
  let disposed = false;
  return {
    root,
    colliders,
    lightSources,
    landmarks,
    stats,
    update(time, dt, position, highQuality = true) {
      if (disposed) return;
      root.visible =
        !SITE ||
        !position ||
        Math.hypot(centerX - position.x, centerZ - position.z) <
          (highQuality ? 400 : 330);
      void time;
      void dt;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      parent.remove(root);
      for (const resource of owned) resource.dispose();
      owned.clear();
      root.clear();
      colliders.length = lightSources.length = landmarks.length = 0;
    },
  };
}

/**
 * 复用已验收的雕刻家具，按调用方给出的世界坐标批量组装。
 * @param {THREE.Object3D} parent 父场景。
 * @param {object} options groups 陈设清单、heightAt 支撑采样和 hostColliders 实体避让。
 * @returns {object} 与探索家具相同的碰撞、统计及幂等生命周期接口。
 */
export function createAtlantisFurnitureBatch(parent, options = {}) {
  return createAtlantisExplorationFurniture(parent, {
    ...options,
    customLayout: true,
    facades: [],
    scatter: [],
  });
}

atlantis_exploration_harbor.js.source:
import * as THREE from "three";
import {
  MergeBucket,
  atlantisMaterials,
  cachedGeometry,
  loftGeometry,
  paintStone,
  seededRandom,
} from "./atlantis_art_geometry.js";
import { pearlHabitat } from "./atlantis_pearl.js";
import { ATLANTIS_EXCAVATION_SITES } from "./atlantis_terrain.js";

// 本模块由 ATLANTIS_EXCAVATION_SITES[0] 的不可变元数据驱动装配;
// 可见体与碰撞体同尺寸同变换,colliders 数组装配完成后不再改动。
const SITE = ATLANTIS_EXCAVATION_SITES[0];
const UPPER = SITE.levels[0]; // 上层展厅:楼板顶 -156,顶板底 -135.5
const LOWER = SITE.levels[1]; // 下层正厅:坑底 -194,楼板底 -158
const ROOF_TOP = -133;
const WALL_BOTTOM = LOWER.floorY - 4; // 墙脚埋入坑底以下
const WALL_N = -224.5; // 北墙内面(墙厚 4.5m,压住高侧坑缘土坡)
const WALL_S = -273.5; // 南墙内面(墙厚 2.5m)
const WALL_W = -247.5; // 西墙内面(墙厚 4.5m)
const WALL_E = -180.5; // 东墙内面(墙厚 2.5m)
const STAIR = SITE.entrance; // 塌口大台阶
const SHAFT = SITE.shaft; // 中央开阔竖井
const PORTAL = SITE.secondExit; // 南墙拱门(第二出口)

/**
 * 在港湾圣所预留区装配双层下沉厅堂:北缘塌口大台阶下行到上层展厅,
 * 中央开阔竖井贯通到下层正厅,南墙拱门为第二出口,屋面南缘塌口可翻越
 * 返回街面,构成连续往返环线。厅堂本体全部在挖掘坑内,屋面与原有
 * 圣所下廊地面大致齐平,东南两侧顺坡露出立面。
 * @param {THREE.Object3D} parent 场景父节点(城市根节点)。
 * @param {{heightAt:function}} options 共享海床高度(已含挖掘剖面)。
 * @returns {object} root、colliders、obstacles、landmarks、lightSources、records、stats、update、dispose。
 */
export function createAtlantisHarborRuins(parent, { heightAt } = {}) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error("Harbor sunken halls require a parent and height function");
  const root = new THREE.Group();
  root.name = "atlantis_harbor_sunken_halls";
  parent.add(root);
  const owned = new Set(),
    colliders = [],
    obstacles = [],
    landmarks = [],
    lightSources = [];
  const b = new HallBuilder(colliders);

  buildWalls(b);
  buildRoof(b);
  buildUpperSlab(b);
  buildColumns(b);
  buildEntranceStair(b, heightAt);
  buildSouthPortal(b);
  buildInteriorDressing(b);
  buildFurniture(b);
  buildPearlNiches(b, lightSources);

  b.bucket.build(atlantisMaterials(), root, owned);
  for (const mesh of root.children) {
    mesh.receiveShadow = true;
    mesh.geometry.computeBoundingSphere();
  }

  landmarks.push(
    {
      id: "harbor_ruins_entrance",
      position: new THREE.Vector3(STAIR.top.x, STAIR.top.y + 2, STAIR.top.z),
    },
    {
      id: "harbor_ruins_shaft",
      position: new THREE.Vector3((SHAFT.minX + SHAFT.maxX) / 2, -160, -247),
    },
    {
      id: "harbor_ruins_lower_hall",
      position: new THREE.Vector3(
        SITE.turningCircle.x,
        SITE.turningCircle.y,
        SITE.turningCircle.z,
      ),
    },
  );
  // 室内鱼群沿真实墙体避障，不能用整栋包围球把两层水域都排除掉。

  const stats = {
    site: SITE.id,
    meshes: owned.size,
    colliders: colliders.length,
    triangles: [...owned].reduce(
      (sum, geometry) => sum + geometry.attributes.position.count / 3,
      0,
    ),
    levels: SITE.levels.length,
    pearls: 2,
  };
  root.userData.harborRuinsStats = stats;
  let disposed = false;
  return {
    root,
    colliders,
    obstacles,
    landmarks,
    lightSources,
    records: SITE.routes,
    stats,
    update(time, dt, position, highQuality = true) {
      if (disposed) return;
      root.visible =
        !position ||
        Math.hypot(-215 - position.x, -248 - position.z) <
          (highQuality ? 400 : 330);
      void time;
      void dt;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      parent.remove(root);
      for (const geometry of owned) geometry.dispose();
      owned.clear();
      root.clear();
      colliders.length =
        obstacles.length =
        landmarks.length =
        lightSources.length =
          0;
    },
  };
}

/*********************************************
 * 装配工具:可见体与碰撞共用尺寸与变换
 *********************************************/

class HallBuilder {
  constructor(colliders) {
    this.bucket = new MergeBucket();
    this.colliders = colliders;
    this.ordinal = 0;
  }
  add(geometry, material, x, y, z, options = {}) {
    const { quaternion = null, tint = null, tile = null } = options;
    paintStone(geometry, {
      base:
        tint ??
        (material === "bronze"
          ? "#668b84"
          : material === "marble"
            ? "#d3d2bc"
            : "#a6b7ae"),
      algaeAmount: material === "stone" ? 0.26 : 0.14,
      seed: 547 + this.ordinal++,
    });
    this.bucket.add(geometry, material, {
      position: [x, y, z],
      quaternion,
      tile: tile ?? (material === "stone" ? 11 : 18),
    });
    geometry.dispose();
  }
  /** 直接并入已带顶点色的构件(贝珠壳体等),不再做石材着色。 */
  addRaw(geometry, materialKey, x, y, z, euler = null) {
    this.bucket.add(geometry, materialKey, { position: [x, y, z], euler });
  }
  box(material, w, h, d, x, y, z, options = {}) {
    const {
      solid = true,
      quaternion = null,
      kind = "harbor_ruin_masonry",
      tint = null,
    } = options;
    this.add(new THREE.BoxGeometry(w, h, d), material, x, y, z, {
      quaternion,
      tint,
    });
    if (solid) {
      const collider = {
        type: "box",
        kind,
        x,
        y,
        z,
        halfSize: { x: w / 2, y: h / 2, z: d / 2 },
      };
      if (quaternion)
        collider.rotation = {
          x: quaternion[0],
          y: quaternion[1],
          z: quaternion[2],
          w: quaternion[3],
        };
      this.colliders.push(collider);
    }
  }
  /** 凹槽柱:方础、放样柱身、环形箍与柱头板;胶囊碰撞与柱身同位。 */
  column(x, z, floorY, topY, radius) {
    const height = topY - floorY;
    this.box("marble", radius * 3, 1, radius * 3, x, floorY + 0.5, z, {
      kind: "harbor_ruin_column",
    });
    const shaft = loftGeometry(
      null,
      [
        { y: 0, rx: radius, rz: radius, wave: 20, waveAmp: 0.07 },
        {
          y: height * 0.5,
          rx: radius * 0.94,
          rz: radius * 0.94,
          wave: 20,
          waveAmp: 0.07,
        },
        {
          y: height - 2,
          rx: radius * 0.8,
          rz: radius * 0.8,
          wave: 20,
          waveAmp: 0.07,
        },
      ],
      { radial: 20, subdivision: 0.4, capStart: true, capEnd: true },
    );
    this.add(shaft, "marble", x, floorY + 1, z);
    this.colliders.push({
      type: "capsule",
      kind: "harbor_ruin_column",
      a: { x, y: floorY + radius, z },
      b: { x, y: topY - 1 - radius, z },
      radius: radius * 1.05,
    });
    this.box("marble", radius * 3, 1, radius * 3, x, topY - 0.5, z, {
      kind: "harbor_ruin_column",
    });
    for (const dy of [1.6, height - 1.6])
      this.add(
        new THREE.CylinderGeometry(radius * 1.16, radius * 1.22, 0.45, 20),
        "marble",
        x,
        floorY + dy,
        z,
      );
  }
}

/*********************************************
 * 围合墙体:北墙让出台阶通道,南墙开第二出口拱门
 *********************************************/

function buildWalls(b) {
  const top = UPPER.ceilingY;
  const height = top - WALL_BOTTOM;
  const y = WALL_BOTTOM + height / 2;
  // 北墙入口与屋面同宽，背墙低于斜板最深一侧，不让实心墙顶伸进台阶。
  const entry = STAIR.roofOpening;
  for (const [left, right] of [
    [-252, entry.minX],
    [entry.maxX, -178],
  ])
    b.box("stone", right - left, height, 4.5, (left + right) / 2, y, -222.25);
  const stairSlope =
    (STAIR.bottom.y - STAIR.top.y) / (STAIR.bottom.z - STAIR.top.z);
  const backTop = STAIR.top.y + (WALL_N - STAIR.top.z) * stairSlope - 1.8;
  b.box(
    "stone",
    entry.maxX - entry.minX,
    backTop - WALL_BOTTOM,
    4.5,
    STAIR.top.x,
    (backTop + WALL_BOTTOM) / 2,
    -222.25,
    { kind: "harbor_ruin_masonry" },
  ); // 台阶背墙
  // 南墙(2.5m 厚):拱门开口 x∈[-222,-208]、y∈[-156,-142]
  b.box("stone", 30, height, 2.5, -237, y, -274.75); // 西段
  b.box("stone", 30, height, 2.5, -193, y, -274.75); // 东段
  b.box(
    "stone",
    14,
    -156 - WALL_BOTTOM,
    2.5,
    -215,
    (-156 + WALL_BOTTOM) / 2,
    -274.75,
  ); // 门坎下段
  b.box("stone", 14, top - -142, 2.5, -215, (top + -142) / 2, -274.75); // 门楣
  // 西墙(4.5m 厚)与东墙(2.5m 厚)整面
  b.box("stone", 4.5, height, 56, -249.75, y, -248);
  b.box("stone", 2.5, height, 56, -179.25, y, -248);
  // 墙顶内饰线脚(视觉,贴面不出碰撞)
  for (const ledgeY of [-160.2, -137.6]) {
    b.box("marble", 67, 1.6, 1.1, -214, ledgeY, WALL_N - 0.55, {
      solid: false,
    });
    b.box("marble", 67, 1.6, 1.1, -214, ledgeY, WALL_S + 0.55, {
      solid: false,
    });
    b.box("marble", 1.1, 1.6, 49, WALL_W + 0.55, ledgeY, -249, {
      solid: false,
    });
    b.box("marble", 1.1, 1.6, 49, WALL_E - 0.55, ledgeY, -249, {
      solid: false,
    });
  }
}

/*********************************************
 * 屋面顶板:独立静态盒,北缘台阶塌口 + 中央竖井 + 南缘翻越塌口
 *********************************************/

function buildRoof(b) {
  const h = ROOF_TOP - UPPER.ceilingY; // 2.5
  const y = (ROOF_TOP + UPPER.ceilingY) / 2;
  // 开口按元数据切分，可见屋板与实体同时避开整段台阶及成年转向竖井。
  const bounds = { minX: -253.5, maxX: -176.5, minZ: -277.5, maxZ: -218.5 };
  const openings = [
    STAIR.roofOpening,
    SHAFT,
    { minX: -222, maxX: -206, minZ: -277.5, maxZ: -273 },
  ];
  const xs = [
    ...new Set([
      bounds.minX,
      bounds.maxX,
      ...openings.flatMap((o) => [o.minX, o.maxX]),
    ]),
  ].sort((a, b) => a - b);
  const zs = [
    ...new Set([
      bounds.minZ,
      bounds.maxZ,
      ...openings.flatMap((o) => [o.minZ, o.maxZ]),
    ]),
  ].sort((a, b) => a - b);
  for (let ix = 1; ix < xs.length; ix++)
    for (let iz = 1; iz < zs.length; iz++) {
      const x = (xs[ix - 1] + xs[ix]) / 2,
        z = (zs[iz - 1] + zs[iz]) / 2;
      if (
        openings.some(
          (o) => x > o.minX && x < o.maxX && z > o.minZ && z < o.maxZ,
        )
      )
        continue;
      b.box("stone", xs[ix] - xs[ix - 1], h, zs[iz] - zs[iz - 1], x, y, z, {
        kind: "harbor_ruin_roof",
      });
    }
  // 竖井在屋面层的井口与楼板层同口对齐;井缘残件与断门标记开口。
  const stubs = [
    [SHAFT.minX - 1.5, SHAFT.minZ - 0.8, 2.6, 1.1],
    [SHAFT.maxX + 1.5, SHAFT.minZ - 0.8, 2.6, 0.8],
    [SHAFT.minX - 1.5, SHAFT.maxZ + 0.8, 2.6, 1.4],
    [SHAFT.maxX + 1.5, SHAFT.maxZ + 0.8, 2.6, 0.9],
    [SHAFT.minX - 0.8, -247, 1.1, 2.2],
    [SHAFT.maxX + 0.8, -247, 1.1, 1.6],
  ];
  for (const [x, z, w, hh] of stubs)
    b.box("marble", w, hh, 1.1, x, ROOF_TOP + hh / 2, z, {
      kind: "harbor_ruin_roof",
    });
  // 井口北侧的断门残框(立于井缘之外,不遮挡竖井)
  b.box("marble", 1.6, 6, 1.6, SHAFT.minX - 1, ROOF_TOP + 3, SHAFT.maxZ + 1, {
    kind: "harbor_ruin_roof",
  });
  b.box("marble", 1.6, 6, 1.6, SHAFT.maxX + 1, ROOF_TOP + 3, SHAFT.maxZ + 1, {
    kind: "harbor_ruin_roof",
  });
  b.box(
    "marble",
    SHAFT.maxX - SHAFT.minX + 3.6,
    1.6,
    1.6,
    (SHAFT.minX + SHAFT.maxX) / 2,
    ROOF_TOP + 6.8,
    SHAFT.maxZ + 1,
    {
      kind: "harbor_ruin_roof",
    },
  );
  // 南缘与东缘的断续栏墙(南缘塌口 x∈[-222,-206] 留空)
  for (const [x0, x1] of [
    [-253, -248],
    [-243, -237],
    [-232, -226],
    [-200, -194],
    [-190, -180],
  ])
    b.box("marble", x1 - x0, 1.1, 0.8, (x0 + x1) / 2, ROOF_TOP + 0.55, -276.9, {
      kind: "harbor_ruin_roof",
    });
  for (const [z0, z1] of [
    [-272, -266],
    [-258, -252],
    [-236, -230],
  ])
    b.box("marble", 0.8, 1.1, z1 - z0, -177.1, ROOF_TOP + 0.55, (z0 + z1) / 2, {
      kind: "harbor_ruin_roof",
    });
  // 屋面翻起与碎裂的铺板(视觉),避免一整块平板的空旷感。
  const random = seededRandom(6201);
  for (let i = 0; i < 12; i++) {
    const x = -248 + random() * 66;
    const z = -272 + random() * 48;
    if (
      (x > SHAFT.minX - 2 &&
        x < SHAFT.maxX + 2 &&
        z > SHAFT.minZ - 2 &&
        z < SHAFT.maxZ + 2) ||
      (x > STAIR.roofOpening.minX - 2 &&
        x < STAIR.roofOpening.maxX + 2 &&
        z > STAIR.roofOpening.minZ - 2)
    )
      continue;
    b.box(
      "stone",
      2.5 + random() * 2.5,
      0.5,
      1.8 + random() * 2,
      x,
      ROOF_TOP + 0.22,
      z,
      { solid: false, tint: "#93a69e" },
    );
  }
}

