    [SHAFT.maxX, WALL_E, WALL_S, WALL_N], // 东条
    [SHAFT.minX, SHAFT.maxX, WALL_S, SHAFT.minZ], // 南条
    [SHAFT.minX, SHAFT.maxX, SHAFT.maxZ, WALL_N], // 北条
  ];
  for (const [x0, x1, z0, z1] of frame)
