      SHAFT.maxZ + 0.4,
      SHAFT.maxX - SHAFT.minX + 1.6,
      0.8,
    ],
    [SHAFT.minX - 0.4, -247, 0.8, SHAFT.maxZ - SHAFT.minZ + 1.6],
    [SHAFT.maxX + 0.4, -247, 0.8, SHAFT.maxZ - SHAFT.minZ + 1.6],
