      tint: "#526e75",
    });
  // 上层展厅保留同样的嵌石图案，真正光源仍是有壳体的贝珠。
  for (const x of [-232, -215, -198])
    b.box("stone", 1.0, 6, 0.3, x, UPPER.floorY + 6, WALL_N - 0.16, {
