}

function storageChest(b, x, floor, z) {
  b.box("stone", 2.2, 1.05, 1.4, x, floor + 0.55, z, {
    solid: false,
    tint: "#8d9a90",
  });
  b.box("marble", 2.3, 0.5, 1.5, x, floor + 1.32, z, { solid: false });
  for (const dx of [-0.75, 0, 0.75])
    b.box("bronze", 0.18, 1.62, 1.52, x + dx, floor + 0.83, z, {
      solid: false,
    });
  for (const dx of [-0.52, 0.52]) {
    const shell = cachedGeometry("harbor_chest_inlay", () => {
      const g = new THREE.CylinderGeometry(0.2, 0.2, 0.07, 12);
      const colors = new Float32Array(g.attributes.position.count * 3).fill(
        0.9,
      );
      g.setAttribute("color", new THREE.BufferAttribute(colors, 3));
      return g;
    });
    b.addRaw(shell, "nacre", x + dx, floor + 1.34, z + 0.76, [
      Math.PI / 2,
      0,
      0,
    ]);
  }
  b.colliders.push({
    type: "box",
    kind: "harbor_ruin_furniture",
    x,
    y: floor + 0.8,
    z,
    halfSize: { x: 1.15, y: 0.8, z: 0.75 },
  });
}

function amphoraCluster(b, x, floor, z, count, seed) {
  const random = seededRandom(seed);
  b.box("stone", 3.6, 0.35, 2.8, x, floor + 0.17, z, {
    solid: false,
    tint: "#97a79e",
  });
  const jar = cachedGeometry("harbor_amphora", () => {
    const points = [
      [0, 0],
      [0.36, 0.1],
      [0.5, 0.3],
      [0.64, 0.85],
      [0.52, 1.4],
      [0.23, 1.62],
      [0.2, 1.9],
      [0.31, 2.0],
    ].map(([px, py]) => new THREE.Vector2(px, py));
    const g = new THREE.LatheGeometry(points, 16);
    paintStone(g, { base: "#9c816a", algaeAmount: 0.22, seed: 91 });
    return g;
  });
  const handle = cachedGeometry("harbor_amphora_handle", () => {
    const g = new THREE.TorusGeometry(0.3, 0.07, 6, 14, Math.PI * 1.65);
    const colors = new Float32Array(g.attributes.position.count * 3).fill(0.62);
    g.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    return g;
  });
  for (let i = 0; i < count; i++) {
    const angle = i * 2.399 + random() * 0.4;
    const px = x + Math.cos(angle) * (0.4 + (i % 3) * 0.55);
    const pz = z + Math.sin(angle) * (0.4 + (i % 2) * 0.6);
    const tipped = i === count - 1 && count > 3;
    const yaw = random() * Math.PI * 2;
    b.addRaw(
      jar,
      "bronze",
      px,
      floor + 0.36 + (tipped ? 0.35 : 0),
      pz,
      tipped ? [0, yaw, 1.32] : [0, yaw, 0],
    );
    if (!tipped)
      for (const side of [-1, 1])
        b.addRaw(
          handle,
          "bronze",
          px + Math.cos(yaw) * side * 0.45,
          floor + 0.36 + 1.5,
          pz - Math.sin(yaw) * side * 0.45,
          [0, yaw + (side * Math.PI) / 2, 0],
        );
  }
  b.colliders.push({
    type: "box",
    kind: "harbor_ruin_furniture",
    x,
    y: floor + 1.15,
    z,
    halfSize: { x: 1.8, y: 1.15, z: 1.4 },
  });
}

function treasureDais(b, x, floor, z) {
  b.box("stone", 5.2, 0.5, 5.2, x, floor + 0.25, z, {
    kind: "harbor_ruin_furniture",
  });
  b.box("marble", 3.9, 0.5, 3.9, x, floor + 0.75, z, {
    kind: "harbor_ruin_furniture",
  });
  // 宝箱:石胎箱体、做旧铜带、贝嵌与青金石锁孔;场景陈设,不是掉落系统。
  const y = floor + 1.0;
  b.box("stone", 2.8, 1.15, 1.8, x, y + 0.58, z, {
    solid: false,
    tint: "#7e8f86",
  });
  b.box("marble", 2.95, 0.55, 1.95, x, y + 1.42, z, { solid: false });
  for (const dx of [-0.95, 0, 0.95])
    b.box("bronze", 0.24, 1.85, 2.0, x + dx, y + 0.9, z, { solid: false });
  b.box("lapisGlow", 0.5, 0.7, 0.14, x, y + 0.95, z + 0.98, { solid: false });
  for (const dx of [-1.15, 1.15]) {
    const pearlDot = cachedGeometry("harbor_dais_pearl_inlay", () => {
      const g = new THREE.SphereGeometry(0.16, 10, 8);
      return g;
    });
    b.addRaw(pearlDot, "pearl", x + dx, y + 1.45, z + 0.99);
  }
  b.colliders.push({
    type: "box",
    kind: "harbor_ruin_furniture",
    x,
    y: y + 0.95,
    z,
    halfSize: { x: 1.48, y: 0.95, z: 1.0 },
  });
}

/*********************************************
 * 厅内贝珠生境:复用贝珠壁龛构件,提供柔和珠光而非电灯
 *********************************************/

function buildPearlNiches(b, lightSources) {
  const habitat = pearlHabitat({ detail: "niche" });
  for (const [x, floor, z, angle] of [
    [-238, LOWER.floorY - 0.2, -269.2, 0.35],
    [-188, UPPER.floorY - 0.2, -269.4, -0.3],
  ]) {
    lightSources.push({
      x,
      y: floor + habitat.lightHeight,
      z,
      color: "#ffe3ab",
      intensity: 800,
      distance: 60,
    });
    for (const part of habitat.parts)
      b.addRaw(part.geometry, part.key, x, floor, z, [0, angle, 0]);
    const sin = Math.sin(angle),
      cos = Math.cos(angle);
    for (const c of habitat.colliders) {
      const rotate = (p) => ({
        x: x + p.x * cos + p.z * sin,
        y: floor + p.y,
        z: z + (-p.x * sin + p.z * cos),
      });
      if (c.type === "capsule")
        b.colliders.push({
          ...c,
          a: rotate(c.a),
          b: rotate(c.b),
        });
      else {
        const rotation = new THREE.Quaternion().setFromAxisAngle(
          new THREE.Vector3(0, 1, 0),
          angle,
        );
        if (c.rotation)
          rotation.multiply(
            new THREE.Quaternion(
              c.rotation.x,
              c.rotation.y,
              c.rotation.z,
              c.rotation.w,
            ),
          );
        b.colliders.push({
          ...c,
          ...rotate(c),
          rotation: {
            x: rotation.x,
            y: rotation.y,
            z: rotation.z,
            w: rotation.w,
          },
        });
      }
    }
  }
}

atlantis_marine_anchors.js.source:
import * as THREE from "three";

/**
 * 从真实砌体碰撞面选取朝向入口的立面，避免用整栋包围盒猜测附着位置。
 * @param {Array<object>} colliders 城市最终静态碰撞体。
 * @param {object} options 入口 near、范围 maxDistance 和所需立面数量 count。
 * @returns {Array<object>} 含中心、法线、有效面宽、标高及宿主的立面锚点。
 */
export function selectMarineFacades(
  colliders,
  { near, maxDistance = 70, count = 1 },
) {
  const candidates = [];
  for (const host of colliders) {
    if (host.type !== "box" || host.kind !== "city_masonry") continue;
    const half = host.halfSize;
    if (
      half.y < 3 ||
      Math.min(half.x, half.z) > 2.5 ||
      Math.max(half.x, half.z) < 4
    )
      continue;
    const rotation = new THREE.Quaternion(
      host.rotation?.x ?? 0,
      host.rotation?.y ?? 0,
      host.rotation?.z ?? 0,
      host.rotation?.w ?? 1,
    );
    const up = new THREE.Vector3(0, 1, 0).applyQuaternion(rotation);
    if (up.y < 0.999) continue;
    const thinX = half.x < half.z;
    const normal = new THREE.Vector3(thinX ? 1 : 0, 0, thinX ? 0 : 1)
      .applyQuaternion(rotation)
      .normalize();
    if (normal.x * (near.x - host.x) + normal.z * (near.z - host.z) < 0)
      normal.negate();
    const thickness = thinX ? half.x : half.z;
    const center = {
      x: host.x + normal.x * thickness,
      z: host.z + normal.z * thickness,
    };
    const distance = Math.hypot(center.x - near.x, center.z - near.z);
    if (distance > maxDistance) continue;
    candidates.push({
      center,
      normal: { x: normal.x, z: normal.z },
      width: 2 * (thinX ? half.z : half.x) - 1,
      baseY: host.y - half.y + 0.2,
      topY: host.y + half.y - 0.2,
      host,
      distance,
    });
  }
  return candidates.sort((a, b) => a.distance - b.distance).slice(0, count);
}

atlantis_ocean.js.source:
import { createAtlantisRelic } from "./atlantis_relic.js";
import * as THREE from "three";
import { WORLD } from "./world_config.js";
import { atlantisSeabedHeight as seabedHeight } from "./atlantis_terrain.js";
import { createAtlantisTerrainMesh } from "./atlantis_terrain_mesh.js";
import { createAtlantisCity } from "./atlantis_city.js";
import { createAtlantisOutskirts } from "./atlantis_outskirts.js";
import {
  addLeafDetail,
  addSurfaceDetail,
  clusterInstances,
  coralBranchGeometry,
  moundCoralGeometry,
  ribbonGeometry,
  seaFanGeometry,
  smoothCoincidentNormals,
} from "./ocean_visuals.js";

/**
 * 创建亚特兰蒂斯海床、育幼礁与月光海面，城市使用独立美术模块。
 * @param {THREE.Scene} scene 世界场景，不改变全局光照或共享地形高度。
 * @returns {object} root、实体与地标，以及update(time,position,dt,highQuality)、dispose。
 */
export function createAtlantisOcean(scene) {
  const root = new THREE.Group();
  root.name = "ocean_environment";
  scene.add(root);
  const resources = new Set();
  const keep = (resource) => (resources.add(resource), resource);
  const time = { value: 0 };
  const random = randomSource(41739);
  const colliders = [];
  const obstacles = [];
  let disposed = false;
  const reducedMotion =
    typeof matchMedia === "function"
      ? matchMedia("(prefers-reduced-motion: reduce)")
      : null;

  root.add(createSeabed(keep, time));
  root.add(createMoonlitWater(keep, time));
  createOutskirts(root, keep, random, colliders, obstacles);
  const nursery = createNursery(root, keep, time, random);
  const city = createAtlantisCity(root, { heightAt: seabedHeight });
  const relic = createAtlantisRelic(root, { records: city.underways.records });
  colliders.push(...city.colliders);
  obstacles.push(...city.obstacles);
  const outskirts = createAtlantisOutskirts(root, {
    heightAt: seabedHeight,
    occupiedColliders: colliders,
  });
  colliders.push(...outskirts.colliders);
  obstacles.push(...outskirts.obstacles);

  return {
    root,
    heightAt: seabedHeight,
    city,
    relic,
    reset() {
      relic.reset();
    },
    outskirts,
    colliders,
    obstacles,
    landmarks: city.landmarks,
    update(elapsed, position, dt = 0, highQuality = true) {
      if (disposed) return;
      time.value = elapsed;
      relic.update(elapsed, position, reducedMotion?.matches || false);
      nursery.visible = position.z > -390;
      city.update(elapsed, dt, position, highQuality);
      outskirts.update(elapsed, position, dt, highQuality);
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      relic.dispose();
      outskirts.dispose();
      city.dispose();
      root.removeFromParent();
      root.traverse((node) => {
        if (node.isInstancedMesh) node.dispose();
      });
      for (const resource of resources) resource.dispose();
      resources.clear();
      colliders.length = 0;
      obstacles.length = 0;
      root.clear();
    },
  };
}

/** 珍珠沙、冷色岩层与城基石灰岩共用真实海床，视觉起伏不另造碰撞地形。 */
function createSeabed(keep, time) {
  const geometry = keep(
    createAtlantisTerrainMesh({
      minX: WORLD.minX - 60,
      maxX: WORLD.maxX + 60,
      minZ: WORLD.minZ - 120,
      maxZ: WORLD.maxZ,
      segmentsX: 144,
      segmentsZ: 282,
      heightAt: seabedHeight,
    }),
  );
  const positions = geometry.attributes.position;
  const colors = new Float32Array(positions.count * 3);
  const pearl = new THREE.Color("#bbc8c6");
  const slate = new THREE.Color("#687b84");
  const abyss = new THREE.Color("#2d414e");
  const marble = new THREE.Color("#7d989b");
  const color = new THREE.Color();
  for (let index = 0; index < positions.count; index++) {
    const x = positions.getX(index);
    const z = positions.getZ(index);
    const y = seabedHeight(x, z);
    positions.setY(index, y);
    const shelf = THREE.MathUtils.smoothstep(-z, 75, 390);
    const deep = THREE.MathUtils.smoothstep(-z, 420, 1080);
    color.copy(pearl).lerp(slate, shelf).lerp(abyss, deep);
    const cityDistance = Math.max(Math.abs(x) / 280, Math.abs(z + 590) / 500);
    const cityStone = 1 - THREE.MathUtils.smoothstep(cityDistance, 0.45, 1.2);
    color.lerp(marble, cityStone * 0.52);
    color.multiplyScalar(0.94 + Math.sin(x * 0.042 + z * 0.061) * 0.045);
    color.toArray(colors, index * 3);
  }
  geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  const material = keep(
    new THREE.MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.89,
      metalness: 0.035,
    }),
  );
  addSurfaceDetail(material, "stone", 0.22);
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous.call(material, shader, renderer);
    shader.uniforms.atlantisTime = time;
    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <common>",
        "#include <common>\nuniform float atlantisTime;",
      )
      .replace(
        "#include <color_fragment>",
        `#include <color_fragment>
        vec2 sandPoint = vSurfaceDetail.xz;
        float sandNear = 1.0 - smoothstep(0.4, 2.4, max(length(dFdx(sandPoint)), length(dFdy(sandPoint))));
        float shallow = 1.0 - smoothstep(45.0, 105.0, -vSurfaceDetail.y);
        float ripples = sin(sandPoint.x * 2.1 + sin(sandPoint.y * 0.17) * 2.7);
        diffuseColor.rgb *= 1.0 + ripples * shallow * sandNear * 0.028;
        float gleamA = sin(sandPoint.x * 0.75 + sin(sandPoint.y * 0.48) + atlantisTime * 0.19);
        float gleamB = cos(sandPoint.y * 0.83 + cos(sandPoint.x * 0.55) - atlantisTime * 0.14);
        float moonCaustic = pow(max(0.0, 1.0 - abs(gleamA + gleamB)), 16.0);
        diffuseColor.rgb += vec3(0.11, 0.17, 0.23) * moonCaustic * shallow * sandNear * 0.2;`,
      );
  };
  material.customProgramCacheKey = () => "atlantis_pearl_slate_seabed_v1";
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = "atlantis_pearl_slate_seabed";
  mesh.receiveShadow = true;
  return mesh;
}

/** 外围岩群采用有侵蚀细节的共享几何，城市与中央下潜通道不放随机巨石。 */
function createOutskirts(root, keep, random, colliders, obstacles) {
  const geometry = keep(new THREE.IcosahedronGeometry(1, 2));
  const positions = geometry.attributes.position;
  const vertex = new THREE.Vector3();
  for (let index = 0; index < positions.count; index++) {
    vertex.fromBufferAttribute(positions, index);
    const erosion =
      Math.sin(vertex.x * 5.8 + vertex.y * 3.2) *
        Math.cos(vertex.z * 5.4 - vertex.y * 2.7) *
        0.17 +
      Math.sin(vertex.z * 11.2 + vertex.x * 7.1) * 0.055;
    vertex.multiplyScalar(1 + erosion);
    positions.setXYZ(index, vertex.x, vertex.y, vertex.z);
  }
  geometry.computeVertexNormals();
  smoothCoincidentNormals(geometry);
  geometry.computeBoundingSphere();
  const envelope =
    geometry.boundingSphere.radius + geometry.boundingSphere.center.length();
  const material = keep(
    new THREE.MeshStandardMaterial({ color: "#849797", roughness: 0.93 }),
  );
  addSurfaceDetail(material, "stone", 0.85);
  const rocks = new THREE.InstancedMesh(geometry, material, 64);
  rocks.name = "atlantis_outcrop";
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  for (let index = 0; index < rocks.count; index++) {
    const shallow = index < 28;
    const x =
      (index % 2 ? 1 : -1) *
      (shallow ? 46 + random() * 63 : 285 + random() * 8);
    const z = shallow ? 126 - random() * 215 : -260 - random() * 870;
    const size = shallow ? 2.2 + random() * 3.5 : 5.5 + random() * 10;
    dummy.position.set(x, seabedHeight(x, z) + size * 0.2, z);
    dummy.rotation.set(
      (random() - 0.5) * 0.5,
      random() * Math.PI,
      (random() - 0.5) * 0.45,
    );
    dummy.scale.set(
      size * (0.9 + random() * 0.35),
      size * (0.6 + random() * 0.85),
      size,
    );
    dummy.updateMatrix();
    rocks.setMatrixAt(index, dummy.matrix);
    color
      .set(shallow ? "#9baaa2" : "#718087")
      .multiplyScalar(0.8 + random() * 0.3);
    rocks.setColorAt(index, color);
    const collider = {
      type: "ellipsoid",
      kind: "atlantis_reef",
      x,
      y: dummy.position.y,
      z,
      axes: {
        x: dummy.scale.x * envelope,
        y: dummy.scale.y * envelope,
        z: dummy.scale.z * envelope,
      },
      rotation: {
        x: dummy.quaternion.x,
        y: dummy.quaternion.y,
        z: dummy.quaternion.z,
        w: dummy.quaternion.w,
      },
    };
    colliders.push(collider);
    obstacles.push({
      x,
      y: collider.y,
      z,
      radius: Math.max(collider.axes.x, collider.axes.z),
    });
  }
  const clusters = clusterInstances(rocks, 120);
  clusters.traverse((node) => {
    if (node.isMesh) node.receiveShadow = true;
  });
  root.add(clusters);
}

/** 海扇、珊瑚与海草组成克制的月下礁园，按空间分批保留近景结构与远景裁剪。 */
function createNursery(root, keep, time, random) {
  const nursery = new THREE.Group();
  nursery.name = "atlantis_nursery_garden";
  root.add(nursery);
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  const palette = ["#b7b8c7", "#7ba6b4", "#c1a1ae", "#bdb9a2", "#83b1aa"];
  const addGroundCover = (geometry, material, count, name, placement) => {
    const mesh = new THREE.InstancedMesh(keep(geometry), keep(material), count);
    mesh.name = name;
    for (let index = 0; index < count; index++) {
      const patch = index % 9;
      const x =
        (patch % 2 ? -1 : 1) * (13 + (patch % 3) * 19) + (random() - 0.5) * 14;
      const z = 112 - Math.floor(patch / 2) * 51 + (random() - 0.5) * 27;
      const size = placement(index, x, z);
      dummy.position.set(x, seabedHeight(x, z) + size.offset, z);
      dummy.rotation.set(0, random() * Math.PI, (random() - 0.5) * 0.18);
      dummy.scale.set(size.x, size.y, size.z);
      dummy.updateMatrix();
      mesh.setMatrixAt(index, dummy.matrix);
      mesh.setColorAt(
        index,
        color
          .set(palette[index % palette.length])
          .multiplyScalar(0.88 + random() * 0.22),
      );
    }
    nursery.add(clusterInstances(mesh, 90));
  };
  const fanMaterial = new THREE.MeshStandardMaterial({
    color: "#bcc6d1",
    roughness: 0.78,
    side: THREE.DoubleSide,
  });
  addSway(fanMaterial, time, 0.018);
  addGroundCover(
    seaFanGeometry(),
    fanMaterial,
    64,
    "atlantis_silver_seafans",
    () => {
      const size = 1.2 + random() * 1.9;
      return { x: size, y: size, z: size, offset: 0 };
    },
  );
  const moundMaterial = new THREE.MeshStandardMaterial({
    roughness: 0.83,
    metalness: 0.025,
  });
  addSurfaceDetail(moundMaterial, "coral", 1.1);
  addGroundCover(
    moundCoralGeometry(),
    moundMaterial,
    82,
    "atlantis_coral_mounds",
    () => {
      const size = 0.45 + random() * 0.9;
      return { x: size, y: size * 0.65, z: size * 0.85, offset: size * 0.2 };
    },
  );
  const grassMaterial = new THREE.MeshStandardMaterial({
    color: "#598781",
    roughness: 0.92,
    side: THREE.DoubleSide,
  });
  addSway(grassMaterial, time, 0.15);
  addLeafDetail(grassMaterial);
  addGroundCover(
    ribbonGeometry(true),
    grassMaterial,
    360,
    "atlantis_seagrass",
    () => ({
      x: 0.8 + random() * 0.6,
      y: 1.3 + random() * 2.9,
      z: 0.8,
      offset: -0.08,
    }),
  );

  const branchMaterial = keep(
    new THREE.MeshStandardMaterial({ color: "#c7b7c1", roughness: 0.76 }),
  );
  addSurfaceDetail(branchMaterial, "coral", 1.4);
  const branches = new THREE.InstancedMesh(
    keep(coralBranchGeometry()),
    branchMaterial,
    240,
  );
  branches.name = "atlantis_branching_coral";
  const up = new THREE.Vector3(0, 1, 0);
  const start = new THREE.Vector3();
  const end = new THREE.Vector3();
  const direction = new THREE.Vector3();
  for (let cluster = 0; cluster < 40; cluster++) {
    const x = (cluster % 2 ? -1 : 1) * (19 + random() * 48);
    const z = 112 - random() * 227;
    const y = seabedHeight(x, z);
    const size = 0.8 + random() * 1.4;
    for (let branch = 0; branch < 6; branch++) {
      const angle = branch * 2.399;
      start.set(x, y + (branch ? size * 0.37 : 0), z);
      end.set(
        x + (branch ? Math.cos(angle) * size * 0.65 : 0),
        y + size * (1.0 + random() * 0.55),
        z + (branch ? Math.sin(angle) * size * 0.65 : 0),
      );
      direction.subVectors(end, start);
      dummy.position.copy(start).add(end).multiplyScalar(0.5);
      dummy.quaternion.setFromUnitVectors(up, direction.clone().normalize());
      dummy.scale.set(
        size * (branch ? 0.48 : 0.7),
        direction.length(),
        size * 0.48,
      );
      dummy.updateMatrix();
      branches.setMatrixAt(cluster * 6 + branch, dummy.matrix);
      branches.setColorAt(
        cluster * 6 + branch,
        color.set(palette[cluster % palette.length]),
      );
    }
  }
  nursery.add(clusterInstances(branches, 90));
  return nursery;
}

/** 沿用成熟水面的连续噪声梯度与像素足迹过滤，改成冷月反射而非日光亮带。 */
function createMoonlitWater(keep, time) {
  const material = keep(
    new THREE.ShaderMaterial({
      uniforms: { oceanTime: time, waterLevel: { value: WORLD.surfaceY } },
      vertexShader: `uniform float oceanTime; varying vec3 vWorld;
      void main() {
        vec3 p = position;
        p.z += sin(p.x * 0.052 + oceanTime * 0.25) * 0.10
          + sin(p.x * 0.022 + p.y * 0.018 - oceanTime * 0.15) * 0.16;
        vec4 world = modelMatrix * vec4(p, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }`,
      fragmentShader: `uniform float oceanTime; uniform float waterLevel; varying vec3 vWorld;
      float rippleHash(vec2 p) {
        vec3 q = fract(vec3(p.xyx) * 0.1031);
        q += dot(q, q.yzx + 33.33);
        return fract((q.x + q.y) * q.z);
      }
      vec3 rippleNoise(vec2 p) {
        vec2 i = floor(p), f = fract(p);
        vec2 u = f*f*(3.0-2.0*f), du = 6.0*f*(1.0-f);
        float a = rippleHash(i), b = rippleHash(i+vec2(1,0));
        float c = rippleHash(i+vec2(0,1)), d = rippleHash(i+vec2(1,1));
        float k = a-b-c+d;
        return vec3(a+(b-a)*u.x+(c-a)*u.y+k*u.x*u.y, ((b-a)+k*u.y)*du.x, ((c-a)+k*u.x)*du.y);
      }
      void main() {
        vec2 p = vWorld.xz;
        float dist = distance(cameraPosition, vWorld);
        float footprint = max(length(dFdx(p)), length(dFdy(p)));
        mat2 turn = mat2(0.8,-0.6,0.6,0.8), back = mat2(0.8,0.6,-0.6,0.8);
        vec3 broad = rippleNoise(p*vec2(0.70,0.37)+vec2(oceanTime*0.10,-oceanTime*0.04));
        vec3 middle = rippleNoise(turn*p*vec2(2.7,1.6)+vec2(-oceanTime*0.20,oceanTime*0.07));
        vec3 fine = rippleNoise(back*p*vec2(7.2,3.8)+vec2(oceanTime*0.30,oceanTime*0.12));
        float broadFilter = 1.0-smoothstep(0.35,1.4,footprint*0.70);
        float middleFilter = 1.0-smoothstep(0.35,1.4,footprint*2.7);
        float fineFilter = 1.0-smoothstep(0.35,1.4,footprint*7.2);
        vec2 slope = broad.yz*vec2(0.70,0.37)*0.075*broadFilter;
        slope += back*(middle.yz*vec2(2.7,1.6))*0.027*middleFilter;
        slope += turn*(fine.yz*vec2(7.2,3.8))*0.009*fineFilter;
        vec3 normal = normalize(vec3(-slope.x,1.0,-slope.y));
        vec3 eye = normalize(cameraPosition-vWorld);
        float above = step(waterLevel,cameraPosition.y);
        float viewNormal = clamp(abs(dot(normal,eye)),0.0,1.0);
        float fresnel = 0.025+0.975*pow(1.0-viewNormal,5.0);
        vec3 reflected = reflect(-eye,normal);
        vec3 sky = mix(vec3(0.018,0.040,0.067),vec3(0.008,0.017,0.040),smoothstep(-0.1,0.8,reflected.y));
        float moon = max(0.0,dot(reflected,normalize(vec3(-0.42,0.75,-0.5))));
        float moonGlow = pow(moon,36.0)*0.055;
        float glint = pow(moon,480.0)*(0.35+0.65*fineFilter);
        sky += vec3(0.45,0.63,0.81)*(glint*0.9+moonGlow);
        vec3 top = mix(vec3(0.010,0.039,0.062),sky,0.20+fresnel*0.74);
        float windowMask = smoothstep(0.54,0.78,viewNormal);
        vec3 below = mix(vec3(0.016,0.056,0.090),vec3(0.055,0.125,0.175),windowMask);
        below += vec3(0.008,0.015,0.024)*(broad.x-0.5)*broadFilter;
        float belowAlpha = mix(0.49,0.20,windowMask)*exp(-dist*0.0035);
        gl_FragColor = vec4(mix(below,top,above),mix(belowAlpha,0.97,above));
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`,
      side: THREE.DoubleSide,
      transparent: true,
      depthWrite: false,
    }),
  );
  const mesh = new THREE.Mesh(
    keep(new THREE.PlaneGeometry(1100, 2600, 52, 120)),
    material,
  );
  mesh.name = "atlantis_moonlit_water";
  mesh.position.set(0, WORLD.surfaceY, (WORLD.minZ + WORLD.maxZ) * 0.5);
  mesh.rotation.x = -Math.PI / 2;
  mesh.renderOrder = 1;
  return mesh;
}

/** 只摆动植物上端；根部与模型中心保持原位，不改变碰撞或生态锚点。 */
function addSway(material, time, strength) {
  material.onBeforeCompile = (shader) => {
    shader.uniforms.atlantisTime = time;
    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        "#include <common>\nuniform float atlantisTime;",
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
        float phase = 0.0;
        #ifdef USE_INSTANCING
          phase = instanceMatrix[3].x*0.17+instanceMatrix[3].z*0.08;
        #endif
        transformed.x += sin(atlantisTime*0.65+phase+position.y)*pow(max(0.0,position.y),2.0)*${strength.toFixed(3)};`,
      );
  };
  material.customProgramCacheKey = () => `atlantis_sway_${strength}_v1`;
}

function randomSource(seed) {
  let state = seed;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

atlantis_outskirts.js.source:
import * as THREE from "three";
import {
  MergeBucket,
  cachedGeometry,
  paintStone,
  seededRandom,
} from "./atlantis_art_geometry.js";
import { cityArchitecture } from "./atlantis_architecture.js";
import { addSurfaceDetail, seaFanGeometry } from "./ocean_visuals.js";
import { createStaticColliderGrid } from "./static_collider_grid.js";

/**
 * 在城外合法空地建造低矮沉物与冷色海底花园，主街、育幼区保持原样。
 * @param {THREE.Object3D} parent 场景父节点。
 * @param {object} options heightAt 为共享海床，occupiedColliders 为现有静态实体。
 * @returns {object} 根节点、碰撞体、避障体、检查锚点、统计及更新/释放接口。
 */
export function createAtlantisOutskirts(
  parent,
  { heightAt, occupiedColliders = [] } = {},
) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error("Atlantis outskirts require a scene and seabed height");
  const root = new THREE.Group();
  root.name = "atlantis_dark_outskirts";
  parent.add(root);
  const time = { value: 0 };
  const materials = makeMaterials(time);
  const owned = new Set(Object.values(materials));
  const chunks = new Map();
  const colliders = [];
  const obstacles = [];
  const anchors = [];
  const random = seededRandom(918277);
  const grid = createStaticColliderGrid(occupiedColliders, { cellSize: 30 });
  const kits = sceneryKits();
  let disposed = false;

  function placePart(chunk, geometry, material, x, z, rotation, scale = 1) {
    geometry.computeBoundingBox();
    const matrix = new THREE.Matrix4().compose(
      new THREE.Vector3(x, 0, z),
      new THREE.Quaternion().setFromEuler(new THREE.Euler(...rotation)),
      new THREE.Vector3(scale, scale, scale),
    );
    const bounds = geometry.boundingBox.clone().applyMatrix4(matrix);
    // 海床坡面采样后沉入少量底缘，防止罐底、碎石悬空。
    let floor = Infinity;
    for (const px of [bounds.min.x, x, bounds.max.x])
      for (const pz of [bounds.min.z, z, bounds.max.z])
        floor = Math.min(floor, heightAt(px, pz));
    // 海扇/海绵只有中心细根接地，冠幅包围盒不能把整株压到坡下。
    if (material === "growth") floor = heightAt(x, z);
    const y = floor - bounds.min.y - 0.12;
    chunk.bucket.add(geometry, material, {
      position: [x, y, z],
      euler: rotation,
      scale,
    });
    return { x, y, z, scale, rotation, bounds };
  }

  function solid(chunk, kit, x, z, angle, scale = 1) {
    const slope = kit.followSlope
      ? (heightAt(x + Math.sin(angle) * 3, z + Math.cos(angle) * 3) -
          heightAt(x - Math.sin(angle) * 3, z - Math.cos(angle) * 3)) /
        6
      : 0;
    const q = new THREE.Quaternion()
      .setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle)
      .multiply(
        new THREE.Quaternion().setFromAxisAngle(
          new THREE.Vector3(1, 0, 0),
          -Math.atan(slope),
        ),
      );
    const euler = new THREE.Euler().setFromQuaternion(q);
    const rotation = [euler.x, euler.y, euler.z];
    const placed = placePart(
      chunk,
      kit.geometry,
      "stone",
      x,
      z,
      rotation,
      scale,
    );
    if (kit.detail)
      chunk.bucket.add(kit.detail, "groove", {
        position: [x, placed.y, z],
        euler: rotation,
        scale,
      });
    for (const local of kit.colliders) {
      const center = new THREE.Vector3(local.x, local.y, local.z)
        .multiplyScalar(scale)
        .applyQuaternion(q)
        .add(new THREE.Vector3(x, placed.y, z));
      colliders.push({
        type: "box",
        kind: "outskirts_remnant",
        x: center.x,
        y: center.y,
        z: center.z,
        halfSize: {
          x: local.halfSize.x * scale,
          y: local.halfSize.y * scale,
          z: local.halfSize.z * scale,
        },
        rotation: { x: q.x, y: q.y, z: q.z, w: q.w },
      });
    }
    obstacles.push({
      x,
      y: placed.y + 1.1 * scale,
      z,
      radius: kit.radius * scale,
    });
  }

  function garden(x, z, kind) {
    // 整个组合的水平包络限定在 5.4m 内，预筛也包含轻微海流摆幅。
    const radius = 5.4;
    if (grid.query({ x, z }, undefined, { padding: radius + 0.65 }).length)
      return false;
    if (anchors.some((anchor) => Math.hypot(x - anchor.x, z - anchor.z) < 18))
      return false;
    const key = `${Math.sign(x)}:${Math.floor(z / 180)}`;
    if (!chunks.has(key)) {
      const group = new THREE.Group();
      group.name = `outskirts_sector_${key}`;
      root.add(group);
      chunks.set(key, { group, bucket: new MergeBucket(), anchors: [] });
    }
    const chunk = chunks.get(key);
    const anchor = { kind, x, y: heightAt(x, z), z, radius };
    anchors.push(anchor);
    chunk.anchors.push(anchor);
    const angle = random() * Math.PI * 2;
    if (kind === "fallen_column") solid(chunk, kits.column, x, z, angle, 0.9);
    if (kind === "inscribed_stele") {
      solid(chunk, kits.stele, x, z, angle, 0.9);
      solid(chunk, kits.fragment, x + 2.1, z + 1.5, angle + 1.1, 0.65);
    }
    if (kind === "cargo_cache") {
      solid(chunk, kits.fragment, x - 0.8, z - 0.8, angle, 0.7);
      for (let i = 0; i < 5; i++) {
        const a = i * 2.399;
        const px = x + Math.sin(a) * (0.8 + i * 0.3);
        const pz = z + Math.cos(a) * (0.8 + i * 0.3);
        const tilt = i === 1 || i === 4 ? 1.28 : 0.1 + random() * 0.15;
        placePart(chunk, kits.amphora, "ceramic", px, pz, [tilt, a, 0], 0.7);
      }
    }
    for (let i = 0; i < 4; i++) {
      const a = angle + i * 1.75;
      const px = x + Math.cos(a) * (3.6 + random() * 0.3);
      const pz = z + Math.sin(a) * (3.6 + random() * 0.3);
      placePart(
        chunk,
        kits.fan,
        "growth",
        px,
        pz,
        [0, a + 0.3, 0],
        0.9 + random() * 0.65,
      );
    }
    for (let i = 0; i < 6; i++) {
      const a = angle + i * 2.399;
      const px = x + Math.cos(a) * (2.4 + random() * 1.7);
      const pz = z + Math.sin(a) * (2.4 + random() * 1.7);
      const scale = 0.5 + random() * 0.65;
      const placed = placePart(
        chunk,
        kits.sponge,
        "growth",
        px,
        pz,
        [0, a, 0],
        scale,
      );
      chunk.bucket.add(kits.lip, "tips", {
        position: [px, placed.y, pz],
        euler: [0, a, 0],
        scale,
      });
    }
    return true;
  }

  const kinds = ["inscribed_stele", "cargo_cache", "fallen_column"];
  for (const side of [-1, 1]) {
    for (let row = 0; row < 11; row++) {
      const z = -164 - row * 88;
      for (const x of [258, 271, 246])
        if (garden(side * x, z, kinds[(row + (side > 0 ? 1 : 0)) % 3])) break;
    }
  }
  for (const [index, x] of [-248, -180, -110, -40, 40, 110, 180, 248].entries())
    garden(x, -1112 - (index % 2) * 8, kinds[index % 3]);

  let triangles = 0;
  let meshes = 0;
  for (const chunk of chunks.values()) {
    const built = chunk.bucket.build(materials, chunk.group, owned);
    for (const mesh of built) {
      mesh.name = `outskirts_${mesh.name}`;
      mesh.geometry.computeBoundingSphere();
      if (mesh.material === materials.growth)
        mesh.geometry.boundingSphere.radius += 0.15;
      triangles +=
        (mesh.geometry.index?.count ??
          mesh.geometry.attributes.position.count) / 3;
      meshes++;
    }
    chunk.bucket = null;
  }
  const stats = Object.freeze({
    source:
      "Original procedural outskirts; existing Atlantis amphora and ocean sea-fan geometry reused",
    clusters: anchors.length,
    remnants: anchors.filter((anchor) => anchor.kind !== "cargo_cache").length,
    cargoCaches: anchors.filter((anchor) => anchor.kind === "cargo_cache")
      .length,
    seaFans: anchors.length * 4,
    sponges: anchors.length * 6,
    meshes,
    triangles,
    colliders: colliders.length,
    pointLights: 0,
    chunks: chunks.size,
  });
  root.userData.outskirtsStats = stats;

  return {
    root,
    colliders,
    obstacles,
    anchors,
    stats,
    update(elapsed, position, dt = 0, highQuality = true) {
      if (disposed) return;
      time.value = elapsed;
      if (!position) return;
      const distance = highQuality ? 270 : 185;
      for (const chunk of chunks.values())
        chunk.group.visible = chunk.anchors.some(
          (anchor) =>
            Math.hypot(
              position.x - anchor.x,
              position.y - anchor.y,
              position.z - anchor.z,
            ) < distance,
        );
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      root.removeFromParent();
      for (const resource of owned) resource.dispose();
      owned.clear();
      root.clear();
      chunks.clear();
      colliders.length = 0;
      obstacles.length = 0;
      anchors.length = 0;
    },
  };
}

function makeMaterials(time) {
  const stone = addSurfaceDetail(
    new THREE.MeshStandardMaterial({
      color: "#839499",
      vertexColors: true,
      roughness: 0.98,
      metalness: 0.02,
    }),
    "stone",
    2,
  );
  const groove = new THREE.MeshStandardMaterial({
    color: "#304349",
    vertexColors: true,
    roughness: 1,
  });
  const ceramic = addSurfaceDetail(
    new THREE.MeshStandardMaterial({
      color: "#769093",
      vertexColors: true,
      roughness: 0.92,
      metalness: 0.02,
      side: THREE.DoubleSide,
    }),
    "stone",
    3,
  );
  const growth = addSurfaceDetail(
    new THREE.MeshStandardMaterial({
      color: "#62787e",
      vertexColors: true,
      roughness: 0.93,
      side: THREE.DoubleSide,
    }),
    "coral",
    2.2,
  );
  const original = growth.onBeforeCompile;
  growth.onBeforeCompile = (shader, renderer) => {
    original.call(growth, shader, renderer);
    shader.uniforms.outskirtsTime = time;
    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        "#include <common>\nuniform float outskirtsTime;",
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
        transformed.x += sin(position.z * 0.13 + outskirtsTime * 0.52) * uv.y * uv.y * 0.065;
        transformed.z += cos(position.x * 0.15 + outskirtsTime * 0.41) * uv.y * uv.y * 0.04;`,
      );
  };
  growth.customProgramCacheKey = () => "atlantis_outskirts_growth_v1";
  // 只有杯口一圈细窄组织发微光；原创幻想附生群落，不作真实物种声明。
  const tips = new THREE.MeshStandardMaterial({
    color: "#638b93",
    vertexColors: true,
    emissive: "#39777e",
    emissiveIntensity: 0.22,
    roughness: 0.88,
    side: THREE.DoubleSide,
  });
  return { stone, groove, ceramic, growth, tips };
}

let KITS = null;

function sceneryKits() {
  if (KITS) return KITS;
  const fan = cachedGeometry("outskirts_fan_v1", () => {
    const geometry = seaFanGeometry();
    const p = geometry.attributes.position;
    const uv = new Float32Array(p.count * 2);
    for (let i = 0; i < p.count; i++)
      uv[i * 2 + 1] = Math.max(0, p.getY(i)) * 0.8;
    geometry.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
    return paintStone(geometry, { base: "#8ea39e", algaeAmount: 0.12 });
  });
  const sponge = cachedGeometry("outskirts_hollow_sponge_v1", () =>
    spongeGeometry(false),
  );
  const lip = cachedGeometry("outskirts_sponge_lip_v1", () =>
    spongeGeometry(true),
  );
  const amphora = cityArchitecture("amphora").parts[0].geometry;
  KITS = {
    fan,
    sponge,
    lip,
    amphora,
    column: columnKit(),
    stele: steleKit(),
    fragment: fragmentKit(),
  };
  return KITS;
}

/** 断柱的沟槽贯穿柱身，斜断面、碎齿和两道柱箍属于真实轮廓。 */
function columnKit() {
  const geometry = cachedGeometry("outskirts_broken_column_v1", () => {
    const positions = [],
      indices = [];
    const sides = 48,
      rows = 7;
    for (let row = 0; row <= rows; row++) {
      const t = row / rows;
      for (let side = 0; side < sides; side++) {
        const a = (side / sides) * Math.PI * 2;
        const r =
          (0.79 - t * 0.07) * (1 + 0.07 * Math.cos(a * 16)) +
          (row === 1 || row === 5 ? 0.08 : 0);
        const end =
          row === rows ? Math.sin(a * 3 + 1) * 0.13 + Math.cos(a) * 0.18 : 0;
        positions.push(
          Math.cos(a) * r,
          0.87 + Math.sin(a) * r,
          -2.85 + t * 5.7 + end,
        );
        if (row < rows) {
          const k = row * sides + side,
            n = row * sides + ((side + 1) % sides);
          indices.push(k, n, k + sides, n, n + sides, k + sides);
        }
      }
    }
    for (const row of [0, rows]) {
      const center = positions.length / 3;
      positions.push(0, 0.87, row ? 2.85 : -2.85);
      for (let side = 0; side < sides; side++) {
        const a = row * sides + side,
          b = row * sides + ((side + 1) % sides);
        if (row) indices.push(center, a, b);
        else indices.push(center, b, a);
      }
    }
    return stoneGeometry(positions, indices, "#9ca9a3");
  });
  // 八条薄盒贴合柱身圆截面，保留扁平断口，不用膨胀的胶囊端帽。
  const colliders = [];
  for (let i = 0; i < 8; i++) {
    const x = -0.84 + (i + 0.5) * 0.21;
    const near = Math.max(0, Math.abs(x) - 0.105);
    colliders.push({
      x,
      y: 0.87,
      z: -0.03,
      halfSize: { x: 0.105, y: Math.sqrt(0.85 ** 2 - near ** 2), z: 2.86 },
    });
  }
  return { geometry, colliders, radius: 2.95, followSlope: true };
}

/** 缺角碑的分层边框和刻纹在近景仍有厚度，倾倒碎片沿用相同石工语言。 */
function steleKit() {
  const outline = [
    [-1.25, 0],
    [1.25, 0],
    [1.25, 3.15],
    [0.7, 3.42],
    [0.56, 4.42],
    [-0.38, 4.22],
    [-0.66, 3.72],
    [-1.25, 3.85],
  ];
  const geometry = cachedGeometry("outskirts_stele_v1", () => {
    const shape = new THREE.Shape(
      outline.map(([x, y]) => new THREE.Vector2(x, y)),
    );
    const result = new THREE.ExtrudeGeometry(shape, {
      depth: 0.6,
      bevelEnabled: true,
      bevelThickness: 0.07,
      bevelSize: 0.06,
      bevelSegments: 1,
      steps: 1,
    });
    result.translate(0, 0, -0.3);
    return paintStone(result, { base: "#a4b0a5", algaeAmount: 0.4 });
  });
  const detail = cachedGeometry("outskirts_stele_inscription_v1", () => {
    const bucket = new MergeBucket();
    const add = (geometry, position, euler = null) => {
      paintStone(geometry, { base: "#687c7b", algaeAmount: 0.15 });
      bucket.add(geometry, "detail", { position, euler });
      geometry.dispose();
    };
    for (const side of [-1, 1]) {
      add(new THREE.BoxGeometry(0.1, 2.72, 0.035), [side * 1.02, 1.61, 0.386]);
      add(new THREE.BoxGeometry(1.95, 0.1, 0.035), [
        0,
        side < 0 ? 0.26 : 2.93,
        0.386,
      ]);
    }
    add(
      new THREE.TorusGeometry(0.52, 0.035, 4, 30, Math.PI * 1.72),
      [0, 2.03, 0.392],
    );
    for (let i = 0; i < 7; i++) {
      const angle = (i * Math.PI) / 3.5;
      add(
        new THREE.BoxGeometry(0.037, 0.57, 0.027),
        [Math.sin(angle) * 0.21, 2.03 + Math.cos(angle) * 0.21, 0.396],
        [0, 0, -angle],
      );
    }
    for (let row = 0; row < 3; row++)
      for (let col = 0; col < 5 - row; col++)
        add(
          new THREE.BoxGeometry(0.16, 0.04, 0.027),
          [-0.65 + col * 0.29, 0.66 + row * 0.23, 0.396],
          [0, 0, ((col % 3) - 1) * 0.26],
        );
    const target = new THREE.Group();
    const temporary = new Set();
    bucket.build({ detail: null }, target, temporary);
    return target.children[0].geometry;
  });
  return {
    geometry,
    detail,
    radius: 2.5,
    colliders: [
      { x: 0, y: 1.55, z: 0, halfSize: { x: 1.29, y: 1.62, z: 0.37 } },
      { x: -0.21, y: 3.53, z: 0, halfSize: { x: 0.9, y: 0.36, z: 0.37 } },
      { x: 0, y: 4.04, z: 0, halfSize: { x: 0.56, y: 0.29, z: 0.37 } },
    ],
  };
}

function fragmentKit() {
  const geometry = cachedGeometry("outskirts_carved_fragment_v1", () => {
    const positions = [
      -1.65, 0, -0.88, 1.46, 0, -0.88, 1.54, 0, 0.85, -1.65, 0, 0.85, -1.22,
      0.74, -0.69, 1.18, 0.55, -0.79, 1.43, 0.87, 0.67, -1.44, 0.86, 0.77,
    ];
    const indices = [
      0, 2, 1, 0, 3, 2, 4, 5, 6, 4, 6, 7, 0, 1, 5, 0, 5, 4, 1, 2, 6, 1, 6, 5, 2,
      3, 7, 2, 7, 6, 3, 0, 4, 3, 4, 7,
    ];
    for (let i = 0; i < indices.length; i += 3)
      [indices[i + 1], indices[i + 2]] = [indices[i + 2], indices[i + 1]];
    return stoneGeometry(positions, indices, "#829b95");
  });
  return {
    geometry,
    radius: 1.85,
    colliders: [
      { x: 0, y: 0.35, z: 0, halfSize: { x: 1.48, y: 0.35, z: 0.78 } },
    ],
  };
}

/** 连续双层杯壁与不规则口缘形成可见的空腔，杯底封闭。 */
function spongeGeometry(lipOnly) {
  const positions = [],
    indices = [],
    uvs = [];
  const rings = lipOnly
    ? [
        [0.97, 0.93],
        [1, 0.97],
        [1, 0.78],
        [0.97, 0.73],
      ]
    : [
        [0, 0.18],
        [0.16, 0.34],
        [0.5, 0.46],
        [0.79, 0.7],
        [1, 0.97],
        [1, 0.78],
        [0.77, 0.55],
        [0.47, 0.3],
        [0.23, 0.05],
      ];
  const sides = 24;
  for (let row = 0; row < rings.length; row++) {
    const [h, radius] = rings[row];
    for (let side = 0; side < sides; side++) {
      const a = (side / sides) * Math.PI * 2;
      const r = radius * 0.48 * (1 + Math.sin(a * 5 + h * 2) * 0.08);
      const y = h * 1.46 + Math.sin(a * 3 + 1) * 0.1 * h;
      positions.push(Math.cos(a) * r + h * h * 0.16, y, Math.sin(a) * r);
      uvs.push(side / sides, h * 0.2);
      if (row < rings.length - 1) {
        const k = row * sides + side,
          n = row * sides + ((side + 1) % sides);
        indices.push(k, k + sides, n, n, k + sides, n + sides);
      }
    }
  }
  if (!lipOnly) {
    const center = positions.length / 3;
    positions.push(0.23 * 0.23 * 0.16, 0.23 * 1.46, 0);
    uvs.push(0.5, 0);
    const start = (rings.length - 1) * sides;
    for (let side = 0; side < sides; side++)
      indices.push(center, start + ((side + 1) % sides), start + side);
  }
  const geometry = stoneGeometry(
    positions,
    indices,
    lipOnly ? "#89c0c2" : "#739998",
  );
  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  return geometry;
}

function stoneGeometry(positions, indices, base) {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return paintStone(geometry, { base, algaeAmount: 0.28, seed: 9107 });
}

