import * as THREE from "three";
import { ATLANTIS_KEY_SITES } from "./expedition_objectives.js";
import { addSurfaceDetail } from "./ocean_visuals.js";

/**
 * 在真实公共建筑下层悬挂钥匙与铭文，不使用幼体专用住宅或新碰撞。
 * @param {THREE.Object3D} parent 海域根节点。
 * @param {object[]} records 已建成的上下层公共建筑记录。
 * @returns {object} 固定接触点、状态、主循环动画及幂等资源释放。
 */
export function createAtlantisKeyArt(parent, records = []) {
  const root = new THREE.Group();
  root.name = "atlantis_conch_key_and_inscriptions";
  parent.add(root);
  const owned = new Set();
  const keep = (r) => (owned.add(r), r);
  const bronze = keep(
    new THREE.MeshStandardMaterial({
      color: 0xb89c59,
      metalness: 0.65,
      roughness: 0.47,
      emissive: 0x392e0b,
      emissiveIntensity: 0.2,
    }),
  );
  addSurfaceDetail(bronze, "stone", 0.04);
  const stone = keep(
    new THREE.MeshStandardMaterial({ color: 0x4e7777, roughness: 0.87 }),
  );
  addSurfaceDetail(stone, "stone", 0.12);
  const glow = keep(new THREE.MeshBasicMaterial({ color: 0xffd897 }));
  function mesh(group, geometry, material, point = [0, 0, 0], name = "") {
    const m = new THREE.Mesh(keep(geometry), material);
    m.position.fromArray(point);
    m.name = name;
    group.add(m);
    return m;
  }
  function tube(group, points, radius, material) {
    return mesh(
      group,
      new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(points.map((p) => new THREE.Vector3(...p))),
        points.length * 5,
        radius,
        6,
        false,
      ),
      material,
    );
  }
  const locations = records
    .filter((r) => ATLANTIS_KEY_SITES.some((s) => s.id === r.id))
    .map((r) => ({
      id: r.id,
      name: ATLANTIS_KEY_SITES.find((s) => s.id === r.id).name,
      point: new THREE.Vector3(
        r.x + (r.variant === "bridges" ? 22 : 0),
        r.lowerY,
        r.z,
      ),
      clue: new THREE.Vector3(r.x, r.lowerY, r.z + 43),
      roofY: r.y - 4,
    }));
  const key = new THREE.Group();
  key.name = "conch_key";
  root.add(key);
  const bow = mesh(
    key,
    new THREE.TorusGeometry(0.9, 0.14, 8, 40),
    bronze,
    [0, 0, 0],
    "key_bow",
  );
  const shaft = mesh(
    key,
    new THREE.CylinderGeometry(0.13, 0.13, 2.8, 10),
    bronze,
    [0, -2.2, 0],
    "key_shaft",
  );
  for (let i = 0; i < 3; i++)
    mesh(key, new THREE.BoxGeometry(0.7, 0.22, 0.3), bronze, [
      0.25,
      -2.7 - i * 0.35,
      0,
    ]);
  tube(
    key,
    Array.from({ length: 49 }, (_, i) => {
      const t = i / 48,
        a = t * Math.PI * 4.5,
        r = 0.06 + t * 0.52;
      return [Math.cos(a) * r, Math.sin(a) * r, 0.13 + t * 0.06];
    }),
    0.055,
    glow,
  );
  const chain = new THREE.Group();
  chain.name = "key_roof_suspension";
  root.add(chain);
  const chainMesh = mesh(
    chain,
    new THREE.CylinderGeometry(0.055, 0.055, 1, 6),
    bronze,
  );
  const plaques = locations.map((site) => {
    const g = new THREE.Group();
    g.position.copy(site.clue);
    root.add(g);
    mesh(
      g,
      new THREE.BoxGeometry(4.8, 5.8, 0.65),
      stone,
      [0, 0, 0],
      "conch_inscription",
    );
    for (const x of [-2.15, 2.15])
      mesh(g, new THREE.BoxGeometry(0.11, 5.4, 0.1), bronze, [x, 0, 0.38]);
    for (const y of [-2.5, 2.5])
      mesh(g, new THREE.BoxGeometry(4.3, 0.11, 0.1), bronze, [0, y, 0.38]);
    tube(
      g,
      Array.from({ length: 36 }, (_, i) => {
        const t = i / 35,
          a = t * Math.PI * 4,
          r = 0.08 + t * 1.35;
        return [Math.cos(a) * r, Math.sin(a) * r, 0.4];
      }),
      0.07,
      glow,
    );
    for (let row = 0; row < 2; row++)
      tube(
        g,
        Array.from({ length: 15 }, (_, i) => [
          -1.8 + i * 0.26,
          -1.85 - row * 0.45 + Math.sin(i * 0.9) * 0.08,
          0.4,
        ]),
        0.025,
        bronze,
      );
    const hang = site.roofY - site.clue.y - 2.9;
    if (hang > 0)
      mesh(g, new THREE.CylinderGeometry(0.06, 0.06, hang, 6), bronze, [
        0,
        2.9 + hang / 2,
        0,
      ]);
    return g;
  });
  let selected = null,
    collected = false,
    disposed = false;
  return {
    root,
    locations,
    key,
    getPoint(id) {
      return locations.find((s) => s.id === id)?.point ?? null;
    },
    setState(state) {
      const site = locations.find((s) => s.id === state.keySiteId);
      if (site && selected !== site.id) {
        selected = site.id;
        key.position.copy(site.point);
        chain.position.copy(site.point);
        const height = site.roofY - site.point.y - 0.9;
        chainMesh.scale.y = Math.max(0, height);
        chainMesh.position.y = 0.9 + height / 2;
      }
      collected = !!state.keyCollected;
    },
    update(time, position, reducedMotion) {
      const visible =
        !!selected &&
        !collected &&
        key.position.distanceToSquared(position) < 200 ** 2;
      key.visible = chain.visible = visible;
      // 接触点保持固定，只摆动饰纹与材质，不让钥匙游出建筑。
      bow.rotation.z = reducedMotion ? 0 : Math.sin(time * 0.6) * 0.025;
      bronze.emissiveIntensity =
        0.2 + (reducedMotion ? 0 : (Math.sin(time * 1.3) + 1) * 0.12);
      plaques.forEach((p) => {
        p.visible = p.position.distanceToSquared(position) < 180 ** 2;
      });
      void shaft;
    },
    reset() {
      selected = null;
      collected = false;
      key.visible = chain.visible = false;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      root.removeFromParent();
      for (const r of owned) r.dispose();
      root.clear();
    },
  };
}

/** 真实宝箱的拱顶箱盖、铜箍、铆钉与钥孔，返回独立开盖关节。 */
export function createAtlantisQuestChest(root, keep, stone, bronze) {
  const dark = keep(
    new THREE.MeshStandardMaterial({ color: 0x345352, roughness: 0.74 }),
  );
  addSurfaceDetail(dark, "stone", 0.09);
  const box = (parent, geo, mat, x, y, z) => {
    const m = new THREE.Mesh(keep(geo), mat);
    m.position.set(x, y, z);
    parent.add(m);
    return m;
  };
  const bodyOutline = new THREE.Shape();
  bodyOutline.moveTo(-3.5, -1.55);
  bodyOutline.lineTo(3.5, -1.55);
  bodyOutline.lineTo(3.5, 1.55);
  bodyOutline.lineTo(-3.5, 1.55);
  bodyOutline.closePath();
  const bodyGeo = new THREE.ExtrudeGeometry(bodyOutline, {
    depth: 4.7,
    bevelEnabled: true,
    bevelSize: 0.08,
    bevelThickness: 0.08,
    bevelSegments: 2,
  });
  bodyGeo.translate(0, 0, -2.35);
  box(root, bodyGeo, dark, 0, 4, 0);
  const engraving = (parent, points, mat, radius = 0.045) =>
    box(
      parent,
      new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(points.map((p) => new THREE.Vector3(...p))),
        points.length * 5,
        radius,
        6,
        false,
      ),
      mat,
      0,
      0,
      0,
    );
  for (const side of [-1, 1]) {
    const x = side * 1.4;
    // 海神三叉与波浪铜嵌，保持盖子和箱体分离，开盖时不会穿帮。
    engraving(
      root,
      [
        [x, 2.9, -2.48],
        [x, 4.9, -2.48],
      ],
      bronze,
    );
    for (const offset of [-0.43, 0, 0.43])
      engraving(
        root,
        [
          [x, 4.1, -2.48],
          [x + offset, 4.5, -2.48],
          [x + offset, 4.94, -2.48],
        ],
        bronze,
        0.035,
      );
    for (const y of [3.15, 5.16])
      engraving(
        root,
        Array.from({ length: 14 }, (_, i) => [
          x - 0.82 + i * 0.126,
          y + Math.sin(i * 0.8) * 0.055,
          -2.48,
        ]),
        bronze,
        0.025,
      );
    box(
      root,
      new THREE.BoxGeometry(0.25, 3.15, 0.25),
      bronze,
      side * 3.34,
      4,
      -2.22,
    );
    box(
      root,
      new THREE.BoxGeometry(0.25, 3.15, 0.25),
      bronze,
      side * 3.34,
      4,
      2.22,
    );
  }
  box(root, new THREE.BoxGeometry(6.6, 0.3, 4.4), stone, 0, 2.5, 0);
  const lid = new THREE.Group();
  lid.name = "sacred_chest_lid";
  lid.position.set(0, 5.6, 2.35);
  root.add(lid);
  const shape = new THREE.Shape();
  shape.moveTo(-2.35, 0);
  shape.lineTo(2.35, 0);
  shape.absarc(0, 0, 2.35, 0, Math.PI, false);
  shape.closePath();
  const shell = new THREE.ExtrudeGeometry(shape, {
    depth: 7,
    bevelEnabled: true,
    bevelSize: 0.08,
    bevelThickness: 0.08,
    bevelSegments: 2,
    curveSegments: 32,
  });
  // 挤出轴为箱宽；拱顶横跨前后，后缘为真实开盖铰链。
  shell.rotateY(Math.PI / 2);
  shell.translate(-3.5, 0, -2.35);
  box(lid, shell, dark, 0, 0, 0);
  for (const side of [-1, 1])
    for (let ray = 0; ray < 7; ray++) {
      const a = (ray / 6) * Math.PI;
      engraving(
        lid,
        [
          [side * 3.59, 0.15, -2.35],
          [side * 3.59, Math.sin(a) * 1.8 + 0.15, -2.35 + Math.cos(a) * 1.8],
        ],
        bronze,
        0.03,
      );
    }
  for (const x of [-2.6, 0, 2.6]) {
    box(root, new THREE.BoxGeometry(0.19, 3.15, 4.82), bronze, x, 4, 0);
    const band = new THREE.TorusGeometry(2.42, 0.08, 6, 48, Math.PI);
    band.rotateY(Math.PI / 2);
    box(lid, band, bronze, x, 0, -2.35);
    for (const y of [2.8, 3.7, 4.6, 5.3])
      box(root, new THREE.SphereGeometry(0.12, 8, 6), bronze, x, y, -2.43);
  }
  box(root, new THREE.BoxGeometry(0.8, 1.4, 0.18), bronze, 0, 4.5, -2.55);
  box(
    root,
    new THREE.CylinderGeometry(0.2, 0.2, 0.2, 12),
    dark,
    0,
    4.7,
    -2.68,
  ).rotation.x = Math.PI / 2;
  box(root, new THREE.BoxGeometry(0.12, 0.45, 0.12), dark, 0, 4.4, -2.69);
  return lid;
}

atlantis_relic.js.source:
import * as THREE from "three";
import {
  createAtlantisKeyArt,
  createAtlantisQuestChest,
} from "./atlantis_quest_art.js";
import { ATLANTIS_RELIC } from "./expedition_objectives.js";
import { addSurfaceDetail } from "./ocean_visuals.js";

/** 地宫圣珠与雕纹宝箱；钥匙和守宝印记齐全后解封，不占用额外灯池。 */
export function createAtlantisRelic(parent, { records = [] } = {}) {
  const keyArt = createAtlantisKeyArt(parent, records);
  const root = new THREE.Group();
  root.name = "poseidon_sacred_pearl";
  root.position.set(ATLANTIS_RELIC.x, -709.5, ATLANTIS_RELIC.z);
  parent.add(root);
  const resources = new Set();
  const keep = (r) => (resources.add(r), r);
  const stone = keep(
    new THREE.MeshStandardMaterial({ color: 0x8ba59a, roughness: 0.89 }),
  );
  addSurfaceDetail(stone, "stone", 0.14);
  const bronze = keep(
    new THREE.MeshStandardMaterial({
      color: 0x9c9870,
      metalness: 0.58,
      roughness: 0.49,
    }),
  );
  const pearlMat = keep(
    new THREE.MeshStandardMaterial({
      color: 0xe0f3d7,
      emissive: 0x71dbce,
      emissiveIntensity: 0.1,
      metalness: 0.2,
      roughness: 0.17,
    }),
  );
  function mesh(geo, mat, name, p = [0, 0, 0]) {
    const m = new THREE.Mesh(keep(geo), mat);
    m.name = name;
    m.position.fromArray(p);
    root.add(m);
    return m;
  }
  mesh(
    new THREE.CylinderGeometry(5.1, 5.8, 1.4, 8),
    stone,
    "carved_octagonal_dais",
    [0, 0.7, 0],
  );
  mesh(
    new THREE.CylinderGeometry(4.3, 4.9, 0.9, 8),
    stone,
    "pearl_dais_upper",
    [0, 1.85, 0],
  );
  for (const y of [1.25, 2.2]) {
    const trim = mesh(
      new THREE.TorusGeometry(y > 2 ? 4.45 : 5.1, 0.08, 6, 8),
      bronze,
      "dais_bronze_inlay",
      [0, y, 0],
    );
    trim.rotation.x = Math.PI / 2;
    trim.rotation.z = Math.PI / 8;
  }
  const lid = createAtlantisQuestChest(root, keep, stone, bronze);
  const pearl = mesh(
    new THREE.SphereGeometry(2.25, 32, 24),
    pearlMat,
    "sacred_pearl",
    [0, ATLANTIS_RELIC.y - root.position.y, 0],
  );
  pearl.visible = false;
  const sealMat = keep(
    new THREE.MeshBasicMaterial({
      color: 0x6197b3,
      transparent: true,
      opacity: 0.22,
      wireframe: true,
      depthWrite: false,
    }),
  );
  const seal = mesh(
    new THREE.IcosahedronGeometry(3.2, 1),
    sealMat,
    "guardian_seal",
    pearl.position.toArray(),
  );
  const crown = mesh(
    new THREE.TorusGeometry(3.1, 0.055, 6, 64),
    bronze,
    "pearl_orbit",
    pearl.position.toArray(),
  );
  crown.rotation.x = Math.PI / 2;
  let unlocked = false,
    collected = false,
    disposed = false,
    previousTime = null;
  return {
    root,
    keyArt,
    get unlocked() {
      return unlocked;
    },
    get collected() {
      return collected;
    },
    setState(state) {
      keyArt.setState(state);
      if (
        unlocked === state.relicUnlocked &&
        collected === state.relicCollected
      )
        return;
      unlocked = state.relicUnlocked;
      collected = state.relicCollected;
      seal.visible = !unlocked;
      pearl.visible = unlocked && !collected;
      crown.visible = !collected;
      pearlMat.emissiveIntensity = unlocked ? 1.7 : 0.1;
    },
    update(time, position, reducedMotion = false) {
      if (disposed) return;
      keyArt.update(time, position, reducedMotion);
      const dt =
        previousTime === null
          ? 0
          : THREE.MathUtils.clamp(time - previousTime, 0, 0.12);
      previousTime = time;
      lid.rotation.x = reducedMotion
        ? unlocked
          ? 1.2
          : 0
        : THREE.MathUtils.damp(lid.rotation.x, unlocked ? 1.2 : 0, 4, dt);
      root.visible = root.position.distanceToSquared(position) < 230 ** 2;
      seal.rotation.y = reducedMotion ? 0 : time * 0.09;
      crown.rotation.z = reducedMotion ? 0 : Math.sin(time * 0.6) * 0.15;
      // 核心接触点固定；呼吸只改变材质，不能令圣珠与拾取范围错位。
      if (unlocked)
        pearlMat.emissiveIntensity =
          1.7 + (reducedMotion ? 0 : Math.sin(time * 1.4) * 0.15);
    },
    reset() {
      keyArt.reset();
      this.setState({ relicUnlocked: false, relicCollected: false });
      lid.rotation.x = 0;
      previousTime = null;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      keyArt.dispose();
      root.removeFromParent();
      for (const r of resources) r.dispose();
      resources.clear();
    },
  };
}

atlantis_residential_interiors.js.source:
import * as THREE from "three";
import { createAtlantisFurnitureBatch } from "./atlantis_exploration_furniture.js";
import {
  bodyRadius,
  castSegment,
  isPositionBlocked,
  resolveMotion,
} from "./collision.js";
import { createStaticColliderGrid } from "./static_collider_grid.js";
import {
  planAtlantisResidentialInteriors,
  RESIDENTIAL_FURNITURE_FOOTPRINTS,
  residentialFootprintSamples,
  residentialPlacementCandidates,
  residentialWorldPoint,
} from "./atlantis_residential_layout.js";

/**
 * 在普通住宅的真实楼板上布置共享雕刻家具，每街区按材质批处理。
 * @param {THREE.Object3D} parent 城市父节点。
 * @param {object} options records 建筑记录、heightAt 海床、hostColliders 完整宿主碰撞和 seed 布局种子。
 * @returns {object} root、colliders、landmarks、lightSources、stats、update 和幂等 dispose。
 */
export function createAtlantisResidentialInteriors(
  parent,
  { records = [], heightAt, hostColliders = [], seed = 5173 } = {},
) {
  if (!parent?.add || typeof heightAt !== "function" || !Array.isArray(records))
    throw new Error(
      "Residential interiors require a parent, records and height function",
    );
  const plans = planAtlantisResidentialInteriors(records, seed);
  const hostGrid = createStaticColliderGrid([...hostColliders]);
  const root = new THREE.Group();
  root.name = "atlantis_residential_interiors";
  parent.add(root);
  const colliders = [],
    landmarks = [],
    lightSources = [],
    districts = new Map(),
    dropped = [],
    excludedHomes = [];
  for (const home of plans) {
    const access = selectJuvenileAccess(home, hostGrid, heightAt);
    if (!access) {
      excludedHomes.push({
        id: home.id,
        record: home.record,
        reason: "blocked_existing_entrance",
      });
      continue;
    }
    home.access = access;
    if (!districts.has(home.district))
      districts.set(home.district, { homes: [], groups: [] });
    const district = districts.get(home.district);
    district.homes.push(home);
    const chosenHomeGroups = new Map();
    for (const original of home.groups) {
      const candidates = residentialPlacementCandidates(home, original);
      const item = candidates.find(
        (candidate) =>
          !overlapsOtherSlot(
            candidate,
            home.groups.map((other) => chosenHomeGroups.get(other.id) ?? other),
          ) && !supportFailure(candidate, heightAt, hostGrid),
      );
      if (!item)
        dropped.push({
          id: original.id,
          homeId: home.id,
          kind: original.kind,
          reason: supportFailure(original, heightAt, hostGrid),
        });
      else {
        chosenHomeGroups.set(item.id, item);
        district.groups.push(item);
      }
    }
  }
  const batches = [];
  const placedGroups = [];
  const placed = { bench: 0, table: 0, chest: 0, amphora: 0 };
  let triangles = 0,
    meshes = 0;
  for (const [id, district] of districts) {
    if (!district.groups.length) continue;
    const batch = createAtlantisFurnitureBatch(root, {
      heightAt,
      hostColliders,
      groups: district.groups,
      seed,
    });
    batch.root.name = `atlantis_residential_${id}`;
    const bounds = districtBounds(district.homes);
    batches.push({ id, batch, bounds });
    for (const collider of batch.colliders)
      collider.kind = "residential_furniture";
    colliders.push(...batch.colliders);
    dropped.push(...batch.stats.dropped);
    placedGroups.push(...batch.stats.placedGroups);
    for (const kind of Object.keys(placed))
      placed[kind] += batch.stats.placed[kind];
    triangles += batch.stats.triangles;
    meshes += batch.root.children.filter((child) => child.isMesh).length;
  }
  const placedIds = new Set(placedGroups.map((item) => item.id));
  const activePlans = [...districts.values()].flatMap(({ homes }) => homes);
  const chosenGroups = new Map(
    [...districts.values()]
      .flatMap(({ groups }) => groups)
      .map((item) => [item.id, item]),
  );
  const layouts = activePlans.map((home) => {
    const groups = home.groups
      .filter((item) => placedIds.has(item.id))
      .map((item) => chosenGroups.get(item.id));
    if (groups.length)
      landmarks.push({
        id: home.id,
        position: new THREE.Vector3(
          home.access.turningCenter.x,
          home.floorY + 1.8,
          home.access.turningCenter.z,
        ),
      });
    return { ...home, groups };
  });
  const stats = {
    plannedHomes: plans.length,
    eligibleHomes: activePlans.length,
    excludedHomes,
    furnishedHomes: layouts.filter((home) => home.groups.length > 0).length,
    fullyFurnishedHomes: layouts.filter((home) =>
      ["bench", "chest"].every((kind) =>
        home.groups.some((item) => item.kind === kind),
      ),
    ).length,
    plannedGroups: plans.reduce((sum, home) => sum + home.groups.length, 0),
    placed,
    placedGroups,
    dropped,
    triangles,
    meshes,
    colliders: colliders.length,
    districts: batches.map(({ id, batch, bounds }) => ({
      id,
      bounds,
      triangles: batch.stats.triangles,
      groups: batch.stats.placedGroups.length,
    })),
    layouts,
  };
  root.userData.residentialStats = stats;
  let disposed = false;
  return {
    root,
    colliders,
    landmarks,
    lightSources,
    stats,
    update(time, dt, position, highQuality = true) {
      if (disposed) return;
      for (const { batch, bounds } of batches) {
        batch.update(time, dt, position, highQuality);
        batch.root.visible =
          !position ||
          distanceToBounds(position, bounds) < (highQuality ? 235 : 190);
      }
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const { batch } of batches) batch.dispose();
      parent.remove(root);
      root.clear();
      colliders.length = landmarks.length = lightSources.length = 0;
    },
  };
}

// 完整占地同时检查海床与实际楼板；中心点正确不能证明边缘没有浮空或埋入坡面。
function supportFailure(item, heightAt, grid) {
  for (const point of residentialFootprintSamples(item)) {
    const terrain = heightAt(point.x, point.z);
    if (!Number.isFinite(terrain) || terrain > item.floor + 0.025)
      return "terrain_intersection";
    const start = { ...point, y: item.floor + 0.04 };
    const end = { ...point, y: item.floor - 0.08 };
    const hosts = grid.query(start, end);
    const support = castSegment(start, end, hosts);
    if (!support || Math.abs(support.point.y - item.floor) > 0.025)
      return "missing_floor_support";
  }
  return null;
}

// 既有大型地基可能把普通住宅包住；只给真实可进出的住宅设置内部地标。
function hasJuvenileAccess(home, grid, heightAt) {
  const query = (start, end, options) => grid.query(start, end, options);
  const options = {
    colliders: query,
    radius: bodyRadius(3),
    length: 3,
    floorHeight: (x, z) => heightAt(x, z) + bodyRadius(3) + 0.1,
  };
  for (const reverse of [false, true]) {
    const points = reverse
      ? [...home.access.route].reverse()
      : home.access.route;
    for (let i = 1; i < points.length; i += 1) {
      const forward = new THREE.Vector3()
        .subVectors(points[i], points[i - 1])
        .normalize();
      const result = resolveMotion(points[i - 1], points[i], {
        ...options,
        forward,
      });
      if (
        result.blocked ||
        result.stuck ||
        new THREE.Vector3().copy(result.position).distanceTo(points[i]) > 0.025
      )
        return false;
    }
  }
  for (let i = 0; i < 16; i += 1) {
    const angle = (i * Math.PI) / 8;
    if (
      isPositionBlocked(home.access.turningCenter, {
        ...options,
        forward: { x: Math.sin(angle), y: 0, z: Math.cos(angle) },
      })
    )
      return false;
  }
  return true;
}

function selectJuvenileAccess(home, grid, heightAt) {
  const candidates = [home.access];
  const swimLocal = home.floorLocal + 3.2 / home.record.scale;
  for (const side of [-1, 1]) {
    const local = [
      [0, 14.7],
      [0, 4.5],
      [side * 3, 0],
      [side * 3, -5.6],
    ];
    candidates.push({
      maxTestedLength: 3,
      route: local.map(([x, z]) =>
        residentialWorldPoint(home.record, x, swimLocal, z),
      ),
      turningCenter: residentialWorldPoint(home.record, side * 3, swimLocal, 0),
    });
  }
  return (
    candidates.find((access) =>
      hasJuvenileAccess({ ...home, access }, grid, heightAt),
    ) ?? null
  );
}

function districtBounds(homes) {
  return {
    minX: Math.min(...homes.map(({ record }) => record.x - record.width / 2)),
    maxX: Math.max(...homes.map(({ record }) => record.x + record.width / 2)),
    minZ: Math.min(...homes.map(({ record }) => record.z - record.depth / 2)),
    maxZ: Math.max(...homes.map(({ record }) => record.z + record.depth / 2)),
  };
}

function distanceToBounds(position, bounds) {
  return Math.hypot(
    Math.max(bounds.minX - position.x, 0, position.x - bounds.maxX),
    Math.max(bounds.minZ - position.z, 0, position.z - bounds.maxZ),
  );
}

function overlapsOtherSlot(item, groups) {
  const a = RESIDENTIAL_FURNITURE_FOOTPRINTS[item.kind];
  return groups.some((other) => {
    if (other.id === item.id) return false;
    const b = RESIDENTIAL_FURNITURE_FOOTPRINTS[other.kind];
    return (
      item.localX + a.maxX > other.localX + b.minX &&
      item.localX + a.minX < other.localX + b.maxX &&
      item.localZ + a.maxZ > other.localZ + b.minZ &&
      item.localZ + a.minZ < other.localZ + b.maxZ
    );
  });
}

atlantis_residential_layout.js.source:
import { ATLANTIS_DISTRICTS, atlantisDistrict } from "./atlantis_city_plan.js";

// 家具完整可见占地包括箱盖、靠杆与陶瓶托盘旁的残片，不能只取碰撞中心。
export const RESIDENTIAL_FURNITURE_FOOTPRINTS = Object.freeze({
  bench: Object.freeze({ minX: -1.81, maxX: 1.81, minZ: -0.69, maxZ: 0.69 }),
  chest: Object.freeze({ minX: -1.37, maxX: 1.37, minZ: -0.95, maxZ: 0.95 }),
  table: Object.freeze({ minX: -1.39, maxX: 1.39, minZ: -1.39, maxZ: 1.39 }),
  amphora: Object.freeze({ minX: -1.75, maxX: 2.5, minZ: -1.55, maxZ: 2.4 }),
});

// 备用位置沿同一室内侧墙有限前移，再尝试镜像侧墙；入口和中轴不作为摆放点。
const RESIDENTIAL_FURNITURE_FALLBACK_Z = Object.freeze({
  bench: Object.freeze([-4.3, -0.7, 2.5]),
  chest: Object.freeze([-4.3, -0.7, 2.5]),
});

/**
 * 将住宅局部坐标换算为真实世界坐标。
 * @param {object} record 含 x、y、z、scale 和 rotation 的建筑记录。
 * @param {number} x 局部横向位置。
 * @param {number} y 局部高度。
 * @param {number} z 局部纵向位置。
 * @returns {object} 世界 x、y、z。
 */
export function residentialWorldPoint(record, x, y, z) {
  const c = Math.cos(record.rotation),
    s = Math.sin(record.rotation);
  return {
    x: record.x + (x * c + z * s) * record.scale,
    y: record.y + y * record.scale,
    z: record.z + (-x * s + z * c) * record.scale,
  };
}

/**
 * 为所有实际庭院和别墅生成有界陈设，中央与入口保留幼体游线。
 * @param {object[]} records 城市建筑记录，不修改原数组。
 * @param {number} seed 四种布局的确定性偏移。
 * @returns {object[]} 住宅记录、楼板高度、陈设与幼体往返路线。
 */
export function planAtlantisResidentialInteriors(records, seed = 5173) {
  const homes = records
    .filter((record) => ["courtyard", "villa"].includes(record.kind))
    .map((record) => ({ ...record }))
    .sort((a, b) => a.z - b.z || a.x - b.x || a.kind.localeCompare(b.kind));
  return homes.map((record, index) => {
    validateRecord(record);
    const district = atlantisDistrict(record.x, record.z)?.id ?? "outskirts";
    const variant = (index + Math.abs(Math.trunc(seed))) % 4;
    const floorLocal = record.kind === "courtyard" ? 1.4 : 1.7;
    const id = `residential_${record.kind}_${record.x}_${record.z}`;
    const side = variant % 2 ? 1 : -1;
    const slots = [
      { kind: "bench", localX: side * 5.4, localZ: -7.9 },
      { kind: "chest", localX: -side * 4.7, localZ: -7.5 },
    ];
    if (variant === 0)
      slots.push({ kind: "table", localX: side * 5.1, localZ: -2.3 });
    if (variant === 2) slots.push({ kind: "amphora", localX: 4.6, localZ: 2 });
    const groups = slots.map((slot) => {
      const position = residentialWorldPoint(
        record,
        slot.localX,
        floorLocal,
        slot.localZ,
      );
      return {
        id: `${id}_${slot.kind}`,
        homeId: id,
        kind: slot.kind,
        x: position.x,
        floor: position.y,
        z: position.z,
        scale: record.scale,
        yaw: record.rotation,
        count: 3,
        seed: Math.trunc(seed) + index * 17,
        localX: slot.localX,
        localZ: slot.localZ,
      };
    });
    // 较小住宅只承诺 3m 幼体进出；16–30m 成体的通道在室外街道和公共大厅。
    const swimLocal = floorLocal + 3.2 / record.scale;
    const route = [14.7, 7.5, 0, -5.6].map((z) =>
      residentialWorldPoint(record, 0, swimLocal, z),
    );
    return {
      id,
      district,
      districtOrder: ATLANTIS_DISTRICTS.findIndex((d) => d.id === district),
      variant,
      record,
      floorLocal,
      floorY: record.y + floorLocal * record.scale,
      groups,
      access: {
        maxTestedLength: 3,
        route,
        turningCenter: residentialWorldPoint(record, 0, swimLocal, 0),
      },
    };
  });
}

/**
 * 采样完整可见占地，所有点都使用与家具相同的缩放和偏航。
 * @param {object} item 陈设组。
 * @param {number} divisions 每轴等分数。
 * @returns {object[]} 世界占地采样点。
 */
export function residentialFootprintSamples(item, divisions = 6) {
  const extent = RESIDENTIAL_FURNITURE_FOOTPRINTS[item.kind];
  const c = Math.cos(item.yaw),
    s = Math.sin(item.yaw);
  const points = [];
  for (let ix = 0; ix <= divisions; ix += 1)
    for (let iz = 0; iz <= divisions; iz += 1) {
      const x = extent.minX + ((extent.maxX - extent.minX) * ix) / divisions;
      const z = extent.minZ + ((extent.maxZ - extent.minZ) * iz) / divisions;
      points.push({
        x: item.x + (x * c + z * s) * item.scale,
        y: item.floor,
        z: item.z + (-x * s + z * c) * item.scale,
      });
    }
  return points;
}

/**
 * 生成有限室内备用位置，不改动原始陈设或住宅记录。
 * @param {object} home 住宅布局及楼板高度。
 * @param {object} item 原始家具组。
 * @returns {object[]} 原位置优先的候选，全部沿真实建筑变换换算。
 */
export function residentialPlacementCandidates(home, item) {
  const candidates = [item];
  const alternatives = RESIDENTIAL_FURNITURE_FALLBACK_Z[item.kind] ?? [];
  for (const x of [item.localX, -item.localX])
    for (const z of alternatives) {
      const point = residentialWorldPoint(home.record, x, home.floorLocal, z);
      candidates.push({
        ...item,
        x: point.x,
        floor: point.y,
        z: point.z,
        localX: x,
        localZ: z,
      });
    }
  return candidates;
}

function validateRecord(record) {
  if (
    ![record.x, record.y, record.z, record.scale, record.rotation].every(
      Number.isFinite,
    ) ||
    record.scale <= 0
  )
    throw new Error(
      "Residential records require finite transforms and positive scale",
    );
}

