import { seabedHeight } from "./ocean.js";
import { AGORA_EXCAVATION_SITE } from "./atlantis_exploration_agora_site.js";
import { POSEIDON_TEMPLE_SITE } from "./atlantis_poseidon_site.js";

/**
 * 亚特兰蒂斯探索层地形接口:在预留区内把共享海床下挖成平底厅堂基坑。
 * 当前港湾、市集与波塞冬神殿挖掘区之外，返回值与原
 * seabedHeight 完全相等(不经过任何算术);坑内只下挖、不抬升,边缘用坑内
 * 单侧平滑带过渡,最低点远高于世界下限并留足成体余量。
 */

// 平滑阶跃(0→1),与 THREE.MathUtils.smoothstep 同形,保持本模块零渲染依赖。
function smooth01(t) {
  const x = Math.min(1, Math.max(0, t));
  return x * x * (3 - 2 * x);
}

function freezeDeep(value) {
  if (value && typeof value === "object")
    for (const key of Object.keys(value)) freezeDeep(value[key]);
  return Object.freeze(value);
}

/** 单块挖掘场地:矩形基坑 + 可选入口沟槽(坡道切口,线性下切)。 */
const HARBOR_DIG = {
  // 港湾圣所预留区为 x∈[-271,-159]、z∈[-302.5,-178.5];基坑避让所有
  // 圣所支墩投影(支墩在 x[-264.5,-253.5] 与 x[-176.5,-165.5]),四周留 6m+ 净距。
  bounds: { minX: -252, maxX: -178, minZ: -276, maxZ: -220 },
  floorY: -194, // 下厅留出竖直成体转平的高度，游泳中心明确低于原海床。
  blend: 4, // 坑缘向内的平滑过渡带宽(米),全部落在坑界内侧
  trench: {
    // 北侧入口沟槽:从街面切开坡顶,让大台阶从原海床一路下行入厅。
    minX: -244,
    maxX: -224,
    minZ: -256,
    maxZ: -211,
    topZ: -211,
    topY: -128,
    bottomZ: -251,
    bottomY: -156,
    edgeBlend: 2, // 两侧各 2m 平滑带,由台阶护墙遮护
  },
};

/**
 * 不可变的挖掘场地元数据:场地边界、入口、竖井、各层楼板标高、
 * 路线航点与净高/回转净空。集成方据此做 3/16/30m 连续体往返测试。
 * 所有 Y 均为世界坐标(水面为 4,向下为负)。
 */
export const ATLANTIS_EXCAVATION_SITES = freezeDeep([
  {
    id: "harbor_sunken_halls",
    reservation: "harbor_sanctuary",
    bounds: HARBOR_DIG.bounds,
    floorY: HARBOR_DIG.floorY,
    blendMeters: HARBOR_DIG.blend,
    trench: HARBOR_DIG.trench,
    originalSeabed: { min: -178.5, max: -128.0 }, // 坑区原海床实测范围
    entrance: {
      kind: "collapsed_grand_stair",
      top: { x: -234, y: -128, z: -211 },
      bottom: { x: -234, y: -156, z: -251 },
      clearWidth: 18.7,
      slopeDegrees: (Math.atan2(28, 40) * 180) / Math.PI,
      gateClearHeight: 30,
      roofOpening: { minX: -245, maxX: -223, minZ: -262, maxZ: -218.5 },
    },
    shaft: {
      // 开阔竖井:贯通屋面与上层楼板,直达下层正厅,兼作上行通道。
      minX: -212,
      maxX: -184,
      minZ: -261,
      maxZ: -233,
      topY: -133,
      bottomY: -194,
    },
    secondExit: {
      kind: "south_portal",
      minX: -222,
      maxX: -208,
      sillY: -156,
      topY: -142,
      z: -274.75, // 南墙中心面
    },
    levels: [
      {
        id: "upper_gallery",
        floorY: -156, // 独立楼板顶面(静态 box collider)
        ceilingY: -135.5, // 屋面板底面
        clearHeight: 20.5,
      },
      {
        id: "lower_hall",
        floorY: -194, // 挖掘坑底(高度场)
        ceilingY: -158, // 上层楼板底面
        clearHeight: 36,
      },
    ],
    turningCircle: {
      // 半径12m的游泳圆周连同成体头尾需要约19m净半径，柱列置于外围。
      x: -227,
      y: -177,
      z: -249,
      clearRadius: 20,
      swimLoopRadius: 12,
      level: "lower_hall",
    },
    routes: [
      {
        id: "stair_to_lower_hall",
        // 航点是身体中心而不是踏步标高；终点保留完整的竖直转平空间。
        waypoints: [
          { x: -234, y: -96, z: -196 },
          { x: -234, y: -113, z: -211 },
          { x: -234, y: -146, z: -251 },
          { x: -198, y: -146, z: -247 },
          { x: -198, y: -177, z: -247 },
          { x: -227, y: -177, z: -249 },
        ],
      },
      {
        id: "south_exit_to_lower_hall",
        // 南门外先留足身体纵向距离；门内平游至落脚处，再抬升转井以避开护墙。
        waypoints: [
          { x: -216, y: -119, z: -295 },
          { x: -216, y: -148, z: -295 },
          { x: -216, y: -148, z: -259 },
          { x: -216, y: -144, z: -247 },
          { x: -198, y: -144, z: -247 },
          { x: -198, y: -177, z: -247 },
          { x: -227, y: -177, z: -249 },
        ],
      },
    ],
    clearances: {
      // 供 3/16/30m 连续体测试的最小净尺寸(米)
      stairWidth: 18.7,
      shaftWidth: 28,
      portalWidth: 14,
      portalHeight: 14,
      upperGalleryHeight: 20.5,
      lowerHallHeight: 36,
      turningDiameter: 40,
    },
  },
  AGORA_EXCAVATION_SITE,
  POSEIDON_TEMPLE_SITE,
]);

/**
 * 亚特兰蒂斯共享海床高度:默认与原 seabedHeight 逐点相等;
 * 仅在挖掘场地边界内部下挖(含入口沟槽),从不抬升地形。
 * @param {number} x 世界横坐标。
 * @param {number} z 世界纵坐标。
 * @returns {number} 该点海床表面 Y。
 */
export function atlantisSeabedHeight(x, z) {
  const base = seabedHeight(x, z);
  let y = base;
  for (const site of ATLANTIS_EXCAVATION_SITES) {
    const b = site.bounds;
    // 基坑:坑界外侧 0;界内 blend 带宽内平滑过渡到底,更深处为平底。
    const inset = Math.min(x - b.minX, b.maxX - x, z - b.minZ, b.maxZ - z);
    if (inset > 0) {
      const t = smooth01(inset / site.blendMeters);
      y = Math.min(y, base + (site.floorY - base) * t);
    }
    const tr = site.trench;
    if (tr) {
      // 入口沟槽:线性坡面切口,只在上口与外缘做短平滑,切口只下切。
      const sideInset = Math.min(x - tr.minX, tr.maxX - x);
      if (sideInset > -tr.edgeBlend && z >= tr.minZ && z <= tr.maxZ + 2) {
        const clampedZ = Math.min(tr.maxZ, Math.max(tr.minZ, z));
        const slopeT = (tr.topZ - clampedZ) / (tr.topZ - tr.bottomZ);
        const cut = tr.topY + (tr.bottomY - tr.topY) * slopeT;
        const fx = smooth01((sideInset + tr.edgeBlend) / tr.edgeBlend / 2);
        const fz = z <= tr.maxZ ? 1 : smooth01(1 - (z - tr.maxZ) / 2);
        const startFade = tr.startBlendMeters
          ? smooth01((z - tr.minZ) / tr.startBlendMeters)
          : 1;
        y = Math.min(y, base + (cut - base) * Math.min(fx, fz, startFade));
      }
    }
  }
  return y;
}

/** 查询点是否落在任一挖掘场地基坑内(含边界),供铺装/植被等避让查询。 */
export function isAtlantisExcavated(x, z) {
  return ATLANTIS_EXCAVATION_SITES.some((site) => {
    const b = site.bounds;
    return x >= b.minX && x <= b.maxX && z >= b.minZ && z <= b.maxZ;
  });
}

atlantis_terrain_mesh.js.source:
import * as THREE from "three";
import { ATLANTIS_EXCAVATION_SITES } from "./atlantis_terrain.js";

/**
 * 只细分挖掘区附近的地表单元，防止原低密度三角形跨过坑口、穿入厅堂。
 * 外围仍沿用原网格密度；同一套采样可供海床和城市铺装使用。
 * @param {object} options 世界范围、原始分段数、共享高度函数与表面偏移。
 * @returns {THREE.BufferGeometry} 顶点位于世界坐标的带索引地表网格。
 */
export function createAtlantisTerrainMesh({
  minX,
  maxX,
  minZ,
  maxZ,
  segmentsX,
  segmentsZ,
  heightAt,
  offset = 0,
}) {
  const positions = [],
    uv = [],
    indices = [],
    normals = [];
  const vertices = new Map();
  function vertexAt(x, z) {
    const key = `${Math.round(x * 1e6)}:${Math.round(z * 1e6)}`;
    if (vertices.has(key)) return vertices.get(key);
    const index = positions.length / 3;
    positions.push(x, heightAt(x, z) + offset, z);
    uv.push((x - minX) / (maxX - minX), (z - minZ) / (maxZ - minZ));
    // 高低密度单元共用采样法线，避免挖掘区边缘形成可见的照明接缝。
    const nx = heightAt(x - 0.05, z) - heightAt(x + 0.05, z);
    const nz = heightAt(x, z - 0.05) - heightAt(x, z + 0.05);
    const inverse = 1 / Math.hypot(nx, 0.1, nz);
    normals.push(nx * inverse, 0.1 * inverse, nz * inverse);
    vertices.set(key, index);
    return index;
  }
  const dx = (maxX - minX) / segmentsX;
  const dz = (maxZ - minZ) / segmentsZ;
  const cuts = ATLANTIS_EXCAVATION_SITES.flatMap((site) => {
    const areas = [{ ...site.bounds, step: 0.5 }];
    if (site.blendMeters < 4) {
      // 更窄的衬墙需要陡而平滑的切口，只细分坑缘单元，保留平底密度。
      const b = site.bounds,
        w = site.blendMeters;
      areas.push(
        { ...b, maxX: b.minX + w, step: 0.25 },
        { ...b, minX: b.maxX - w, step: 0.25 },
        { ...b, maxZ: b.minZ + w, step: 0.25 },
        { ...b, minZ: b.maxZ - w, step: 0.25 },
      );
    }
    if (site.trench) {
      const t = site.trench;
      areas.push({
        minX: t.minX - t.edgeBlend,
        maxX: t.maxX + t.edgeBlend,
        minZ: t.minZ,
        maxZ: t.maxZ + 2,
      });
    }
    return areas;
  });
  for (let iz = 0; iz < segmentsZ; iz++) {
    for (let ix = 0; ix < segmentsX; ix++) {
      const x0 = minX + ix * dx,
        z0 = minZ + iz * dz;
      const detailed = cuts.filter((b) => {
        const pad = b.step < 0.5 ? 0 : 1;
        return (
          x0 + dx > b.minX - pad &&
          x0 < b.maxX + pad &&
          z0 + dz > b.minZ - pad &&
          z0 < b.maxZ + pad
        );
      });
      const step = Math.min(...detailed.map((cut) => cut.step ?? 0.5));
      // 平底厅堂的整个单元都是同一平面，无须把不可见的平面再切成密集小格。
      // 仅在矩形完全落入坑内平底且实际采样一致时合并，陡坡与入口仍保持原密度。
      const flat = ATLANTIS_EXCAVATION_SITES.some((site) => {
        const b = site.bounds,
          margin = site.blendMeters;
        return (
          x0 >= b.minX + margin &&
          x0 + dx <= b.maxX - margin &&
          z0 >= b.minZ + margin &&
          z0 + dz <= b.maxZ - margin &&
          [
            [x0, z0],
            [x0 + dx, z0],
            [x0, z0 + dz],
            [x0 + dx, z0 + dz],
            [x0 + dx / 2, z0 + dz / 2],
          ].every(([x, z]) => Math.abs(heightAt(x, z) - site.floorY) < 1e-8)
        );
      });
      const nx = detailed.length && !flat ? Math.ceil(dx / step) : 1;
      const nz = detailed.length && !flat ? Math.ceil(dz / step) : 1;
      const cell = [];
      for (let j = 0; j <= nz; j++) {
        for (let i = 0; i <= nx; i++) {
          const x = x0 + (dx * i) / nx,
            z = z0 + (dz * j) / nz;
          cell.push(vertexAt(x, z));
        }
      }
      for (let j = 0; j < nz; j++) {
        for (let i = 0; i < nx; i++) {
          const a = j * (nx + 1) + i,
            b = a + 1,
            c = a + nx + 1,
            d = c + 1;
          const ids = [cell[a], cell[b], cell[c], cell[d]];
          const centerHeight =
            heightAt(x0 + (dx * (i + 0.5)) / nx, z0 + (dz * (j + 0.5)) / nz) +
            offset;
          const adError = Math.abs(
            (positions[ids[0] * 3 + 1] + positions[ids[3] * 3 + 1]) / 2 -
              centerHeight,
          );
          const bcError = Math.abs(
            (positions[ids[1] * 3 + 1] + positions[ids[2] * 3 + 1]) / 2 -
              centerHeight,
          );
          // 坑角的两段陡坡相交时，沿真实折线选对角线，避免跨坡搭出薄片。
          if (adError < bcError)
            indices.push(cell[a], cell[c], cell[d], cell[a], cell[d], cell[b]);
          else
            indices.push(cell[a], cell[c], cell[b], cell[b], cell[c], cell[d]);
        }
      }
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
  geometry.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
  geometry.setIndex(indices);
  return geometry;
}

atlantis_underways.js.source:
import * as THREE from "three";
import {
  MergeBucket,
  atlantisMaterials,
  loftGeometry,
  paintStone,
} from "./atlantis_art_geometry.js";

// 只替换侧城街坊；范围不改变五城区边界，也不侵占圣道和克拉肯战斗空间。
export const ATLANTIS_UNDERWAY_SITES = Object.freeze([
  Object.freeze({
    id: "harbor_sanctuary",
    x: -215,
    z: -240.5,
    width: 112,
    depth: 124,
    variant: "sanctuary",
  }),
  Object.freeze({
    id: "agora_bridges",
    x: 215,
    z: -447.5,
    width: 112,
    depth: 124,
    variant: "bridges",
  }),
  Object.freeze({
    id: "memorial_terrace",
    x: -215,
    z: -999.5,
    width: 112,
    depth: 124,
    variant: "terrace",
  }),
]);

/**
 * 查询原建筑投影是否碰到预留街坊，供城市在构建原基座之前过滤。
 * @param {number} x 建筑中心横坐标。
 * @param {number} z 建筑中心纵坐标。
 * @param {number} width 原建筑投影宽度。
 * @param {number} depth 原建筑投影深度。
 * @returns {boolean} 是否需要让出街坊。
 */
export function isAtlantisUnderwayReserved(x, z, width = 0, depth = 0) {
  return ATLANTIS_UNDERWAY_SITES.some(
    (site) =>
      Math.abs(x - site.x) < (site.width + width) / 2 &&
      Math.abs(z - site.z) < (site.depth + depth) / 2,
  );
}

/**
 * 构建三处上下可穿行的抬升圣所，所有实体与碰撞共用尺寸。
 * @param {THREE.Object3D} parent 场景父节点。
 * @param {{heightAt:function}} options 已有海床采样函数。
 * @returns {object} 场景、碰撞、地标、记录、统计、更新与幂等释放接口。
 */
export function createAtlantisUnderways(parent, { heightAt } = {}) {
  if (!parent?.add || typeof heightAt !== "function")
    throw new Error(
      "Atlantis underways require a parent and seabed height function",
    );
  const root = new THREE.Group();
  root.name = "atlantis_underways";
  parent.add(root);
  const owned = new Set(),
    colliders = [],
    obstacles = [],
    landmarks = [],
    records = [];
  const materials = atlantisMaterials();
  for (const site of ATLANTIS_UNDERWAY_SITES) {
    const group = new THREE.Group();
    group.name = site.id;
    root.add(group);
    const builder = new UnderwayBuilder(site, heightAt, colliders);
    const maximum = builder.floorRange(0, 0, 100, 112).max;
    const deck = maximum + 52;
    buildGallery(builder, deck, maximum);
    if (site.variant === "bridges") {
      // 双翼上殿围出真实的露天竖井，两端石桥形成上下层环游路线。
      for (const side of [-1, 1]) {
        builder.box("stone", 30, 4, 112, side * 35, deck - 2, 0);
        hall(builder, side * 35, deck, 0, 27, 94, 27, 8);
      }
      for (const z of [-46, 46])
        builder.box("marble", 40, 4, 20, 0, deck - 2, z);
    } else {
      builder.box("stone", 100, 4, 112, 0, deck - 2, 0);
      if (site.variant === "sanctuary")
        hall(builder, 0, deck, 0, 86, 88, 33, 13);
      else {
        hall(builder, 0, deck, -25, 76, 53, 30, 11);
        for (const side of [-1, 1]) {
          hall(builder, side * 36, deck, 35, 24, 30, 20, 6);
          builder.column(side * 43, deck, 6, 28, 2.2);
        }
      }
    }
    for (const x of [-49, 49])
      builder.box("marble", 2, 1.4, 112, x, deck + 0.7, 0);
    // 横向边缘压顶分开，入口保持敞开；层叠檐口、齿饰和铜嵌条继承王城语言。
    for (const z of [-55, 55]) {
      for (const x of [-37, 37])
        builder.box("marble", 26, 1.4, 2, x, deck + 0.7, z);
      builder.box("marble", 102, 1.1, 3, 0, deck - 1.3, z);
      for (let x = -47; x <= 47; x += 5)
        builder.box(
          "bronze",
          1.4,
          2.4,
          0.5,
          x,
          deck - 1.9,
          z + Math.sign(z) * 1.7,
          false,
        );
    }
    builder.bucket.build(materials, group, owned);
    group.traverse((mesh) => {
      if (!mesh.isMesh) return;
      mesh.receiveShadow = true;
      mesh.geometry.computeBoundingSphere();
    });
    const lowerY = maximum + 23;
    const record = {
      ...site,
      kind: "underway",
      y: deck,
      floorMaximum: maximum,
      lowerY,
      upperY: deck + 14,
      height: deck - maximum + 49,
      lowerRoute: [
        { x: site.x, y: lowerY, z: site.z + 69 },
        { x: site.x, y: lowerY, z: site.z - 69 },
      ],
      upperRoute: [
        { x: site.x, y: deck + 14, z: site.z + 69 },
        { x: site.x, y: deck + 14, z: site.z - 69 },
      ],
      verticalRoute:
        site.variant === "bridges"
          ? [
              { x: site.x, y: lowerY, z: site.z },
              { x: site.x, y: deck + 44, z: site.z },
            ]
          : null,
      clearWidth: 64,
      lowerClearance: 44,
      group,
    };
    records.push(record);
    landmarks.push({
      id: site.id,
      position: new THREE.Vector3(site.x, deck + 14, site.z),
    });
  }
  const stats = {
    sites: records.length,
    levels: 2,
    meshes: owned.size,
    colliders: colliders.length,
    triangles: [...owned].reduce(
      (sum, geometry) => sum + geometry.attributes.position.count / 3,
      0,
    ),
  };
  root.userData.underwayStats = stats;
  let disposed = false;
  return {
    root,
    colliders,
    obstacles,
    landmarks,
    records,
    stats,
    update(time, dt, position, highQuality = true) {
      if (disposed) return;
      for (const record of records)
        record.group.visible =
          !position ||
          Math.hypot(record.x - position.x, record.z - position.z) <
            (highQuality ? 400 : 330);
      void time;
      void dt;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      parent.remove(root);
      for (const geometry of owned) geometry.dispose();
      owned.clear();
      root.clear();
      colliders.length =
        obstacles.length =
        landmarks.length =
        records.length =
          0;
    },
  };
}

class UnderwayBuilder {
  constructor(site, heightAt, colliders) {
    this.site = site;
    this.heightAt = heightAt;
    this.colliders = colliders;
    this.bucket = new MergeBucket();
    this.ordinal = 0;
  }
  add(geometry, material, x, y, z, euler = null) {
    paintStone(geometry, {
      base:
        material === "bronze"
          ? "#668b84"
          : material === "marble"
            ? "#d3d2bc"
            : "#a6b7ae",
      algaeAmount: material === "stone" ? 0.24 : 0.12,
      seed: 319 + this.ordinal++,
    });
    this.bucket.add(geometry, material, {
      position: [this.site.x + x, y, this.site.z + z],
      euler,
      tile: material === "stone" ? 11 : 18,
    });
    geometry.dispose();
  }
  box(material, w, h, d, x, y, z, solid = true, angle = 0) {
    this.add(new THREE.BoxGeometry(w, h, d), material, x, y, z, [0, 0, angle]);
    if (solid)
      this.colliders.push({
        type: "box",
        kind: "underway_masonry",
        site: this.site.id,
        x: this.site.x + x,
        y,
        z: this.site.z + z,
        halfSize: { x: w / 2, y: h / 2, z: d / 2 },
        ...(angle
          ? {
              rotation: {
                x: 0,
                y: 0,
                z: Math.sin(angle / 2),
                w: Math.cos(angle / 2),
              },
            }
          : {}),
      });
  }
  floorRange(x, z, w, d) {
    const samples = [];
    for (let ix = 0; ix <= 4; ix++)
      for (let iz = 0; iz <= 4; iz++)
        samples.push(
          this.heightAt(
            this.site.x + x + (ix / 4 - 0.5) * w,
            this.site.z + z + (iz / 4 - 0.5) * d,
          ),
        );
    return { min: Math.min(...samples), max: Math.max(...samples) };
  }
  column(x, y, z, height, radius) {
    this.box("marble", radius * 3, 1, radius * 3, x, y + 0.5, z);
    const shaft = loftGeometry(
      null,
      [
        { y: 0, rx: radius, rz: radius, wave: 20, waveAmp: 0.07 },
        {
          y: height * 0.5,
          rx: radius * 0.94,
          rz: radius * 0.94,
          wave: 20,
          waveAmp: 0.07,
        },
        {
          y: height - 2,
          rx: radius * 0.8,
          rz: radius * 0.8,
          wave: 20,
          waveAmp: 0.07,
        },
      ],
      { radial: 24, subdivision: 0.25, capStart: true, capEnd: true },
    );
    this.add(shaft, "marble", x, y + 1, z);
    this.colliders.push({
      type: "capsule",
      kind: "underway_column",
      site: this.site.id,
      a: { x: this.site.x + x, y: y + radius, z: this.site.z + z },
      b: { x: this.site.x + x, y: y + height - radius, z: this.site.z + z },
      radius: radius * 1.05,
    });
    this.box("marble", radius * 3, 1, radius * 3, x, y + height - 0.5, z);
    for (const sign of [-1, 1])
      this.add(
        new THREE.TorusGeometry(radius * 0.5, radius * 0.14, 6, 16),
        "marble",
        x + sign * radius,
        y + height - 1.2,
        z + radius,
      );
    for (const dy of [1.1, height - 1.4])
      this.add(
        new THREE.CylinderGeometry(radius * 1.15, radius * 1.2, 0.45, 24),
        "marble",
        x,
        y + dy,
        z,
      );
  }
  arch(z, spring, radius) {
    const thickness = 3.2,
      count = 25,
      mid = radius + thickness / 2;
    for (let i = 0; i < count; i++) {
      const angle = ((i + 0.5) / count) * Math.PI;
      this.box(
        "marble",
        thickness,
        ((Math.PI * mid) / count) * 1.025,
        5,
        Math.cos(angle) * mid,
        spring + Math.sin(angle) * mid,
        z,
        true,
        angle,
      );
    }
    for (const side of [-1, 1])
      this.box(
        "bronze",
        3,
        3.5,
        0.6,
        side * 16,
        spring + radius - 1,
        z + Math.sign(z) * 2.85,
        false,
      );
  }
}

/** 下廊只放独立支墩，桥面以下始终没有整面碰撞盒。 */
function buildGallery(b, deck, maximum) {
  for (const x of [-44, 44])
    for (const z of [-46, 0, 46]) {
      const sample = b.floorRange(x, z, 11, 11),
        bottom = sample.min - 2,
        footing = sample.max + 2.4;
      b.box("stone", 11, footing - bottom, 11, x, (footing + bottom) / 2, z);
      b.column(x, footing, z, deck - footing - 2, 3.4);
      // 竖向壁柱和腰线与独立墩基重合，不填入中间通道。
      for (let y = footing + 7; y < deck - 4; y += 9) {
        const radius = 3.5 * (1 - (0.2 * (y - footing)) / (deck - footing));
        b.add(
          new THREE.CylinderGeometry(radius, radius, 0.25, 28),
          "bronze",
          x,
          y,
          z,
        );
      }
    }
  for (const z of [-46, 46]) {
    b.arch(z, deck - 44, 38);
    b.box("marble", 100, 3, 8, 0, deck - 2.5, z);
  }
  for (const x of [-44, 44]) b.box("marble", 8, 3, 106, x, deck - 2.5, 0);
  // 巨拱背后的斗拱传力到柱头；两端均留有真实贯通洞口。
  for (const side of [-1, 1])
    for (const z of [-46, 46]) b.box("stone", 9, 8, 6, side * 43, deck - 7, z);
  void maximum;
}

/** 上殿使用带凹槽柱、双层檐口、三角山墙和石屋面，四面透空。 */
function hall(b, cx, floor, cz, width, depth, height, rise) {
  const xEdge = width / 2 - 4,
    zEdge = depth / 2 - 4;
  for (const side of [-1, 1])
    for (const z of [-zEdge, 0, zEdge])
      b.column(
        cx + side * xEdge,
        floor,
        cz + z,
        height,
        width < 40 ? 1.6 : 2.3,
      );
  for (const x of [-xEdge, xEdge])
    b.box("marble", 5, 2.5, depth, cx + x, floor + height + 0.7, cz);
  for (const z of [-zEdge, zEdge]) {
    b.box("marble", width, 2.5, 5, cx, floor + height + 0.7, cz + z);
    for (let x = -width / 2 + 2; x < width / 2; x += 3.5)
      b.box(
        "marble",
        0.7,
        1,
        1.1,
        cx + x,
        floor + height - 0.8,
        cz + z + Math.sign(z) * 2.4,
        false,
      );
  }
  const roofBase = floor + height + 2.2;
  // 两片斜屋面使用相同旋转盒碰撞，不能用覆盖整座殿堂的隐形矩形。
  const slope = Math.atan2(rise, width / 2),
    span = Math.hypot(width / 2, rise);
  for (const side of [-1, 1])
    b.box(
      "stone",
      span + 1.1,
      2,
      depth + 3,
      cx + (side * width) / 4,
      roofBase + rise / 2,
      cz,
      true,
      -side * slope,
    );
  for (const z of [-depth / 2, depth / 2]) {
    const shape = new THREE.Shape();
    shape.moveTo(-width / 2, 0);
    shape.lineTo(width / 2, 0);
    shape.lineTo(0, rise);
    shape.closePath();
    b.add(
      new THREE.ExtrudeGeometry(shape, {
        depth: 1.3,
        bevelEnabled: false,
        steps: 1,
      }),
      "marble",
      cx,
      roofBase,
      cz + z - 0.65,
    );
    // 分条山墙碰撞贴合三角形，不遮挡斜屋面上方的游动空间。
    for (let i = 0; i < 20; i++) {
      const x = -width / 2 + ((i + 0.5) * width) / 20,
        h = rise * (1 - Math.abs(x) / (width / 2));
      b.colliders.push({
        type: "box",
        kind: "underway_pediment",
        site: b.site.id,
        x: b.site.x + cx + x,
        y: roofBase + h / 2,
        z: b.site.z + cz + z,
        halfSize: { x: width / 40, y: h / 2, z: 0.65 },
      });
    }
    b.add(
      new THREE.TorusGeometry(Math.min(rise * 0.27, 3), 0.3, 8, 28),
      "bronze",
      cx,
      roofBase + rise * 0.4,
      cz + z + Math.sign(z) * 0.9,
    );
    for (const side of [-1, 1])
      b.box(
        "marble",
        span + 1,
        0.7,
        2,
        cx + (side * width) / 4,
        roofBase + rise / 2 + 0.7,
        cz + z,
        false,
        -side * slope,
      );
  }
  b.box("marble", 1.8, 1.6, depth + 4, cx, roofBase + rise + 0.3, cz);
}

