// 世界尺度集中管理，显示深度为世界深度的四倍。
export const WORLD = Object.freeze({
  minX: -300,
  maxX: 300,
  minZ: -1150,
  maxZ: 140,
  maxDepth: 740,
  surfaceY: 4,
  displayDepthScale: 4,
});
